#[test]
fn point_after_large_fold_keeps_visually_valid_window_start() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let hidden = (0..80)
        .map(|index| format!("hidden state {index}\n"))
        .collect::<String>();
    let text = format!("heading\n:LOGBOOK:\n{hidden}:END:\nafter\nnext\n");
    let hidden_start = text.find("hidden state").expect("hidden start");
    let hidden_end = text.find(":END:").expect("hidden end");
    let after = text.find("after").expect("after");
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(&text);
        buf.set_buffer_local(
            "buffer-invisibility-spec",
            Value::list(vec![Value::cons(Value::symbol("folded"), Value::T)]),
        );
        assert!(buf.put_text_property(
            hidden_start,
            hidden_end,
            Value::symbol("invisible"),
            Value::symbol("folded"),
        ));
        buf.goto_emacs_byte_pos(EmacsBytePos::new(0));
    }
    let frame_id =
        eval.frame_manager_mut()
            .create_frame("point-after-large-fold", 640, 120, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    eval.buffer_manager_mut()
        .goto_buffer_emacs_byte_pos(buf_id, EmacsBytePos::new(after));
    let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
    let neovm_core::window::Window::Leaf { point, .. } = frame
        .find_window_mut(selected_window)
        .expect("selected window")
    else {
        panic!("selected window is not a leaf");
    };
    *point = LispCharPos1::new((after + 1) as i64);
    engine.layout_frame_rust(&mut eval, frame_id);

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let neovm_core::window::Window::Leaf { window_start, .. } =
        frame.find_window(selected_window).expect("selected window")
    else {
        panic!("selected window is not a leaf");
    };
    assert_eq!(
        *window_start,
        LispCharPos1::ONE,
        "hidden logical lines must not recenter a visually visible point into the fold"
    );
}

#[test]
fn visibility_retry_never_places_window_start_inside_unmeasured_fold() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let prefix = (0..12)
        .map(|index| format!("visible prefix {index}\n"))
        .collect::<String>();
    let hidden = (0..80)
        .map(|index| format!("hidden state {index}\n"))
        .collect::<String>();
    let text = format!("{prefix}{hidden}after\nnext\n");
    let hidden_start = prefix.len();
    let hidden_end = hidden_start + hidden.len();
    let after = hidden_end;
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(&text);
        buf.set_buffer_local(
            "buffer-invisibility-spec",
            Value::list(vec![Value::cons(Value::symbol("folded"), Value::T)]),
        );
        assert!(buf.put_text_property(
            hidden_start,
            hidden_end,
            Value::symbol("invisible"),
            Value::symbol("folded"),
        ));
        buf.goto_emacs_byte_pos(EmacsBytePos::new(0));
    }
    let frame_id = eval.frame_manager_mut().create_frame(
        "visibility-retry-across-large-fold",
        640,
        120,
        buf_id,
    );
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    eval.buffer_manager_mut()
        .goto_buffer_emacs_byte_pos(buf_id, EmacsBytePos::new(after));
    let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
    let neovm_core::window::Window::Leaf { point, .. } = frame
        .find_window_mut(selected_window)
        .expect("selected window")
    else {
        panic!("selected window is not a leaf");
    };
    *point = LispCharPos1::new((after + 1) as i64);
    engine.layout_frame_rust(&mut eval, frame_id);

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let neovm_core::window::Window::Leaf { window_start, .. } =
        frame.find_window(selected_window).expect("selected window")
    else {
        panic!("selected window is not a leaf");
    };
    let start_byte = window_start.as_i64() as usize - 1;
    assert!(
        start_byte <= hidden_start || start_byte >= hidden_end,
        "the retry must advance through measured display rows, not raw source lines; \
         window-start={window_start:?}, hidden={hidden_start}..{hidden_end}"
    );
    assert!(
        engine
            .last_frame_display_state
            .as_ref()
            .and_then(|state| state.phys_cursor.as_ref())
            .is_some(),
        "the accepted retry must make point visibly placeable"
    );
}

/// GNU keeps row measurement separate from the viewport decision: a replacing
/// `display` property can force xdisp to walk real display rows, but it does not
/// change what `scroll-conservatively` means.  Telega exercises this whenever
/// sending a message replaces its prompt/message cells between the retained
/// visible end and point.
#[test]
fn replacing_display_measurement_preserves_conservative_bottom_scroll() {
    let layout_after_tail_insert = |with_replacement: bool| {
        let mut eval = Context::new();
        let buf_id = eval
            .buffer_manager()
            .current_buffer()
            .expect("current buffer")
            .id();
        let history = (0..120)
            .map(|index| format!("message {index:03}\n"))
            .collect::<String>();
        let prompt = ">>> ";
        let text = format!("{history}{prompt}");
        {
            let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
            buf.insert(&text);
            buf.set_buffer_local("scroll-conservatively", Value::fixnum(101));
            buf.goto_emacs_byte_pos(EmacsBytePos::new(text.len()));
        }
        let frame_id = eval.frame_manager_mut().create_frame(
            "conservative-scroll-across-display-replacement",
            640,
            224,
            buf_id,
        );
        let selected_window = eval
            .frame_manager()
            .get(frame_id)
            .expect("frame")
            .selected_window;
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        let neovm_core::window::Window::Leaf { point, .. } = frame
            .find_window_mut(selected_window)
            .expect("selected window")
        else {
            panic!("selected window is not a leaf");
        };
        *point = LispCharPos1::from_one_based_usize(text.len() + 1);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);

        let insert_at = history.len();
        let inserted = "sent message\n";
        let target = text.len() + inserted.len();
        if with_replacement {
            eval.eval_str(
                "(progn
                   (setq neomacs-viewport-scroll-log nil)
                   (make-local-variable 'window-scroll-functions)
                   (setq window-scroll-functions
                         (list (lambda (_window start)
                                 (setq neomacs-viewport-scroll-log
                                       (cons start neomacs-viewport-scroll-log))))))",
            )
            .expect("install viewport publication observer");
            assert!(
                eval.window_scroll_functions_may_run(selected_window),
                "the buffer-local observer must be visible to redisplay"
            );
        }
        {
            let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
            buf.goto_emacs_byte_pos(EmacsBytePos::new(insert_at));
            buf.insert(inserted);
            if with_replacement {
                assert!(buf.put_text_property(
                    insert_at,
                    insert_at + inserted.len(),
                    Value::symbol("display"),
                    Value::string(inserted),
                ));
            }
            buf.goto_emacs_byte_pos(EmacsBytePos::new(target));
        }
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        let neovm_core::window::Window::Leaf { point, .. } = frame
            .find_window_mut(selected_window)
            .expect("selected window")
        else {
            panic!("selected window is not a leaf");
        };
        *point = LispCharPos1::from_one_based_usize(target + 1);

        engine.layout_frame_rust(&mut eval, frame_id);
        let trace = selected_window_layout_trace(&eval, &engine, frame_id);
        if with_replacement {
            let hook_count = eval
                .eval_str("(length neomacs-viewport-scroll-log)")
                .expect("read viewport publication count")
                .as_fixnum()
                .expect("publication count");
            let published_starts = eval
                .eval_str("(format \"%S\" neomacs-viewport-scroll-log)")
                .expect("read published viewport starts")
                .as_str_owned()
                .expect("published starts");
            assert_eq!(
                hook_count, 1,
                "measurement probes must not run window-scroll-functions"
            );
            assert_eq!(
                published_starts,
                format!("({})", trace.window_start.as_i64()),
                "only the final policy-approved viewport may be published"
            );
        }
        trace
    };

    let plain = layout_after_tail_insert(false);
    let replacing = layout_after_tail_insert(true);

    assert_eq!(
        replacing.window_start, plain.window_start,
        "measurement uncertainty must not turn into a page-sized viewport commit"
    );
    let plain_cursor = plain.phys_cursor.as_ref().expect("plain cursor");
    let replacing_cursor = replacing.phys_cursor.as_ref().expect("replacement cursor");
    let plain_last_row = plain
        .output_rows
        .iter()
        .map(|row| row.row)
        .max()
        .expect("plain body rows");
    let replacing_last_row = replacing
        .output_rows
        .iter()
        .map(|row| row.row)
        .max()
        .expect("replacement body rows");
    assert!(
        plain_last_row - plain_cursor.row <= 1,
        "control cursor should occupy the last fully visible row"
    );
    assert!(
        replacing_last_row - replacing_cursor.row <= 1,
        "replacement cursor should occupy the last fully visible row"
    );
    assert_eq!(
        replacing_cursor.row, plain_cursor.row,
        "scroll-conservatively > 100 should keep point on the bottom row"
    );
}

/// One describe-char scenario run: chat buffer with an image-bearing reply
/// row, point placed per `point_mode`, then a Help-style vertical split.
/// Returns the max nested `layout_window_rust` depth observed.
fn run_describe_char_scenario(
    conservatively: i64,
    point_mode: &str,
    image_height: i64,
    wrapped_paragraph: bool,
) -> (usize, usize) {
    let mut eval = Context::new();
    let requests = Arc::new(Mutex::new(Vec::new()));
    eval.set_display_host(Box::new(RecordingImageDisplayHost {
        requests: Arc::clone(&requests),
        video_requests: Arc::new(Mutex::new(Vec::new())),
        webkit_requests: Arc::new(Mutex::new(Vec::new())),
        surface_requests: Arc::new(Mutex::new(Vec::new())),
    }));
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let image_spec = Value::list(vec![
        Value::symbol("image"),
        Value::keyword("type"),
        Value::symbol("png"),
        Value::keyword("file"),
        Value::string("/tmp/neomacs-inline-image.png"),
        Value::keyword("max-width"),
        Value::fixnum(32),
        Value::keyword("max-height"),
        Value::fixnum(image_height),
    ]);
    let prefix = Value::string_with_text_properties(
        "@@",
        vec![StringTextPropertyRun {
            start: 0,
            end: 2,
            plist: Value::list(vec![Value::symbol("display"), image_spec.clone()]),
        }],
    );
    let reply_line = " azz> grok build/grok cli/grok agent/grok bot\n";
    let context_line = "description context line 000\n";
    let image_char;
    let point_byte;
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("scroll-conservatively", Value::fixnum(conservatively));
        let mut text = String::new();
        for line in 0..24 {
            text.push_str(&format!("preceding chat line {line:03}\n"));
        }
        image_char = text.len();
        text.push('↩');
        text.push_str(reply_line);
        if wrapped_paragraph {
            for word in 0..120 {
                text.push_str(&format!("wrapped filler word {word:03} "));
            }
            text.push('\n');
        }
        for line in 0..140 {
            text.push_str(&format!("description context line {line:03}\n"));
        }
        buf.insert(&text);
        assert!(buf.put_text_property(
            image_char,
            image_char + '↩'.len_utf8(),
            Value::symbol("display"),
            image_spec,
        ));
        assert!(buf.put_text_property(
            image_char,
            image_char + '↩'.len_utf8(),
            Value::symbol("line-prefix"),
            prefix.clone(),
        ));
        assert!(buf.put_text_property(
            image_char,
            image_char + '↩'.len_utf8(),
            Value::symbol("wrap-prefix"),
            prefix,
        ));
        point_byte = match point_mode {
            "at-image" => image_char,
            "line-end" => image_char + '↩'.len_utf8() + reply_line.len(),
            "below-image" => {
                image_char + '↩'.len_utf8() + reply_line.len() + 10 * context_line.len()
            }
            other => panic!("unknown point_mode {other}"),
        };
        buf.goto_emacs_byte_pos(EmacsBytePos::new(point_byte));
    }
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("probe-describe-char", 640, 448, buf_id);
    let selected = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    let mut engine = LayoutEngine::new();
    super::viewport_retry_depth_probe::reset();
    engine.layout_frame_rust(&mut eval, frame_id);
    let after_initial = super::viewport_retry_depth_probe::max_depth();

    // *Help* opens below the source window, resizing it mid-session.
    eval.frame_manager_mut()
        .split_window(
            frame_id,
            selected,
            neovm_core::window::SplitDirection::Vertical,
            buf_id,
            None,
            neovm_core::window::SplitPlacement::AfterTarget,
        )
        .expect("help window");
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        let neovm_core::window::Window::Leaf { point, .. } =
            frame.find_window_mut(selected).expect("source window")
        else {
            panic!("source window is not a leaf");
        };
        *point = LispCharPos1::from_one_based_usize(point_byte + 1);
    }
    super::viewport_retry_depth_probe::reset();
    engine.layout_frame_rust(&mut eval, frame_id);
    let after_split = super::viewport_retry_depth_probe::max_depth();

    (after_initial, after_split)
}

/// Help-window variant: describe-char's `*Help*` buffer contains a copy of
/// the image display property, and its point sits at EOB beyond the small
/// Help window's visible span.  Returns max nested depth over both windows.
fn run_help_window_scenario(conservatively: i64) -> usize {
    let mut eval = Context::new();
    let requests = Arc::new(Mutex::new(Vec::new()));
    eval.set_display_host(Box::new(RecordingImageDisplayHost {
        requests: Arc::clone(&requests),
        video_requests: Arc::new(Mutex::new(Vec::new())),
        webkit_requests: Arc::new(Mutex::new(Vec::new())),
        surface_requests: Arc::new(Mutex::new(Vec::new())),
    }));
    let chat_buf = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let image_spec = Value::list(vec![
        Value::symbol("image"),
        Value::keyword("type"),
        Value::symbol("png"),
        Value::keyword("file"),
        Value::string("/tmp/neomacs-inline-image.png"),
        Value::keyword("max-width"),
        Value::fixnum(32),
        Value::keyword("max-height"),
        Value::fixnum(18),
    ]);
    let chat_image;
    let help_image;
    let help_end;
    {
        let buf = eval.buffer_manager_mut().get_mut(chat_buf).expect("buffer");
        buf.set_buffer_local("scroll-conservatively", Value::fixnum(conservatively));
        let mut text = String::new();
        for line in 0..24 {
            text.push_str(&format!("preceding chat line {line:03}\n"));
        }
        chat_image = text.len();
        text.push('↩');
        text.push_str(" azz> grok build/grok cli/grok agent/grok bot\n");
        for line in 0..140 {
            text.push_str(&format!("description context line {line:03}\n"));
        }
        buf.insert(&text);
        assert!(buf.put_text_property(
            chat_image,
            chat_image + '↩'.len_utf8(),
            Value::symbol("display"),
            image_spec.clone(),
        ));
        buf.goto_emacs_byte_pos(EmacsBytePos::new(chat_image));
    }
    let help_buf = eval.buffer_manager_mut().create_buffer("*Help*");
    {
        let buf = eval
            .buffer_manager_mut()
            .get_mut(help_buf)
            .expect("help buffer");
        buf.set_buffer_local("scroll-conservatively", Value::fixnum(conservatively));
        let mut text = String::new();
        for line in 0..8 {
            text.push_str(&format!("help header line {line:03}\n"));
        }
        help_image = text.len();
        text.push('↩');
        text.push_str(" display: (image ...)\n");
        for line in 0..60 {
            text.push_str(&format!(
                "help body line {line:03} with more words to wrap\n"
            ));
        }
        help_end = text.len();
        buf.insert(&text);
        assert!(buf.put_text_property(
            help_image,
            help_image + '↩'.len_utf8(),
            Value::symbol("display"),
            image_spec,
        ));
        buf.goto_emacs_byte_pos(EmacsBytePos::new(help_end));
    }
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("probe-help-window", 640, 448, chat_buf);
    let selected = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    // *Help* opens below the source window on its own buffer.
    let help_window = eval
        .frame_manager_mut()
        .split_window(
            frame_id,
            selected,
            neovm_core::window::SplitDirection::Vertical,
            help_buf,
            None,
            neovm_core::window::SplitPlacement::AfterTarget,
        )
        .expect("help window");
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        let neovm_core::window::Window::Leaf { point, .. } =
            frame.find_window_mut(selected).expect("source window")
        else {
            panic!("source window is not a leaf");
        };
        *point = LispCharPos1::from_one_based_usize(chat_image + 1);
        let neovm_core::window::Window::Leaf { point, .. } =
            frame.find_window_mut(help_window).expect("help window")
        else {
            panic!("help window is not a leaf");
        };
        *point = LispCharPos1::from_one_based_usize(help_end + 1);
    }
    let mut engine = LayoutEngine::new();
    super::viewport_retry_depth_probe::reset();
    engine.layout_frame_rust(&mut eval, frame_id);
    super::viewport_retry_depth_probe::max_depth()
}

/// REGRESSION (telega describe-char evaluator stack overflow): the viewport
/// visibility retry must consume *iterations*, never nested
/// `layout_window_rust` frames.  Each frame is large (image parsing, font
/// resolution, row walks); the recursive architecture overflowed the
/// profiling evaluator's stack at ~30 nested placement attempts, far below
/// the nominal retry budget.
///
/// Sweeps the geometry around the crash: scroll-conservatively, point
/// position, image height, wrapped paragraphs, plus a `*Help*`-window
/// variant — and asserts that no scenario nests layout at all.
#[tracing_test::traced_test]
#[test]
fn viewport_retries_iterate_without_nesting_layout_window_rust() {
    let mut report = Vec::new();
    let mut worst = 0usize;
    for conservatively in [0i64, 101i64] {
        for point_mode in ["at-image", "line-end", "below-image"] {
            for image_height in [18i64, 40i64] {
                for wrapped_paragraph in [false, true] {
                    let (initial, split) = run_describe_char_scenario(
                        conservatively,
                        point_mode,
                        image_height,
                        wrapped_paragraph,
                    );
                    report.push(format!(
                        "c={conservatively} {point_mode:>11} img_h={image_height:>2} \
                         wrapped={wrapped_paragraph:<5} depth initial={initial} split={split}"
                    ));
                    worst = worst.max(initial).max(split);
                }
            }
        }
    }
    for conservatively in [0i64, 101i64] {
        let help_depth = run_help_window_scenario(conservatively);
        report.push(format!(
            "c={conservatively} help-window depth split={help_depth}"
        ));
        worst = worst.max(help_depth);
    }
    for line in &report {
        eprintln!("PROBE {line}");
    }
    assert_eq!(
        worst, 1,
        "viewport retries must consume iterations, never nested \
         layout_window_rust frames; worst depth={worst} across {report:?}"
    );
}

#[test]
fn distant_point_with_unrelated_overlay_does_not_exhaust_visibility_retries() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let text = (0..1_200)
        .map(|index| format!("ordinary line {index}\n"))
        .collect::<String>();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(&text);
        buf.goto_emacs_byte_pos(EmacsBytePos::new(0));
    }
    eval.eval_str("(overlay-put (make-overlay 1 2) 'face 'bold)")
        .expect("install unrelated face overlay");
    let frame_id =
        eval.frame_manager_mut()
            .create_frame("distant-point-with-face-overlay", 640, 120, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let point = text.rfind("ordinary line").expect("last line");
    eval.buffer_manager_mut()
        .goto_buffer_emacs_byte_pos(buf_id, EmacsBytePos::new(point));
    let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
    let neovm_core::window::Window::Leaf {
        point: window_point,
        ..
    } = frame
        .find_window_mut(selected_window)
        .expect("selected window")
    else {
        panic!("selected window is not a leaf");
    };
    *window_point = LispCharPos1::new((point + 1) as i64);
    engine.layout_frame_rust(&mut eval, frame_id);

    assert!(
        engine
            .last_frame_display_state
            .as_ref()
            .and_then(|state| state.phys_cursor.as_ref())
            .is_some(),
        "a non-display overlay must not turn an ordinary jump into more than \
         MAX_WINDOW_VISIBILITY_RETRIES screen-at-a-time retries"
    );
}

#[test]
fn layout_frame_rust_renders_invisible_ellipsis_through_row_builder() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("abc hidden xyz");
        buf.set_buffer_local(
            "buffer-invisibility-spec",
            Value::list(vec![Value::cons(Value::symbol("folded"), Value::T)]),
        );
        let start = "abc ".len();
        let end = start + "hidden".len();
        assert!(buf.put_text_property(
            start,
            end,
            Value::symbol("invisible"),
            Value::symbol("folded"),
        ));
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-invisible-ellipsis", 640, 160, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("text row");
    let logical_text = glyphs_logical_text(&text_row.glyphs[1]);

    assert_eq!(logical_text, "abc ... xyz");
    assert!(
        text_row.glyphs[1]
            .iter()
            .filter(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: '.' }))
            .all(|glyph| (glyph.pixel_width - 8.0).abs() <= 0.01),
        "ellipsis dots should carry measured pixel widths, row={:?}",
        text_row.glyphs[1]
    );
}

#[test]
fn buffer_remapped_default_gets_distinct_face_for_leading_invisible_ellipsis() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("hidden visible");
        buf.set_buffer_local(
            "face-remapping-alist",
            Value::list(vec![Value::list(vec![
                Value::symbol("default"),
                Value::list(vec![
                    Value::keyword("family"),
                    Value::string("Noto Sans CJK SC"),
                ]),
                Value::symbol("default"),
            ])]),
        );
        buf.set_buffer_local(
            "buffer-invisibility-spec",
            Value::list(vec![Value::cons(Value::symbol("folded"), Value::T)]),
        );
        assert!(buf.put_text_property(
            0,
            "hidden".len(),
            Value::symbol("invisible"),
            Value::symbol("folded"),
        ));
    }

    let frame_id = eval.frame_manager_mut().create_frame(
        "layout-remapped-default-leading-invisible",
        640,
        160,
        buf_id,
    );
    realize_test_gui_frame(&mut eval, frame_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("text row");
    let ellipsis_face_ids = text_row.glyphs[GlyphArea::Text.index()]
        .iter()
        .filter_map(|glyph| {
            matches!(glyph.glyph_type, GlyphType::Char { ch: '.' }).then_some(glyph.face_id)
        })
        .collect::<std::collections::BTreeSet<_>>();

    assert_eq!(
        ellipsis_face_ids.len(),
        1,
        "one remapped default face should own the leading ellipsis"
    );
    let ellipsis_face_id = *ellipsis_face_ids.first().expect("ellipsis face");
    assert_ne!(
        ellipsis_face_id,
        FaceId::from(neomacs_display_protocol::face::BasicFaceId::Default),
        "GNU lookup_basic_face gives a buffer-remapped default its realized face id"
    );
    assert_eq!(
        state.faces[&ellipsis_face_id].font_family,
        "Noto Sans CJK SC"
    );
}

#[test]
fn implemented_text_backends_match_layout_frame_multiline_overlay_output() {
    let baseline = multiline_overlay_backend_layout_trace(BufferTextBackendKind::GapBuffer);
    let rows = trace_text_rows(&baseline);
    assert!(
        rows.iter().any(|row| row.contains("xA")),
        "baseline should render overlay after-string suffix on the source row, rows={rows:?}"
    );
    assert!(
        rows.iter().any(|row| row.contains('B')),
        "baseline should render multiline overlay continuation row, rows={rows:?}"
    );
    assert!(
        baseline.output_rows.iter().any(|row| row.row == 1),
        "baseline should publish a second output row for multiline overlay, rows={:?}",
        baseline.output_rows
    );

    for kind in implemented_text_backends() {
        let trace = multiline_overlay_backend_layout_trace(kind);
        assert_eq!(trace, baseline, "{kind:?}");
    }
}

