/// GNU renders control-character substitute glyphs (`^A`, `\003`, ...) in a
/// face that merges the `escape-glyph` face over the surrounding base face
/// (`merge_escape_glyph_face` -> `merge_faces(w, Qescape_glyph, 0,
/// it->face_id)`, xdisp.c:8372-8389). The single merged face id is stamped
/// onto BOTH the `^` glyph and the caret letter (`dpvec_face_id`, xdisp.c:8663).
///
/// This test pins the RENDERED-glyph foreground (the guard the prior latent
/// groundwork lacked): both `^` and `A` must resolve to the escape-glyph
/// foreground, not the default text foreground, while the surrounding plain
/// `a`/`b` keep the base face.
#[test]
fn layout_frame_rust_control_char_caret_uses_escape_glyph_foreground() {
    use neomacs_display_protocol::types::Color;

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("a\u{0001}b\n");
    }

    // GNU's cyan-on-dark escape-glyph color (#46D9FF), used by the Doom GUI
    // repro. Defined through the Lisp face machinery so it survives the
    // per-frame face sync (`sync_runtime_faces_for_frame`) that layout runs.
    let escape_fg = Color::from_pixel((0x46u32 << 16) | (0xD9u32 << 8) | 0xFFu32);

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-control-char-escape-glyph", 640, 160, buf_id);
    // Window-system frame: GNU only paints escape-glyph faces in graphical
    // redisplay; a TTY frame collapses many face distinctions.
    if let Some(frame) = eval.frame_manager_mut().get_mut(frame_id) {
        frame.set_window_system(Some(Value::symbol("neo")));
    }
    assert!(eval.frame_manager_mut().select_frame(frame_id));
    let results = eval.eval_str_each(
        "(internal-set-lisp-face-attribute 'escape-glyph :foreground \"#46D9FF\" (selected-frame))",
    );
    assert!(
        results.iter().all(Result::is_ok),
        "escape-glyph face must accept a foreground, got {results:?}"
    );
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.displays_text)
        .expect("text row");
    let text_glyphs = &text_row.glyphs[GlyphArea::Text.index()];

    // The control char produced the caret "^A" (proves the ControlChar path ran).
    assert!(
        glyphs_logical_text(text_glyphs).contains("^A"),
        "control char should render as ^A, got {:?}",
        glyphs_logical_text(text_glyphs)
    );

    let caret = text_glyphs
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: '^' }))
        .expect("caret '^' glyph");
    let caret_letter = text_glyphs
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: 'A' }))
        .expect("caret letter 'A' glyph");
    let plain_a = text_glyphs
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: 'a' }))
        .expect("plain 'a' glyph");

    // GNU stamps ONE merged face id on both substitute glyphs.
    assert_eq!(
        caret.face_id, caret_letter.face_id,
        "the '^' and caret letter must share one escape-glyph-merged face id"
    );
    // ...and it is distinct from the surrounding base text face.
    assert_ne!(
        caret.face_id, plain_a.face_id,
        "escape glyph must realize a separate face, not reuse the base text face"
    );

    // THE guard the prior groundwork lacked: the caret's RESOLVED foreground is
    // the escape-glyph color, not the default text foreground.
    let caret_face = state
        .faces
        .get(&caret.face_id)
        .expect("escape-glyph face must be registered in the frame face table");
    assert_eq!(
        caret_face.foreground, escape_fg,
        "caret '^' fg must be the escape-glyph foreground, got {:?}",
        caret_face.foreground
    );
    let caret_letter_face = state
        .faces
        .get(&caret_letter.face_id)
        .expect("escape-glyph face for caret letter");
    assert_eq!(
        caret_letter_face.foreground, escape_fg,
        "caret letter 'A' fg must be the escape-glyph foreground"
    );

    // And it differs from the plain text face's foreground (override applied).
    let base_face = state
        .faces
        .get(&plain_a.face_id)
        .expect("base text face for 'a'");
    assert_ne!(
        caret_face.foreground, base_face.foreground,
        "escape glyph fg must differ from the default text fg"
    );
}

/// Sibling guard: ordinary (non-control) text glyphs keep the surrounding base
/// face -- the escape-glyph merge must NOT leak onto normal characters.
#[test]
fn layout_frame_rust_normal_text_keeps_base_face_not_escape_glyph() {
    use neomacs_display_protocol::types::Color;

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("a\u{0001}b\n");
    }
    {
        let table = eval.face_table_mut();
        let mut escape = neovm_core::face::Face::new("escape-glyph");
        escape.foreground = Some(neovm_core::face::Color::rgb(0x46, 0xD9, 0xFF));
        table.define("escape-glyph", escape);
    }
    let escape_fg = Color::from_pixel((0x46u32 << 16) | (0xD9u32 << 8) | 0xFFu32);

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-normal-text-base-face", 640, 160, buf_id);
    if let Some(frame) = eval.frame_manager_mut().get_mut(frame_id) {
        frame.set_window_system(Some(Value::symbol("neo")));
    }
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.displays_text)
        .expect("text row");
    let text_glyphs = &text_row.glyphs[GlyphArea::Text.index()];

    let default_face_id = FaceId::from(neomacs_display_protocol::face::BasicFaceId::Default);
    let default_fg = state
        .faces
        .get(&default_face_id)
        .expect("default face")
        .foreground;

    for ch in ['a', 'b'] {
        let glyph = text_glyphs
            .iter()
            .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: c } if c == ch))
            .unwrap_or_else(|| panic!("plain '{ch}' glyph"));
        let face = state
            .faces
            .get(&glyph.face_id)
            .unwrap_or_else(|| panic!("resolved face for '{ch}'"));
        assert_eq!(
            face.foreground, default_fg,
            "normal text '{ch}' must keep the default base foreground, not escape-glyph"
        );
        assert_ne!(
            face.foreground, escape_fg,
            "normal text '{ch}' must NOT take the escape-glyph foreground"
        );
    }
}

/// GNU `get_next_display_element` (xdisp.c:8594-8603) merges the `nobreak-space`
/// face over the surrounding base face for a non-ASCII space (e.g. nbsp U+00A0)
/// when `nobreak-char-display` is `t` (the default), painting the substitute
/// glyph in the merged face -- `merge_faces (it->w, Qnobreak_space, 0,
/// it->face_id)`. `nobreak-space` inherits `escape-glyph`, so when escape-glyph
/// carries a themed foreground the nbsp glyph resolves to it.
///
/// This pins the RENDERED-glyph foreground: the nbsp substitute must resolve to
/// the (escape-glyph-inherited) nobreak-space foreground, distinct from the
/// surrounding base face -- while an adjacent NORMAL space keeps the base face.
#[test]
fn layout_frame_rust_nbsp_uses_nobreak_space_foreground() {
    use neomacs_display_protocol::types::Color;

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        // `a`, normal space, nbsp, `c`. The normal space is the base-face control
        // case; the nbsp must get the nobreak-space face.
        buf.insert("a \u{00A0}c\n");
    }

    // GNU's cyan-on-dark escape-glyph color (#46D9FF). `nobreak-space` inherits
    // escape-glyph, so the nbsp glyph must resolve to this color WITHOUT
    // nobreak-space setting its own foreground -- proving the `:inherit` chain
    // flows through `merge_named_face_over`. Defined through the Lisp face
    // machinery so it survives the per-frame face sync.
    let nbsp_fg = Color::from_pixel((0x46u32 << 16) | (0xD9u32 << 8) | 0xFFu32);

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-nbsp-nobreak-space", 640, 160, buf_id);
    // Window-system frame: GNU only paints nobreak faces in graphical redisplay.
    if let Some(frame) = eval.frame_manager_mut().get_mut(frame_id) {
        frame.set_window_system(Some(Value::symbol("neo")));
    }
    assert!(eval.frame_manager_mut().select_frame(frame_id));
    // Set escape-glyph's foreground and wire `nobreak-space :inherit
    // escape-glyph` (faces.el's defface, which the bare test context does not
    // load). The nbsp glyph must then resolve to the escape-glyph color WITHOUT
    // nobreak-space setting its own foreground -- proving the `:inherit` chain
    // flows through `merge_named_face_over`.
    let results = eval.eval_str_each(
        "(internal-set-lisp-face-attribute 'escape-glyph :foreground \"#46D9FF\" (selected-frame))\
         (internal-set-lisp-face-attribute 'nobreak-space :inherit 'escape-glyph (selected-frame))",
    );
    assert!(
        results.iter().all(Result::is_ok),
        "escape-glyph/nobreak-space faces must accept attributes, got {results:?}"
    );
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.displays_text)
        .expect("text row");
    let text_glyphs = &text_row.glyphs[GlyphArea::Text.index()];

    let default_face_id = FaceId::from(neomacs_display_protocol::face::BasicFaceId::Default);
    let default_fg = state
        .faces
        .get(&default_face_id)
        .expect("default face")
        .foreground;

    // GNU defaults `nobreak-char-ascii-display` to nil: highlight mode keeps
    // the original U+00A0 glyph and merges the `nobreak-space` face over it.
    assert_eq!(
        glyphs_logical_text(text_glyphs),
        "a \u{00A0}c",
        "default highlight mode must preserve the original U+00A0 glyph"
    );
    let normal_space_glyph = text_glyphs
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: ' ' }))
        .expect("literal ASCII space glyph");
    let nbsp_glyph = text_glyphs
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: '\u{00A0}' }))
        .expect("original U+00A0 glyph");

    let normal_space_face = state
        .faces
        .get(&normal_space_glyph.face_id)
        .expect("resolved face for literal ASCII space");
    let nbsp_face = state
        .faces
        .get(&nbsp_glyph.face_id)
        .expect("resolved face for U+00A0");
    assert_eq!(
        normal_space_face.foreground, default_fg,
        "the literal ASCII space must keep the default foreground"
    );
    assert_eq!(
        nbsp_face.foreground,
        nbsp_fg,
        "U+00A0 must receive the nobreak-space foreground; glyphs={:?}",
        glyphs_logical_text(text_glyphs)
    );

    // The nbsp realized a SEPARATE face id, not the base/default face reused.
    assert_ne!(
        nbsp_glyph.face_id, normal_space_glyph.face_id,
        "nbsp must realize a separate nobreak-space face, not reuse the base text face"
    );
    assert_ne!(
        nbsp_glyph.face_id, default_face_id,
        "nbsp face must not be the default face id"
    );

    // The surrounding plain text `a`/`c` keep the base foreground.
    for ch in ['a', 'c'] {
        let glyph = text_glyphs
            .iter()
            .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: c } if c == ch))
            .unwrap_or_else(|| panic!("plain '{ch}' glyph"));
        let face = state
            .faces
            .get(&glyph.face_id)
            .unwrap_or_else(|| panic!("resolved face for '{ch}'"));
        assert_eq!(
            face.foreground, default_fg,
            "normal text '{ch}' must keep the default base foreground, not nobreak-space"
        );
        assert_ne!(
            face.foreground, nbsp_fg,
            "normal text '{ch}' must NOT take the nobreak-space foreground"
        );
    }
}

/// GNU's `nobreak-space` is `:inherit escape-glyph :underline t`. The `t`
/// underline carries no explicit color, so GNU draws it in the face's
/// (escape-glyph-inherited) FOREGROUND -- a brown/cyan underline, never a
/// defaulted black one. This guards the face-realization rule that an
/// unspecified `:underline` color resolves to the foreground, mirroring the
/// box-border resolution; without it the nbsp underline regresses to black.
#[test]
fn layout_frame_rust_nbsp_underline_follows_nobreak_space_foreground() {
    use neomacs_display_protocol::face::UnderlineStyle;
    use neomacs_display_protocol::types::Color;

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("a \u{00A0}c\n");
    }

    // escape-glyph's cyan-on-dark foreground; `nobreak-space` inherits it.
    let nbsp_fg = Color::from_pixel((0x46u32 << 16) | (0xD9u32 << 8) | 0xFFu32);

    let frame_id = eval
        .frame_manager_mut()
        .create_frame("layout-nbsp-underline", 640, 160, buf_id);
    if let Some(frame) = eval.frame_manager_mut().get_mut(frame_id) {
        frame.set_window_system(Some(Value::symbol("neo")));
    }
    assert!(eval.frame_manager_mut().select_frame(frame_id));
    // Wire the real GNU nobreak-space shape: inherit escape-glyph for the
    // foreground AND enable `:underline t` (no explicit underline color).
    let results = eval.eval_str_each(
        "(internal-set-lisp-face-attribute 'escape-glyph :foreground \"#46D9FF\" (selected-frame))\
         (internal-set-lisp-face-attribute 'nobreak-space :inherit 'escape-glyph (selected-frame))\
         (internal-set-lisp-face-attribute 'nobreak-space :underline t (selected-frame))",
    );
    assert!(
        results.iter().all(Result::is_ok),
        "escape-glyph/nobreak-space faces must accept attributes, got {results:?}"
    );
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.displays_text)
        .expect("text row");
    let text_glyphs = &text_row.glyphs[GlyphArea::Text.index()];

    assert_eq!(
        glyphs_logical_text(text_glyphs),
        "a \u{00A0}c",
        "default highlight mode must preserve the original U+00A0 glyph"
    );
    // The original U+00A0 glyph's realized face carries the nobreak-space
    // (escape-glyph-inherited) foreground and underline.
    let nbsp_face = text_glyphs
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: '\u{00A0}' }))
        .and_then(|g| state.faces.get(&g.face_id))
        .expect("original U+00A0 glyph carrying the nobreak-space face");
    assert_eq!(
        nbsp_face.foreground, nbsp_fg,
        "U+00A0 must use the escape-glyph-inherited foreground"
    );

    assert_ne!(
        nbsp_face.underline_style,
        UnderlineStyle::None,
        "nbsp `:underline t` must be underlined"
    );
    // The heart of the guard: an unspecified `:underline` color resolves to the
    // face foreground, not a defaulted black -- so the underline renders in the
    // nobreak-space color exactly like GNU.
    assert_eq!(
        nbsp_face.underline_color,
        Some(nbsp_fg),
        "unspecified nbsp underline color must resolve to the nobreak-space foreground"
    );
    assert_eq!(
        nbsp_face.get_underline_color(),
        nbsp_fg,
        "nbsp underline must draw in the nobreak-space foreground, not defaulted black"
    );
}

/// Sibling of the nbsp-underline guard for the OTHER defaulted decorations.
/// GNU draws `:overline t` and `:strike-through t` (no explicit color) in the
/// face FOREGROUND, exactly like `:underline t` and `:box t`. An anonymous
/// `face` text property carrying blue fg + overline + strike must realize to a
/// face whose overline/strike colors are that blue, never a defaulted black.
#[test]
fn layout_frame_rust_overline_strike_follow_face_foreground() {
    use neomacs_display_protocol::types::Color;

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    // Bare Context has no font-lock, so the anonymous `face` text property
    // survives to layout. `X` carries blue fg + `:overline t` + `:strike t`.
    let results = eval.eval_str_each(
        "(insert (propertize \"X\" 'face \
           '(:foreground \"#0000FF\" :overline t :strike-through t)))",
    );
    assert!(
        results.iter().all(Result::is_ok),
        "insert of propertized text must succeed, got {results:?}"
    );
    let deco_fg = Color::from_pixel(0x0000FF);

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-overline-strike", 640, 160, buf_id);
    if let Some(frame) = eval.frame_manager_mut().get_mut(frame_id) {
        frame.set_window_system(Some(Value::symbol("neo")));
    }
    assert!(eval.frame_manager_mut().select_frame(frame_id));
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.displays_text)
        .expect("text row");
    let x_glyph = text_row.glyphs[GlyphArea::Text.index()]
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: 'X' }))
        .expect("the 'X' glyph");
    let face = state
        .faces
        .get(&x_glyph.face_id)
        .expect("resolved face for 'X'");

    // fg applied, and BOTH defaulted decorations resolve to that fg (not black).
    assert_eq!(
        face.foreground, deco_fg,
        "'X' must carry the blue foreground"
    );
    assert_eq!(
        face.overline_color,
        Some(deco_fg),
        "defaulted `:overline t` color must resolve to the face foreground"
    );
    assert_eq!(
        face.strike_through_color,
        Some(deco_fg),
        "defaulted `:strike-through t` color must resolve to the face foreground"
    );
}

/// GNU renders a non-printable char that a font can't draw (noncharacters,
/// unassigned codepoints, C1 controls) as `\`+octal codepoint in the
/// escape-glyph face (xdisp.c:8645-8661), NOT as a `.notdef` box. U+FFFF must
/// expand to the seven glyphs `\177777`, each painted in the escape-glyph
/// foreground -- asserting the RENDERED GLYPH ROW, not just the source items.
#[test]
fn layout_frame_rust_nonprintable_char_shows_escape_glyph_octal() {
    use neomacs_display_protocol::types::Color;

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        // `a`, the U+FFFF noncharacter, `b`. U+FFFF is category Cn (not
        // printable) so it must display as the octal escape, not a box.
        buf.insert("a\u{FFFF}b\n");
    }
    let escape_fg = Color::from_pixel((0x46u32 << 16) | (0xD9u32 << 8) | 0xFFu32);

    let frame_id = eval
        .frame_manager_mut()
        .create_frame("layout-nonprintable", 640, 160, buf_id);
    if let Some(frame) = eval.frame_manager_mut().get_mut(frame_id) {
        frame.set_window_system(Some(Value::symbol("neo")));
    }
    assert!(eval.frame_manager_mut().select_frame(frame_id));
    let results = eval.eval_str_each(
        "(internal-set-lisp-face-attribute 'escape-glyph :foreground \"#46D9FF\" \
          (selected-frame))",
    );
    assert!(
        results.iter().all(Result::is_ok),
        "escape-glyph must accept a foreground, got {results:?}"
    );
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.displays_text)
        .expect("text row");
    let text_glyphs = &text_row.glyphs[GlyphArea::Text.index()];

    // The rendered row reads `a\177777b`: the noncharacter expands in place.
    let rendered = glyphs_logical_text(text_glyphs);
    assert!(
        rendered.contains("\\177777"),
        "U+FFFF must render as the octal escape `\\177777`, got {rendered:?}"
    );
    assert!(
        !rendered.contains('\u{FFFF}'),
        "the raw noncharacter must never reach the glyph row, got {rendered:?}"
    );

    // Every octal-escape glyph paints in the escape-glyph foreground, not the
    // default face. (`1`/`7` occur only inside the escape here.)
    let default_face_id = FaceId::from(neomacs_display_protocol::face::BasicFaceId::Default);
    let default_fg = state
        .faces
        .get(&default_face_id)
        .expect("default face")
        .foreground;
    assert_ne!(
        escape_fg, default_fg,
        "escape-glyph fg must differ from default"
    );
    for want in ['\\', '1', '7'] {
        let glyph = text_glyphs
            .iter()
            .find(|g| matches!(g.glyph_type, GlyphType::Char { ch } if ch == want))
            .unwrap_or_else(|| panic!("octal-escape glyph {want:?}"));
        let face = state
            .faces
            .get(&glyph.face_id)
            .unwrap_or_else(|| panic!("resolved face for {want:?}"));
        assert_eq!(
            face.foreground, escape_fg,
            "octal-escape glyph {want:?} must paint in the escape-glyph foreground"
        );
    }
}

/// Sibling guard for the nobreak hyphens. GNU treats SOFT_HYPHEN (U+00AD),
/// HYPHEN (U+2010) and NON_BREAKING_HYPHEN (U+2011) via
/// `merge_faces (it->w, Qnobreak_hyphen, 0, it->face_id)` (xdisp.c:8608-8617).
/// The substitute renders as `-`; it must resolve to the nobreak-hyphen
/// foreground, distinct from a normal `-`/base text.
#[test]
fn layout_frame_rust_nobreak_hyphen_uses_nobreak_hyphen_foreground() {
    use neomacs_display_protocol::types::Color;

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        // `x`, normal hyphen, non-breaking hyphen U+2011, `y`.
        buf.insert("x-\u{2011}y\n");
    }

    let hyphen_fg = Color::from_pixel((0x12u32 << 16) | (0x34u32 << 8) | 0x56u32);

    let frame_id = eval
        .frame_manager_mut()
        .create_frame("layout-nobreak-hyphen", 640, 160, buf_id);
    if let Some(frame) = eval.frame_manager_mut().get_mut(frame_id) {
        frame.set_window_system(Some(Value::symbol("neo")));
    }
    assert!(eval.frame_manager_mut().select_frame(frame_id));
    let results = eval.eval_str_each(
        "(internal-set-lisp-face-attribute 'nobreak-hyphen :foreground \"#123456\" (selected-frame))",
    );
    assert!(
        results.iter().all(Result::is_ok),
        "nobreak-hyphen face must accept a foreground, got {results:?}"
    );
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.displays_text)
        .expect("text row");
    let text_glyphs = &text_row.glyphs[GlyphArea::Text.index()];

    let default_face_id = FaceId::from(neomacs_display_protocol::face::BasicFaceId::Default);
    let default_fg = state
        .faces
        .get(&default_face_id)
        .expect("default face")
        .foreground;

    assert_eq!(
        glyphs_logical_text(text_glyphs),
        "x-\u{2011}y",
        "default highlight mode must preserve the original U+2011 glyph"
    );
    let normal_hyphen_glyph = text_glyphs
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: '-' }))
        .expect("literal ASCII hyphen");
    let nobreak_glyph = text_glyphs
        .iter()
        .find(|g| matches!(g.glyph_type, GlyphType::Char { ch: '\u{2011}' }))
        .expect("original U+2011 glyph");
    assert_eq!(
        state
            .faces
            .get(&normal_hyphen_glyph.face_id)
            .expect("resolved face for literal hyphen")
            .foreground,
        default_fg,
        "the literal ASCII hyphen must keep the default foreground"
    );
    assert_eq!(
        state
            .faces
            .get(&nobreak_glyph.face_id)
            .expect("resolved face for U+2011")
            .foreground,
        hyphen_fg,
        "U+2011 must receive the nobreak-hyphen foreground"
    );

    assert_ne!(
        nobreak_glyph.face_id, normal_hyphen_glyph.face_id,
        "U+2011 must realize a separate nobreak-hyphen face, not reuse the base text face"
    );
}

#[test]
fn layout_frame_rust_renders_line_prefix_through_row_builder() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("abc");
        buf.set_buffer_local("line-prefix", Value::string("中\t"));
        buf.set_buffer_local(
            "face-remapping-alist",
            Value::list(vec![Value::list(vec![
                Value::symbol("default"),
                Value::list(vec![Value::keyword("background"), Value::string("#112233")]),
                Value::symbol("default"),
            ])]),
        );
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-buffer-line-prefix", 640, 160, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("text row");
    let logical_text = glyphs_logical_text(&text_row.glyphs[1]);

    assert!(
        logical_text.starts_with("中      abc"),
        "line-prefix should render through the shared row builder with wide/tab semantics, text={logical_text:?}, row={:?}",
        text_row.glyphs[1]
    );
    assert!(
        text_row.glyphs[1]
            .iter()
            .any(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: '中' }) && glyph.wide),
        "line-prefix wide char should carry wide glyph metadata, row={:?}",
        text_row.glyphs[1]
    );
    assert!(
        text_row.glyphs[1]
            .iter()
            .any(|glyph| matches!(glyph.glyph_type, GlyphType::Stretch { width_cols: 6 })),
        "line-prefix tab should expand to the next tab stop, row={:?}",
        text_row.glyphs[1]
    );

    for glyph in text_row.glyphs[1].iter().filter(|glyph| {
        matches!(
            glyph.glyph_type,
            GlyphType::Char { ch: '中' } | GlyphType::Stretch { width_cols: 6 }
        )
    }) {
        let face = state
            .faces
            .get(&glyph.face_id)
            .expect("resolved line-prefix face");
        assert_eq!(
            face.background,
            Color::from_pixel(0x00112233),
            "line-prefix glyphs must use the buffer-remapped default background"
        );
    }
}

#[test]
fn layout_frame_rust_remaps_named_faces_on_line_and_wrap_prefix_strings() {
    use neomacs_display_protocol::types::Color;

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let propertized_prefix = |text| {
            Value::string_with_text_properties(
                text,
                vec![StringTextPropertyRun {
                    start: 0,
                    end: 1,
                    plist: Value::list(vec![
                        Value::symbol("face"),
                        Value::symbol("prefix-face-probe"),
                    ]),
                }],
            )
        };
        let line_prefix = propertized_prefix("L");
        let wrap_prefix = propertized_prefix("W");
        let text = format!("{}\n", "x".repeat(120));
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(&text);
        buf.set_buffer_local("line-prefix", line_prefix);
        buf.set_buffer_local("wrap-prefix", wrap_prefix);
        buf.set_buffer_local(
            "face-remapping-alist",
            Value::list(vec![
                Value::list(vec![
                    Value::symbol("default"),
                    Value::list(vec![Value::keyword("background"), Value::string("#112233")]),
                    Value::symbol("default"),
                ]),
                Value::list(vec![
                    Value::symbol("prefix-face-probe"),
                    Value::list(vec![Value::keyword("foreground"), Value::string("#ff0000")]),
                    Value::symbol("prefix-face-probe"),
                ]),
            ]),
        );
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-remapped-prefix-faces", 632, 400, buf_id);
    assert!(eval.frame_manager_mut().select_frame(frame_id));
    let face_results = eval.eval_str_each(
        "(internal-make-lisp-face 'prefix-face-probe)
         (internal-set-lisp-face-attribute
          'prefix-face-probe :foreground \"#00ff00\" (selected-frame))
         (internal-set-lisp-face-attribute
          'prefix-face-probe :background \"#0000ff\" (selected-frame))",
    );
    assert!(
        face_results.iter().all(Result::is_ok),
        "install prefix probe face, got {face_results:?}"
    );
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let line_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| {
            row.enabled
                && row.role == GlyphRowRole::Text
                && glyphs_logical_text(&row.glyphs[GlyphArea::Text.index()]).starts_with("Lx")
        })
        .expect("text row with line prefix");
    let wrap_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| {
            row.enabled
                && row.role == GlyphRowRole::Text
                && glyphs_logical_text(&row.glyphs[GlyphArea::Text.index()]).starts_with("Wx")
        })
        .expect("continuation row with wrap prefix");
    let prefix_face = |row: &MatrixRow, ch| {
        let prefix_glyph = row.glyphs[GlyphArea::Text.index()]
            .iter()
            .find(|glyph| {
                matches!(glyph.glyph_type, GlyphType::Char { ch: glyph_ch } if glyph_ch == ch)
            })
            .expect("prefix glyph");
        state
            .faces
            .get(&prefix_glyph.face_id)
            .expect("resolved prefix face")
    };

    for (kind, face) in [
        ('L', prefix_face(line_row, 'L')),
        ('W', prefix_face(wrap_row, 'W')),
    ] {
        assert_eq!(
            face.foreground,
            Color::from_pixel(0x00ff0000),
            "{kind} prefix named face must use its buffer-local remapped foreground"
        );
        assert_eq!(
            face.background,
            Color::from_pixel(0x000000ff),
            "unremapped attributes must still come from the {kind} prefix named face"
        );
    }

    let post_zv_rows = entry
        .matrix
        .rows
        .iter()
        .filter(|row| {
            row.enabled
                && row.role == GlyphRowRole::Text
                && row.start_charpos == 121
                && row.end_charpos == 121
                && row.ends_at_zv
        })
        .collect::<Vec<_>>();
    assert!(
        post_zv_rows.len() > 1,
        "fixture must expose more than the first post-ZV row"
    );
    for row in post_zv_rows {
        let text = glyphs_logical_text(&row.glyphs[GlyphArea::Text.index()]);
        assert!(
            text.starts_with('L'),
            "GNU applies line-prefix to every post-ZV row; got {text:?} in {row:#?}"
        );
        let face = prefix_face(row, 'L');
        assert_eq!(face.foreground, Color::from_pixel(0x00ff0000));
        assert_eq!(face.background, Color::from_pixel(0x000000ff));
    }
}

