/// GNU `face_at_string_position' merges an overlay string's own face after
/// resolving the anchor face.  The pushed string must therefore override the
/// default EOB anchor face.
#[test]
fn eob_overlay_after_string_applies_its_own_face() {
    let (eval, buf_id, _frame_id, rows, _char_width, _char_height) =
        layout_main_text_rows_with("ab", |eval, _buf_id| {
            eval.eval_str(
                "(overlay-put (make-overlay 3 3) 'after-string \
                   (propertize \"X\" 'face '(:foreground \"#ff0000\")))",
            )
            .expect("propertized EOB after-string");
        });

    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let overlay_string = RustTextPropAccess::new(buffer)
        .overlay_strings_at(2)
        .into_iter()
        .next()
        .expect("EOB after-string value")
        .string;
    let properties =
        neovm_core::emacs_core::value::get_string_text_properties_table_for_value(overlay_string)
            .expect("after-string text properties");
    assert_eq!(
        properties.get_property_at_char_pos(CharPos0::ZERO, Value::symbol("face")),
        Some(Value::list(vec![
            Value::symbol(":foreground"),
            Value::string("#ff0000"),
        ])),
        "the overlay bridge must retain the string object's own face property"
    );

    let glyph = rows
        .iter()
        .flat_map(|row| row.glyphs[GlyphArea::Text.index()].iter())
        .find(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: 'X' }))
        .expect("EOB after-string glyph");
    assert_ne!(
        glyph.face_id,
        neomacs_display_protocol::types::FaceId::from(
            neomacs_display_protocol::face::BasicFaceId::Default,
        ),
        "the after-string's own named face must survive the EOB overlay path"
    );
}

#[test]
fn only_the_last_boxed_eob_overlay_string_closes_the_run() {
    use neomacs_display_protocol::face::BoxVerticalEdges;

    let (_eval, _buf_id, _frame_id, rows, _char_width, _char_height) =
        layout_main_text_rows_with("ab", |eval, _buf_id| {
            eval.eval_str(
                r##"(progn
                      (put-text-property
                       2 3 'face '(:box (:line-width 1 :color "#ff0000")))
                      (let ((first (make-overlay 2 3))
                            (second (make-overlay 2 3)))
                        (overlay-put first 'after-string
                                     (propertize "X" 'face
                                                 '(:box (:line-width 1 :color "#ff0000"))))
                        (overlay-put second 'after-string
                                      (propertize "Y" 'face
                                                  '(:box (:line-width 1 :color "#ff0000"))))))"##,
            )
            .expect("two boxed EOB strings");
        });

    let edges: Vec<_> = rows
        .iter()
        .flat_map(|row| row.glyphs[GlyphArea::Text.index()].iter())
        .filter_map(|glyph| match glyph.glyph_type {
            GlyphType::Char { ch: 'X' | 'Y' } => Some(glyph.box_vertical_edges),
            _ => None,
        })
        .collect();
    assert_eq!(edges.len(), 2, "both EOB strings are displayed");
    assert_eq!(
        edges,
        [BoxVerticalEdges::Neither, BoxVerticalEdges::Right],
        "GNU closes the restored source run only after its final pushed string"
    );
}

/// A point inside covered buffer text belongs to the display replacement's
/// opening slot.  Finishing the pushed string iterator on a later visual row
/// must not move that cursor capture to the iterator's final row.
#[test]
fn wrapped_display_replacement_cursor_stays_at_opening_slot() {
    let prefix = "a".repeat(74);
    let text = format!("{prefix}:\nnext\n");
    let replacement_start = prefix.len();
    let point_pos = replacement_start + 1;
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(&text);
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(replacement_start));
        buf.put_text_property(
            replacement_start,
            replacement_start + 1,
            Value::symbol("display"),
            Value::string(": (47 GiB available)"),
        );
    }
    eval.buffer_manager_mut().set_current(buf_id);
    eval.eval_str("(setq truncate-lines nil)").expect("wrap");

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-wrapped-display-cursor", 640, 160, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        let window = frame
            .find_window_mut(selected_window)
            .expect("selected window");
        if let neovm_core::window::Window::Leaf {
            window_start,
            point,
            ..
        } = window
        {
            *window_start = LispCharPos1::ONE;
            *point = LispCharPos1::from_one_based_usize(point_pos);
        }
    }

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let snapshot = frame
        .redisplay_snapshot(selected_window)
        .expect("display snapshot");
    let cursor = snapshot.phys_cursor.as_ref().expect("cursor");
    let preceding = snapshot
        .point_for_buffer_pos(LispCharPos1::from_one_based_usize(point_pos - 1))
        .expect("preceding prefix glyph");

    assert_eq!(
        cursor.row, preceding.row,
        "the covered point belongs to the replacement's opening row"
    );
    assert_eq!(cursor.x, preceding.x + preceding.width);
}

#[test]
fn layout_frame_rust_renders_display_replacement_tabs_as_stretches() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("px");
        buf.put_text_property(1, 2, Value::symbol("display"), Value::string("a\tb"));
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-display-tab-replacement", 640, 160, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("text row");

    let logical_text = glyphs_logical_text(&text_row.glyphs[1]);
    assert!(
        !logical_text.contains('\t'),
        "display replacement tab should not render as a literal tab, row={:?}",
        text_row.glyphs[1]
    );
    assert!(
        logical_text.contains("pa      b"),
        "display replacement tab should expand to the next row tab stop, text={logical_text:?}"
    );
    assert!(
        text_row.glyphs[1]
            .iter()
            .any(|glyph| matches!(glyph.glyph_type, GlyphType::Stretch { width_cols: 6 })),
        "display replacement tab should be a stretch glyph, row={:?}",
        text_row.glyphs[1]
    );
}

