#[test]
fn layout_frame_rust_emits_inline_image_glyphs_for_display_image_specs() {
    let mut eval = Context::new();
    let requests = Arc::new(Mutex::new(Vec::new()));
    eval.set_display_host(Box::new(RecordingImageDisplayHost {
        requests: Arc::clone(&requests),
        video_requests: Arc::new(Mutex::new(Vec::new())),
        webkit_requests: Arc::new(Mutex::new(Vec::new())),
        surface_requests: Arc::new(Mutex::new(Vec::new())),
    }));
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let text = "aXb";
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(text);
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(1));
        buf.put_text_property(
            1,
            2,
            Value::symbol("display"),
            Value::list(vec![
                Value::symbol("image"),
                Value::keyword("type"),
                Value::symbol("png"),
                Value::keyword("file"),
                Value::string("/tmp/neomacs-inline-image.png"),
                Value::keyword("max-width"),
                Value::fixnum(32),
                Value::keyword("max-height"),
                Value::fixnum(24),
                Value::keyword("foreground"),
                Value::string("#112233"),
                Value::keyword("background"),
                Value::string("red"),
            ]),
        );
    }

    let frame_id = eval
        .frame_manager_mut()
        .create_frame("layout-inline-image", 320, 120, buf_id);

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("frame display state");
    let presentation = state.materialize();
    let (image_id, width, height, slot_id) = presentation
        .glyphs
        .iter()
        .find_map(|glyph| match glyph {
            FrameGlyph::Image {
                image_id,
                width,
                height,
                slot_id,
                ..
            } => Some((*image_id, *width, *height, *slot_id)),
            _ => None,
        })
        .expect("inline image glyph");
    assert_eq!(image_id.get(), 77);
    assert_eq!(width, 32.0);
    assert_eq!(height, 24.0);
    let replacement = assert_replacement_slot_between_neighbors(&eval, frame_id, 2, 32);
    let slot_id = slot_id.expect("image slot id");
    assert_eq!(i64::from(slot_id.col), replacement.col);

    let requests = requests.lock().expect("requests lock");
    assert_eq!(requests.len(), 1);
    assert_eq!(
        requests[0].size,
        ImageSizeSpec::new(AxisSize::AtMost(32), AxisSize::AtMost(24))
    );
    assert_eq!(requests[0].colors.foreground().rgb24(), 0x112233);
    assert_eq!(requests[0].colors.background().rgb24(), 0xff0000);
}

/// Telega sizes inline badges and custom emoji in character-cell units.  GNU
/// resolves those units against the selected frame before image lookup; the
/// renderer must never see the intrinsic 128px emoji as an unconstrained
/// native-size image.
#[test]
fn layout_frame_rust_resolves_telega_cell_sized_images_before_catalog_lookup() {
    let mut eval = Context::new();
    let requests = Arc::new(Mutex::new(Vec::new()));
    eval.set_display_host(Box::new(RecordingImageDisplayHost {
        requests: Arc::clone(&requests),
        video_requests: Arc::new(Mutex::new(Vec::new())),
        webkit_requests: Arc::new(Mutex::new(Vec::new())),
        surface_requests: Arc::new(Mutex::new(Vec::new())),
    }));
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("aXXb");
        buf.put_text_property(
            1,
            3,
            Value::symbol("display"),
            Value::list(vec![
                Value::list(vec![
                    Value::symbol("slice"),
                    Value::fixnum(0),
                    Value::NIL,
                    Value::make_float(1.0),
                    Value::NIL,
                ]),
                Value::list(vec![
                    Value::symbol("image"),
                    Value::keyword("type"),
                    Value::symbol("svg"),
                    Value::keyword("file"),
                    Value::string("/tmp/telega-premium.svg"),
                    Value::keyword("max-height"),
                    Value::cons(Value::fixnum(1), Value::symbol("ch")),
                    Value::keyword("width"),
                    Value::cons(Value::fixnum(2), Value::symbol("cw")),
                ]),
            ]),
        );
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-telega-cell-image", 320, 120, buf_id);
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        frame.char_width = 8.0;
        frame.char_height = 18.0;
    }

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let requests = requests.lock().expect("requests lock");
    assert_eq!(requests.len(), 1);
    assert_eq!(
        requests[0].size,
        ImageSizeSpec::new(AxisSize::Exact(16), AxisSize::AtMost(18)),
        "character-cell units are logical layout dimensions, independent of device scale"
    );
}

/// GNU xdisp applies non-replacing `(slice X Y WIDTH HEIGHT)` specs to the
/// image replacement in the same `display` property.  Telega uses this exact
/// form to split one multi-line photo into one image glyph per text row.
#[test]
fn layout_frame_rust_crops_compound_display_images_to_the_requested_slice() {
    let mut eval = Context::new();
    eval.set_display_host(Box::new(RecordingImageDisplayHost::default()));
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("aXb");
        buf.put_text_property(
            1,
            2,
            Value::symbol("display"),
            Value::list(vec![
                Value::list(vec![
                    Value::symbol("slice"),
                    Value::fixnum(0),
                    Value::fixnum(8),
                    Value::make_float(1.0),
                    Value::fixnum(8),
                ]),
                Value::list(vec![
                    Value::symbol("image"),
                    Value::keyword("type"),
                    Value::symbol("png"),
                    Value::keyword("file"),
                    Value::string("/tmp/neomacs-sliced-image.png"),
                ]),
            ]),
        );
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-sliced-inline-image", 320, 120, buf_id);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let presentation = engine
        .last_frame_display_state
        .as_ref()
        .expect("frame display state")
        .materialize();
    let (source_rect, width, height) = presentation
        .glyphs
        .iter()
        .find_map(|glyph| match glyph {
            FrameGlyph::Image {
                source_rect,
                width,
                height,
                ..
            } => Some((*source_rect, *width, *height)),
            _ => None,
        })
        .expect("sliced inline image glyph");

    assert_eq!(width, 32.0, "a 1.0 slice width means the full image width");
    assert_eq!(
        height, 8.0,
        "the row must reserve only the requested slice, not the full 24px image"
    );
    let source_rect_tolerance = 2.0 / u16::MAX as f32;
    assert_eq!(source_rect.x(), 0.0);
    assert!((source_rect.y() - 8.0 / 24.0).abs() <= source_rect_tolerance);
    assert_eq!(source_rect.width(), 1.0);
    assert!((source_rect.height() - 8.0 / 24.0).abs() <= source_rect_tolerance);
}

