#[test]
fn layout_frame_rust_emits_display_space_as_stretch_glyph() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let text = "a b";
    let space_byte_start = text.find(' ').expect("space start");
    let space_byte_end = space_byte_start + 1;
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(text);
        buf.put_text_property(
            space_byte_start,
            space_byte_end,
            Value::symbol("display"),
            display_space_width_spec(4),
        );
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-display-space-stretch", 320, 120, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let window_entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = window_entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("text row");
    let glyphs = &text_row.glyphs[1];

    assert!(matches!(
        glyphs.first().map(|glyph| &glyph.glyph_type),
        Some(GlyphType::Char { ch: 'a' })
    ));
    assert!(matches!(
        glyphs.get(1).map(|glyph| &glyph.glyph_type),
        Some(GlyphType::Stretch { width_cols: 4 })
    ));
    assert!(matches!(
        glyphs.get(2).map(|glyph| &glyph.glyph_type),
        Some(GlyphType::Char { ch: 'b' })
    ));
}

fn display_space_width_spec(columns: i64) -> Value {
    Value::list(vec![
        Value::symbol("space"),
        Value::keyword("width"),
        Value::fixnum(columns),
    ])
}

fn display_space_relative_width_spec(factor: i64) -> Value {
    Value::list(vec![
        Value::symbol("space"),
        Value::keyword("relative-width"),
        Value::fixnum(factor),
    ])
}

fn display_space_relative_height_spec(factor: i64, ascent_percent: i64) -> Value {
    Value::list(vec![
        Value::symbol("space"),
        Value::keyword("width"),
        Value::fixnum(2),
        Value::keyword("relative-height"),
        Value::fixnum(factor),
        Value::keyword("ascent"),
        Value::fixnum(ascent_percent),
    ])
}

/// Issue #204 — a `(space :align-to (- center (0.5 . IMAGE-SPEC)))` prefix is
/// how Dashboard and `image-dired` centre a banner image.
///
/// GNU resolves the `(image …)` operand to the image's own pixel width
/// (xdisp.c:30506) and `(NUM . EXPR)` to NUM × EXPR (xdisp.c:30551), so the
/// stretch reaches `centre − half the image`. NEO Emacs left-aligned it: the
/// operand could not be modelled by the typed expression mirror, so the whole
/// `:align-to` was dropped and the stretch collapsed to one column.
#[test]
fn issue_204_align_to_centers_image_by_its_resolved_width() {
    let _eval = Context::new();
    let mut params = test_window_params();
    params.space_image_catalog = Some(crate::types::SharedImageCatalog(std::rc::Rc::new(
        FixedSizeImageCatalog {
            width: 400,
            height: 300,
        },
    )));

    let image = Value::list(vec![
        Value::symbol("image"),
        Value::keyword("type"),
        Value::symbol("png"),
        Value::keyword("file"),
        Value::string("banner.png"),
    ]);
    // `(0.5 . IMAGE)` — reads as the proper list `(0.5 image :type png …)`.
    let half_image = Value::cons(Value::make_float(0.5), image);
    let spec = Value::list(vec![
        Value::symbol("space"),
        Value::keyword("align-to"),
        Value::list(vec![
            Value::symbol("-"),
            Value::symbol("center"),
            half_image,
        ]),
    ]);

    let geometry = DisplaySpaceGeometry::from_display_space_spec(
        &spec, 0.0, 0.0, 8.0, 8.0, 10.0, 7.0, &params,
    );

    // The 800px-wide text area centres at 400; half the 400px image is 200.
    assert_eq!(
        geometry.width, 200.0,
        "stretch must reach centre minus half the image width"
    );
}

/// Without a catalog — a terminal frame — GNU's `FRAME_WINDOW_P` guard makes
/// the `(image …)` operand, and with it the whole expression, fail. The stretch
/// then falls back to one canonical char width (xdisp.c:32879) rather than
/// centring on a made-up image size.
#[test]
fn issue_204_align_to_image_operand_falls_back_without_a_catalog() {
    let _eval = Context::new();
    let params = test_window_params();

    let image = Value::list(vec![
        Value::symbol("image"),
        Value::keyword("type"),
        Value::symbol("png"),
        Value::keyword("file"),
        Value::string("banner.png"),
    ]);
    let spec = Value::list(vec![
        Value::symbol("space"),
        Value::keyword("align-to"),
        Value::list(vec![
            Value::symbol("-"),
            Value::symbol("center"),
            Value::cons(Value::make_float(0.5), image),
        ]),
    ]);

    let geometry = DisplaySpaceGeometry::from_display_space_spec(
        &spec, 0.0, 0.0, 8.0, 8.0, 10.0, 7.0, &params,
    );

    assert_eq!(geometry.width, 8.0, "GNU falls back to one char width");
}

/// An image that finishes decoding must invalidate the window's retained
/// matrix, not just request a redisplay.
///
/// Redisplay has two independent gates: `RedisplaySignature` decides whether to
/// redisplay at all, and `RetainedWindowKey` decides whether a window may reuse
/// its retained matrix. `ImageStateChanged` bumped only the former, so
/// redisplay ran and then reused the matrix that had captured the image's 1x1
/// `Pending` placeholder — every async-decoded buffer image stayed one pixel
/// wide for the lifetime of the buffer, no matter how many redisplays or buffer
/// edits followed.
#[test]
fn completed_image_decode_invalidates_the_retained_window_key() {
    let mut eval = Context::new();
    let params = test_window_params();
    let layout_box = WindowLayoutBox::resolve(&params, Default::default(), Default::default());

    let before = RetainedWindowKey::from_params(&params, layout_box, &eval);

    // The decode landing is delivered as `ImageStateChanged` -> `LayoutInvalidated`.
    eval.invalidate_media();

    let after = RetainedWindowKey::from_params(&params, layout_box, &eval);

    assert_ne!(
        before, after,
        "a completed image decode must escalate past retained-matrix reuse, \
         otherwise the 1x1 placeholder geometry is never re-resolved"
    );
}

struct FixedSizeImageCatalog {
    width: u32,
    height: u32,
}

impl ImageCatalog for FixedSizeImageCatalog {
    fn lookup(&self, _request: ImageResolveRequest) -> ImageLookup {
        ImageLookup::Ready(ReadyImage {
            load: test_image_load(9),
            metadata:
                neovm_core::emacs_core::image_catalog::ResolvedImageMetadata::layout_is_image_pixels(
                    self.width,
                    self.height,
                    0,
                    false,
                    neomacs_display_protocol::ImageMaskKind::None,
                ),
        })
    }
}

