#[test]
fn layout_frame_rust_converges_visibility_for_wrapped_rows_in_one_redisplay() {
    fn char_at_lisp_pos(buffer: &neovm_core::buffer::Buffer, pos: usize) -> Option<char> {
        if pos == 0 {
            return None;
        }
        let byte_pos = buffer
            .char_pos_to_emacs_byte_pos_clamped(neovm_core::buffer::CharPos0::new(pos - 1))
            .get();
        buffer.char_after_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(byte_pos))
    }

    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let logical_lines = (0..24)
        .map(|line| format!("line-{line:02} abcdefghijklmno\n"))
        .collect::<Vec<_>>();
    let text = logical_lines.join("");
    let target_pos = logical_lines
        .iter()
        .take(18)
        .map(|line| line.chars().count())
        .sum::<usize>()
        + 1;
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(&text);
        // Move the buffer point to target_pos so the selected
        // window reads it as params.point (GNU
        // window.c:window_point says selected windows use
        // BUF_PT, not pointm). Without this, the Window::point
        // assignment below would be shadowed by buffer.pt_char
        // during window_params_from_neovm and layout would
        // never see the target.
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(target_pos - 1));
        buf.set_buffer_local("word-wrap", Value::T);
    }
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("layout-wrap-retry", 80, 192, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        let window = frame
            .find_window_mut(selected_window)
            .expect("selected window");
        if let neovm_core::window::Window::Leaf {
            window_start,
            point,
            ..
        } = window
        {
            *window_start = LispCharPos1::ONE;
            *point = LispCharPos1::from_one_based_usize(target_pos);
        }
    }

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let snapshot = frame
        .redisplay_snapshot(selected_window)
        .expect("display snapshot");
    let window = frame.find_window(selected_window).expect("selected window");
    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let point_chars = snapshot
        .points
        .iter()
        .map(|point| {
            (
                point.buffer_pos,
                char_at_lisp_pos(buffer, point.buffer_pos.to_one_based_usize()),
            )
        })
        .collect::<Vec<_>>();

    assert!(
        snapshot
            .point_for_buffer_pos(LispCharPos1::from_one_based_usize(target_pos))
            .is_some(),
        "expected wrapped-line redisplay to converge on point {target_pos}, points={:?}, rows={:?}, chars={:?}",
        snapshot.points,
        snapshot.rows,
        point_chars
    );
    match window {
        neovm_core::window::Window::Leaf { window_start, .. } => {
            assert!(
                *window_start > LispCharPos1::ONE,
                "expected window-start to advance for wrapped redisplay, got {window_start:?}"
            );
        }
        other => panic!("expected leaf window, got {other:?}"),
    }
}

#[test]
fn layout_frame_rust_converges_visibility_for_point_line_tail_clipping() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let prefix = (0..2)
        .map(|line| format!("p{line:02}\n"))
        .collect::<Vec<_>>()
        .join("");
    let target_line = "abcdefghijklmno\n";
    let text = format!("{prefix}{target_line}");
    let point = prefix.chars().count() + 1;
    let later_pos = point + 10;
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(&text);
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(0));
        buf.set_buffer_local("word-wrap", Value::T);
    }
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("layout-point-line-tail", 80, 256, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        let window = frame
            .find_window_mut(selected_window)
            .expect("selected window");
        if let neovm_core::window::Window::Leaf {
            window_start,
            point: window_point,
            ..
        } = window
        {
            *window_start = LispCharPos1::ONE;
            *window_point = LispCharPos1::from_one_based_usize(point);
        }
    }

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let snapshot = frame
        .redisplay_snapshot(selected_window)
        .expect("display snapshot");
    assert!(
        snapshot
            .point_for_buffer_pos(LispCharPos1::from_one_based_usize(later_pos))
            .is_some(),
        "expected redisplay to publish later positions from the point line after retry, points={:?}, rows={:?}",
        snapshot.points,
        snapshot.rows
    );
}

#[test]
fn layout_frame_rust_keeps_visible_eob_cursor_on_short_trailing_newline_buffer() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let text = "LEFT WINDOW\nLine 2\nLine 3\n";
    let point = {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(text);
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(0));
        buf.point_max_char_pos().get() + 1
    };
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("layout-eob-visible", 320, 640, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        let window = frame
            .find_window_mut(selected_window)
            .expect("selected window");
        if let neovm_core::window::Window::Leaf {
            window_start,
            point: window_point,
            ..
        } = window
        {
            *window_start = LispCharPos1::ONE;
            *window_point = LispCharPos1::from_one_based_usize(point);
        }
    }

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let snapshot = frame
        .redisplay_snapshot(selected_window)
        .expect("display snapshot");
    let window = frame.find_window(selected_window).expect("selected window");

    assert!(
        snapshot
            .point_for_buffer_pos(LispCharPos1::from_one_based_usize(1))
            .is_some(),
        "expected first line to remain visible when EOB cursor is already onscreen, points={:?}, rows={:?}",
        snapshot.points,
        snapshot.rows
    );
    match window {
        neovm_core::window::Window::Leaf { window_start, .. } => {
            assert_eq!(
                *window_start,
                LispCharPos1::ONE,
                "expected visible EOB cursor not to force a retry scroll"
            );
        }
        other => panic!("expected leaf window, got {other:?}"),
    }
}

#[test]
fn incremental_newline_insert_moves_phys_cursor_to_empty_eob_row() {
    let initial_text = ";; first scratch comment\n;; second scratch comment\n\n";
    let initial_eob = initial_text.len();
    let (mut eval, frame_id, buf_id, _selected_window) = incr_editing_frame(initial_text, 320, 640);
    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(initial_eob));
    let mut engine = LayoutEngine::new();

    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .insert("a");
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);
    let after_insert = engine
        .last_frame_display_state
        .as_ref()
        .and_then(|state| state.phys_cursor.as_ref())
        .expect("cursor after self-insert");
    assert_eq!((after_insert.row, after_insert.col), (3, 1));

    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .insert("\n");
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state after Return");
    let after_return = state.phys_cursor.as_ref().expect("cursor after Return");
    assert_eq!(
        (after_return.row, after_return.col),
        (4, 0),
        "GNU places point after the inserted newline on the next empty row"
    );
    assert_eq!(
        (
            (after_return.y / state.char_height.max(1.0)) as usize,
            (after_return.x / state.char_width.max(1.0)) as usize,
        ),
        (after_return.row, usize::from(after_return.col)),
        "the pixel geometry consumed by the TTY must identify the same cursor cell as its typed slot"
    );
}

#[test]
fn layout_frame_rust_keeps_visible_eob_cursor_across_redisplay_with_scroll_step() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let text = "M-x describe";
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(text);
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(text.len()));
        buf.set_buffer_local("scroll-step", Value::fixnum(1));
    }
    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-visible-eob-scroll-step", 640, 480, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    {
        let frame = eval.frame_manager().get(frame_id).expect("frame");
        let window = frame.find_window(selected_window).expect("selected window");
        match window {
            neovm_core::window::Window::Leaf { window_start, .. } => {
                assert_eq!(
                    *window_start,
                    LispCharPos1::ONE,
                    "first redisplay should keep the visible EOB cursor at the buffer top"
                );
            }
            other => panic!("expected leaf window, got {other:?}"),
        }
    }

    // The second pass has a valid previous `window-end`.  Its value is
    // exclusive and therefore equals point at EOB, but GNU still keeps the EOB
    // cursor on the already-rendered row instead of invoking `scroll-step`.
    engine.layout_frame_rust(&mut eval, frame_id);

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let snapshot = frame
        .redisplay_snapshot(selected_window)
        .expect("display snapshot");
    let window = frame.find_window(selected_window).expect("selected window");
    assert!(
        snapshot.point_for_buffer_pos(LispCharPos1::ONE).is_some(),
        "repeated redisplay should keep the prompt/input row visible, points={:?}, rows={:?}",
        snapshot.points,
        snapshot.rows
    );
    match window {
        neovm_core::window::Window::Leaf { window_start, .. } => {
            assert_eq!(
                *window_start,
                LispCharPos1::ONE,
                "visible EOB must not be mistaken for an off-screen cursor by scroll-step"
            );
        }
        other => panic!("expected leaf window, got {other:?}"),
    }
}

