#[test]
fn buffer_text_source_shadow_matches_main_buffer_simple_unicode_row() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("A中👨‍👩B\n");
    }
    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-buffer-source-shadow", 640, 160, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let main_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("main buffer text row");

    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let snapshot = LayoutBufferSnapshot::from_buffer(buffer);
    let line_end = CharPos0::new("A中👨‍👩B".chars().count());
    let shadow_row =
        render_buffer_text_source_shadow_row(buf_id, &snapshot, line_end, 640.0, 16.0, 12.0, 8.0);

    // Compare against the text portion: the full pipeline appends the GNU
    // newline-space glyph, which the minimal shadow producer does not.
    let main_text_glyphs = strip_appended_newline_space(&main_row.glyphs[1]);
    assert_eq!(
        glyphs_logical_text(&shadow_row.glyphs[1]),
        glyphs_logical_text(&main_text_glyphs)
    );
    assert_eq!(
        shadow_row.glyphs[1]
            .iter()
            .any(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: '中' }) && glyph.wide),
        main_row.glyphs[1]
            .iter()
            .any(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: '中' }) && glyph.wide)
    );
    assert_eq!(
        shadow_row.glyphs[1].iter().any(|glyph| glyph.padding),
        main_row.glyphs[1].iter().any(|glyph| glyph.padding)
    );
    assert_eq!(
        shadow_row
            .glyphs[1]
            .iter()
            .any(|glyph| matches!(&glyph.glyph_type, GlyphType::Composite { text } if text.contains('\u{200d}'))),
        main_row
            .glyphs[1]
            .iter()
            .any(|glyph| matches!(&glyph.glyph_type, GlyphType::Composite { text } if text.contains('\u{200d}')))
    );
}

#[test]
fn buffer_text_source_shadow_matches_main_buffer_tab_row() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("a\tb\n");
    }
    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-buffer-source-tab-shadow", 640, 160, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let main_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("main buffer text row");

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let snapshot = LayoutBufferSnapshot::from_buffer(buffer);
    let line_end = CharPos0::new("a\tb".chars().count());
    let shadow_row = render_buffer_text_source_shadow_row(
        buf_id,
        &snapshot,
        line_end,
        640.0,
        frame.char_height,
        frame.char_height,
        frame.char_width,
    );

    // The full pipeline appends the GNU newline-space glyph at the line
    // end; the minimal shadow producer stops at the text. Compare the text
    // portion.
    let main_glyphs = strip_appended_newline_space(&main_row.glyphs[1]);
    let main_glyphs = &main_glyphs;
    let shadow_glyphs = &shadow_row.glyphs[1];
    let main_tab = main_glyphs
        .iter()
        .find(|glyph| matches!(glyph.glyph_type, GlyphType::Stretch { .. }))
        .expect("main tab stretch");
    let shadow_tab = shadow_glyphs
        .iter()
        .find(|glyph| matches!(glyph.glyph_type, GlyphType::Stretch { .. }))
        .expect("shadow tab stretch");

    assert_eq!(
        glyphs_logical_text(main_glyphs),
        glyphs_logical_text(shadow_glyphs)
    );
    assert_eq!(main_tab.glyph_type, shadow_tab.glyph_type);
    assert_eq!(main_tab.pixel_width, shadow_tab.pixel_width);
}

/// Widens the buffer-source A/B net to a row class the acquisition migration
/// touches: trailing whitespace followed by the appended GNU newline space.
/// The shadow producer must agree with the main pipeline on the text glyphs
/// (including their buffer positions), and the appended newline space — a
/// positionless glyph the trailing-whitespace highlight must skip — must sit
/// AFTER the trailing spaces on the main row only.
#[test]
fn buffer_text_source_shadow_matches_main_buffer_trailing_whitespace_row() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("ab  \n");
    }
    let frame_id = eval.frame_manager_mut().create_frame(
        "layout-buffer-source-trailing-ws-shadow",
        640,
        160,
        buf_id,
    );
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let main_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("main buffer text row");

    // The full pipeline must have appended the GNU newline space (a
    // positionless glyph) after the trailing spaces.
    let raw_main = &main_row.glyphs[1];
    let last = raw_main.last().expect("main row glyphs");
    assert!(
        matches!(last.glyph_type, GlyphType::Char { ch: ' ' })
            && last.legacy_charpos()
                == neomacs_display_protocol::glyph_matrix::NO_BUFFER_POSITION_CHARPOS,
        "expected the appended positionless newline space last, got {last:?}"
    );

    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let snapshot = LayoutBufferSnapshot::from_buffer(buffer);
    let line_end = CharPos0::new("ab  ".chars().count());
    let shadow_row =
        render_buffer_text_source_shadow_row(buf_id, &snapshot, line_end, 640.0, 16.0, 12.0, 8.0);

    let main_glyphs = strip_appended_newline_space(raw_main);
    let shadow_glyphs = &shadow_row.glyphs[1];
    assert_eq!(
        glyphs_logical_text(&main_glyphs),
        glyphs_logical_text(shadow_glyphs)
    );
    // The trailing spaces are ordinary buffer glyphs on both paths: same
    // glyph types and same buffer positions, all positioned (the highlight
    // seam distinguishes them from appended glyphs by exactly this).
    assert_eq!(
        main_glyphs
            .iter()
            .map(|glyph| (glyph.glyph_type.clone(), glyph.legacy_charpos()))
            .collect::<Vec<_>>(),
        shadow_glyphs
            .iter()
            .map(|glyph| (glyph.glyph_type.clone(), glyph.legacy_charpos()))
            .collect::<Vec<_>>()
    );
    assert!(
        main_glyphs.iter().all(|glyph| glyph.legacy_charpos()
            != neomacs_display_protocol::glyph_matrix::NO_BUFFER_POSITION_CHARPOS),
        "text glyphs of the trailing-whitespace row must all carry buffer positions"
    );
}

/// Render one buffer row through the unified item renderer fed by the
/// classified-row source ([`crate::buffer_source::row_route::BufferPlainItemSource`]),
/// for shadow comparison against the buffer-pipeline row.
#[allow(clippy::too_many_arguments)]
fn render_buffer_plain_item_source_shadow_row(
    buf_id: BufferId,
    snapshot: &LayoutBufferSnapshot,
    start: CharPos0,
    line_end: CharPos0,
    base_face_id: FaceId,
    width_px: f32,
    height_px: f32,
    ascent_px: f32,
    char_width_px: f32,
) -> GlyphRow {
    let mut source = crate::buffer_source::row_route::BufferPlainItemSource::with_row_break(
        buf_id,
        snapshot,
        start,
        line_end,
        RenderFaceRef::FaceId(base_face_id),
    );
    let mut font_metrics = None;
    let mut renderer =
        DisplayRowRenderer::new(&mut font_metrics, DisplayRowMeasurementMode::LogicalCells);
    let table = FaceTable::new();
    let resolver = FaceResolver::new(&table, 0x00ff_ffff, 0x0000_0000, 14.0, None);
    let mut face_ids = FrameFaceAttempt::for_test_with_next_id(base_face_id.get() + 1);
    DisplayRowSourceFragmentFrame::new(
        DisplayRowGeometry::new(
            0.0,
            width_px,
            height_px,
            char_width_px,
            ascent_px,
            DisplayTabPolicy::every(8),
        ),
        GlyphRowRole::Text,
        base_face_id,
        resolver.default_face(),
    )
    .render_request(DisplayRowRenderBounds::new(
        DisplayRowPosition::new(0.0, 0),
        DisplayRowMaxX::Bounded(width_px),
    ))
    .render(&mut renderer, &mut source, &resolver, &mut face_ids)
    .expect("ascii item source row")
    .into_row()
}

/// Like [`render_buffer_plain_item_source_shadow_row`] but rendering the
/// TEXT ONLY over `[start, end)` — no row-break item — mirroring the routed
/// production render of a phase-2f overflow-prefix plan, where the walk
/// hands back to the pipeline at the first non-fitting char instead of
/// consuming a newline.
#[allow(clippy::too_many_arguments)]
fn render_buffer_plain_item_prefix_shadow_row(
    buf_id: BufferId,
    snapshot: &LayoutBufferSnapshot,
    start: CharPos0,
    end: CharPos0,
    base_face_id: FaceId,
    width_px: f32,
    height_px: f32,
    ascent_px: f32,
    char_width_px: f32,
) -> GlyphRow {
    render_buffer_plain_item_prefix_shadow_row_at(
        buf_id,
        snapshot,
        start,
        end,
        base_face_id,
        width_px,
        height_px,
        ascent_px,
        char_width_px,
        DisplayRowPosition::new(0.0, 0),
    )
}

#[allow(clippy::too_many_arguments)]
fn render_buffer_plain_item_prefix_shadow_row_at(
    buf_id: BufferId,
    snapshot: &LayoutBufferSnapshot,
    start: CharPos0,
    end: CharPos0,
    base_face_id: FaceId,
    width_px: f32,
    height_px: f32,
    ascent_px: f32,
    char_width_px: f32,
    start_position: DisplayRowPosition,
) -> GlyphRow {
    let mut source = crate::buffer_source::row_route::BufferPlainItemSource::text_only(
        buf_id,
        snapshot,
        start,
        end,
        RenderFaceRef::FaceId(base_face_id),
    );
    let mut font_metrics = None;
    let mut renderer =
        DisplayRowRenderer::new(&mut font_metrics, DisplayRowMeasurementMode::LogicalCells);
    let table = FaceTable::new();
    let resolver = FaceResolver::new(&table, 0x00ff_ffff, 0x0000_0000, 14.0, None);
    let mut face_ids = FrameFaceAttempt::for_test_with_next_id(base_face_id.get() + 1);
    DisplayRowSourceFragmentFrame::new(
        DisplayRowGeometry::new(
            0.0,
            width_px,
            height_px,
            char_width_px,
            ascent_px,
            DisplayTabPolicy::every(8),
        ),
        GlyphRowRole::Text,
        base_face_id,
        resolver.default_face(),
    )
    .render_request(DisplayRowRenderBounds::new(
        start_position,
        DisplayRowMaxX::Bounded(width_px),
    ))
    .render(&mut renderer, &mut source, &resolver, &mut face_ids)
    .expect("ascii item prefix shadow row")
    .into_row()
}

/// Lay out `text` in a fresh frame and return the enabled text rows of the
/// selected window plus the frame char metrics, for ascii-route shadow tests.
fn layout_main_text_rows(
    text: &str,
) -> (
    Context,
    BufferId,
    Vec<neomacs_display_protocol::glyph_matrix::MatrixRow>,
    f32,
    f32,
) {
    let (eval, buf_id, _frame_id, rows, char_width, char_height) =
        layout_main_text_rows_with(text, |_, _| {});
    (eval, buf_id, rows, char_width, char_height)
}

/// [`layout_main_text_rows`] with a setup hook (text properties, variables)
/// run between buffer fill and layout, also returning the frame id so shadow
/// helpers can reconstruct the engine's face-resolver inputs.
fn layout_main_text_rows_with(
    text: &str,
    setup: impl FnOnce(&mut Context, BufferId),
) -> (
    Context,
    BufferId,
    neovm_core::window::FrameId,
    Vec<neomacs_display_protocol::glyph_matrix::MatrixRow>,
    f32,
    f32,
) {
    layout_main_text_rows_with_width(text, 640, setup)
}

fn layout_main_text_rows_with_graphical_frame(
    text: &str,
    setup: impl FnOnce(&mut Context, BufferId),
) -> (
    Context,
    BufferId,
    neovm_core::window::FrameId,
    Vec<neomacs_display_protocol::glyph_matrix::MatrixRow>,
    f32,
    f32,
) {
    layout_main_text_rows_with_width_and_frame_kind(text, 640, true, setup)
}

fn layout_main_text_rows_with_width(
    text: &str,
    frame_width_px: u32,
    setup: impl FnOnce(&mut Context, BufferId),
) -> (
    Context,
    BufferId,
    neovm_core::window::FrameId,
    Vec<neomacs_display_protocol::glyph_matrix::MatrixRow>,
    f32,
    f32,
) {
    layout_main_text_rows_with_width_and_frame_kind(text, frame_width_px, false, setup)
}

fn layout_main_text_rows_with_width_and_frame_kind(
    text: &str,
    frame_width_px: u32,
    graphical: bool,
    setup: impl FnOnce(&mut Context, BufferId),
) -> (
    Context,
    BufferId,
    neovm_core::window::FrameId,
    Vec<neomacs_display_protocol::glyph_matrix::MatrixRow>,
    f32,
    f32,
) {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(text);
    }
    setup(&mut eval, buf_id);
    let frame_id = eval.frame_manager_mut().create_frame(
        "layout-ascii-route-shadow",
        frame_width_px,
        160,
        buf_id,
    );
    if graphical {
        eval.frame_manager_mut()
            .get_mut(frame_id)
            .expect("frame")
            .set_window_system(Some(Value::symbol("neo")));
    }
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let rows: Vec<_> = entry
        .matrix
        .rows
        .iter()
        .filter(|row| row.enabled && row.role == GlyphRowRole::Text)
        .cloned()
        .collect();
    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let (char_width, char_height) = (frame.char_width, frame.char_height);
    (eval, buf_id, frame_id, rows, char_width, char_height)
}

/// Glyph-for-glyph shadow assertion: the item-renderer row must equal the
/// buffer-pipeline row COMPLETELY (glyph type, buffer position, face id,
/// pixel geometry, wide/padding flags) — including the appended GNU newline
/// space, which the routed source produces through the shared line-end seam
/// when it emits the row-break item.
fn assert_plain_shadow_row_matches(
    main_row: &neomacs_display_protocol::glyph_matrix::MatrixRow,
    shadow_row: &GlyphRow,
) {
    assert_eq!(
        shadow_row.glyphs[1], main_row.glyphs[1],
        "item-renderer row must equal the buffer-pipeline row glyph-for-glyph"
    );
}

/// The realized face id of the first text glyph on a main-pipeline row: the
/// window's base text face, fed to the shadow renderer so both paths realize
/// glyphs against the same face identity.
fn main_row_base_face_id(row: &neomacs_display_protocol::glyph_matrix::MatrixRow) -> FaceId {
    row.glyphs[1].first().expect("main row glyph").face_id
}

fn plain_route_classification<B: crate::neovm_bridge::LayoutBufferView>(
    buffer: &B,
    text: &[u8],
    byte_idx: usize,
    charpos: i64,
    char_width: f32,
    right_edge_px: f32,
    point_charpos: i64,
) -> crate::buffer_source::row_route::RowAcquisitionRoute {
    crate::buffer_source::row_route::RowAcquisitionRoute::of(
        &crate::buffer_source::row_route::plan_plain_row_classified(
            buffer,
            crate::buffer_source::row_route::RowRouteRowStart {
                text,
                byte_idx,
                charpos,
                text_start_byte: 0,
            },
            crate::buffer_source::row_route::RowRouteFit {
                start_position: DisplayRowPosition::new(0.0, 0),
                char_width_px: char_width,
                right_edge_px,
                tab_policy: &DisplayTabPolicy::every(8),
            },
            crate::buffer_source::row_route::RowRouteWindowPolicy {
                point_charpos,
                hscroll_active: false,
                selective_display: 0,
                word_wrap: false,
                show_trailing_whitespace: false,
                wrap_mode: crate::types::LineWrapMode::Truncate,
                overlay_string_window: Some(0),
            },
        ),
    )
}

#[test]
fn plain_item_source_shadow_matches_main_buffer_plain_row() {
    let text = "hello world\n";
    let (eval, buf_id, rows, char_width, char_height) = layout_main_text_rows(text);
    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let snapshot = LayoutBufferSnapshot::from_buffer(buffer);

    assert_eq!(
        plain_route_classification(
            &snapshot,
            text.as_bytes(),
            0,
            0,
            char_width,
            640.0,
            text.chars().count() as i64
        ),
        crate::buffer_source::row_route::RowAcquisitionRoute::ItemRenderer
    );

    let line_end = CharPos0::new("hello world".chars().count());
    let shadow_row = render_buffer_plain_item_source_shadow_row(
        buf_id,
        &snapshot,
        CharPos0::ZERO,
        line_end,
        main_row_base_face_id(&rows[0]),
        640.0,
        char_height,
        char_height,
        char_width,
    );
    assert_plain_shadow_row_matches(&rows[0], &shadow_row);
}

