/// Increment 2i rung 2 shadow proof (flipping the former 2d rung-2 refusal
/// pin): a plain single-line string-valued `display` property now ROUTES,
/// and the routed row is glyph-for-glyph identical to the buffer pipeline's
/// — including GNU string-index provenance plus its exact covered buffer range
/// (N string glyphs for M covered chars) and the string session's base-face
/// resolution, because the
/// routed commit drives the pipeline's OWN replacement session. The
/// pipeline side is produced in the same process by putting point on the
/// row (the PointInRow refusal), which changes cursor capture only, never
/// row glyphs.
#[test]
fn display_string_replacement_row_routes_and_matches_pipeline() {
    let text = "abXXcd\nnext\n";
    let put_replacement = |eval: &mut Context, buf_id: BufferId| {
        eval.buffer_manager_mut().set_current(buf_id);
        eval.eval_str("(put-text-property 3 5 'display \"STR\")")
            .expect("display string replacement");
    };

    // Pipeline side: point inside row 0 refuses the route (PointInRow), so
    // the buffer pipeline renders the replacement row.
    let (_eval_pipeline, _buf_pipeline, _fid_p, rows_pipeline, _cw_p, _ch_p) =
        layout_main_text_rows_with(text, |eval, buf_id| {
            put_replacement(eval, buf_id);
            eval.eval_str("(goto-char 2)").expect("point on row 0");
        });
    assert_eq!(
        glyphs_logical_text(&rows_pipeline[0].glyphs[1]),
        "abSTRcd ",
        "the pipeline must replace the covered span"
    );

    // Routed side: point stays at end-of-buffer (row 1), so the classifier
    // accepts row 0 and the routed commit renders it via the replacement
    // session. The engagement counter proves the route actually fired.
    let routed_before = crate::buffer_source::row_route::ROUTED_REPLACEMENT_ROW_COUNT
        .load(std::sync::atomic::Ordering::Relaxed);
    let (eval, buf_id, _fid_r, rows_routed, char_width, _ch_r) =
        layout_main_text_rows_with(text, put_replacement);
    assert!(
        crate::buffer_source::row_route::ROUTED_REPLACEMENT_ROW_COUNT
            .load(std::sync::atomic::Ordering::Relaxed)
            > routed_before,
        "the replacement row must render through the routed acquisition"
    );

    // Glyph-for-glyph identity: type, charpos provenance, face id, pixel
    // geometry, wide/padding flags.
    assert_eq!(
        rows_routed[0].glyphs[1], rows_pipeline[0].glyphs[1],
        "routed replacement row must equal the pipeline row glyph-for-glyph"
    );
    // The GNU shape explicitly: glyphs 'S','T','R' carry indices 0,1,2 in one
    // string object, while the separate buffer range remains [2,4).
    let replacement = &rows_routed[0].glyphs[1][2..5];
    let GlyphProvenance::Str { source, .. } = replacement[0].provenance else {
        panic!("replacement glyph must be string-sourced");
    };
    let covered = GlyphStringBufferRange::new(2, 4);
    assert_eq!(
        rows_routed[0]
            .string_source(source)
            .and_then(|source| source.covered_buffer_range()),
        Some(covered),
        "replacement coverage belongs to the row occurrence"
    );
    for (index, glyph) in replacement.iter().enumerate() {
        assert_eq!(
            glyph.provenance,
            GlyphProvenance::string(source, index),
            "replacement glyphs advance in string coordinates"
        );
    }
    // Direct classification agrees with production (point on row 1's text).
    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let snapshot = LayoutBufferSnapshot::from_buffer(buffer);
    assert_eq!(
        plain_route_classification(
            &snapshot,
            text.as_bytes(),
            0,
            0,
            char_width,
            640.0,
            text.chars().count() as i64
        ),
        crate::buffer_source::row_route::RowAcquisitionRoute::ItemRenderer,
        "display-string rows in the routed class must route"
    );
}

/// Increment 2i rung 2: the shapes that STAY refused after the flip, pinned
/// at engine level with identical output either way: a display string
/// carrying its own text properties (per-run string faces) and a display
/// string containing a newline (multi-row session). Provenance now EXISTS
/// (the typed string-index + covered-range vocabulary and session reuse);
/// these remain outside
/// the routed class because the plan's single-run width prediction does not
/// model per-run string faces, and a mid-string row break hands mid-line
/// state back to the walk.
#[test]
fn propertized_display_string_rows_stay_on_buffer_pipeline_under_item_route() {
    let text = "abXXcd\nnext\n";
    let (eval, buf_id, rows, char_width, _char_height) = {
        let (eval, buf_id, _frame_id, rows, char_width, char_height) =
            layout_main_text_rows_with(text, |eval, buf_id| {
                eval.buffer_manager_mut().set_current(buf_id);
                eval.eval_str("(put-text-property 3 5 'display (propertize \"STR\" 'face 'bold))")
                    .expect("propertized display string");
            });
        (eval, buf_id, rows, char_width, char_height)
    };
    assert_eq!(glyphs_logical_text(&rows[0].glyphs[1]), "abSTRcd ");
    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let snapshot = LayoutBufferSnapshot::from_buffer(buffer);
    assert_eq!(
        plain_route_classification(
            &snapshot,
            text.as_bytes(),
            0,
            0,
            char_width,
            640.0,
            text.chars().count() as i64
        ),
        crate::buffer_source::row_route::RowAcquisitionRoute::BufferPipeline,
        "a propertized display string must keep the buffer pipeline"
    );
}

/// Increment 2i rung 3 shadow proof (flipping the former 2d rung-3 refusal
/// pin): a plain `(space :width N)` display spec now ROUTES, rendering
/// through the pipeline's replacement session — one stretch glyph of exactly
/// N canonical char widths with covered-buffer provenance (GNU stamps the
/// covered buffer position on stretch glyphs, xdisp.c 6604 + 32684). The
/// routed row is glyph-for-glyph identical to the buffer-pipeline row (same
/// process, point placement toggles the route).
#[test]
fn space_width_spec_row_routes_and_matches_pipeline() {
    let text = "ab cd\nnext\n";
    let put_spec = |eval: &mut Context, buf_id: BufferId| {
        eval.buffer_manager_mut().set_current(buf_id);
        eval.eval_str("(put-text-property 3 4 'display '(space :width 3))")
            .expect("space width spec");
    };

    // Pipeline side: point inside row 0 refuses the route.
    let (_e_p, _b_p, _f_p, rows_pipeline, char_width, _c_p) =
        layout_main_text_rows_with(text, |eval, buf_id| {
            put_spec(eval, buf_id);
            eval.eval_str("(goto-char 2)").expect("point on row 0");
        });
    let stretch = rows_pipeline[0].glyphs[1]
        .iter()
        .find(|glyph| matches!(glyph.glyph_type, GlyphType::Stretch { .. }))
        .expect("the space spec must render a stretch glyph");
    assert_eq!(
        stretch.pixel_width,
        3.0 * char_width,
        "(space :width 3) must stretch exactly three canonical char widths"
    );

    // Routed side: point at end-of-buffer (row 1).
    let routed_before = crate::buffer_source::row_route::ROUTED_REPLACEMENT_ROW_COUNT
        .load(std::sync::atomic::Ordering::Relaxed);
    let (eval, buf_id, _f_r, rows_routed, _cw_r, _c_r) = layout_main_text_rows_with(text, put_spec);
    assert!(
        crate::buffer_source::row_route::ROUTED_REPLACEMENT_ROW_COUNT
            .load(std::sync::atomic::Ordering::Relaxed)
            > routed_before,
        "the space-spec row must render through the routed acquisition"
    );
    assert_eq!(
        rows_routed[0].glyphs[1], rows_pipeline[0].glyphs[1],
        "routed space-spec row must equal the pipeline row glyph-for-glyph"
    );
    // Provenance: GNU stamps the COVERED buffer position on a spec-produced
    // stretch glyph (xdisp.c:6600-6606 sets it->position = start_pos, and
    // append_stretch_glyph stamps CHARPOS of it, xdisp.c:32684). This pin
    // used to record the shared divergence - both paths left Glyph::stretch's
    // charpos 0 - and asked that a future provenance fix update them
    // together. It did: the stamp is now the covered start on both, which is
    // what the glyph-for-glyph assertion above keeps honest.
    let routed_stretch = rows_routed[0].glyphs[1]
        .iter()
        .find(|glyph| matches!(glyph.glyph_type, GlyphType::Stretch { .. }))
        .expect("routed stretch glyph");
    assert_eq!(
        routed_stretch.legacy_charpos(),
        2,
        "the stretch stamps the covered range's start on both paths"
    );
    let buffer = eval.buffer_manager().get(buf_id).expect("buffer");
    let snapshot = LayoutBufferSnapshot::from_buffer(buffer);
    assert_eq!(
        plain_route_classification(
            &snapshot,
            text.as_bytes(),
            0,
            0,
            char_width,
            640.0,
            text.chars().count() as i64
        ),
        crate::buffer_source::row_route::RowAcquisitionRoute::ItemRenderer,
        "plain space-spec rows in the routed class must route"
    );
}

#[test]
fn layout_frame_rust_preserves_multiline_overlay_output_rows() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("x");
        let overlay = Value::make_overlay(neovm_core::heap_types::OverlayDataInit {
            serial: 0,
            plist: Value::NIL,
            buffer: Some(buf_id),
            start: 0,
            end: 1,
            front_advance: false,
            rear_advance: false,
        });
        buf.overlays_mut().insert_overlay(overlay);
        let _ = buf.overlays_mut().overlay_put(
            overlay,
            Value::symbol("after-string"),
            Value::string("A\nB"),
        );
        let point = buf.point_max_char_pos().get() + 1;
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(point - 1));
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-overlay-output-rows", 640, 160, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    let snapshot = frame
        .redisplay_snapshot(selected_window)
        .expect("window display snapshot");
    let display = frame
        .find_window(selected_window)
        .and_then(|window| window.display())
        .expect("window display state");
    assert!(
        snapshot
            .rows
            .iter()
            .any(|row| row.row == 0 && row.start_buffer_pos.is_some()),
        "expected first text row snapshot to survive multiline overlay output, rows={:?}",
        snapshot.rows
    );
    assert!(
        snapshot.rows.iter().any(|row| row.row == 1),
        "expected multiline overlay output to publish a second text row, rows={:?}",
        snapshot.rows
    );
    assert!(
        display.output_cursor.is_some_and(|cursor| cursor.row >= 1),
        "expected live output cursor to advance onto multiline overlay rows, output={:?}",
        display.output_cursor
    );
}

#[test]
fn layout_frame_rust_renders_overlay_string_tabs_as_stretches() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("x");
        let overlay = Value::make_overlay(neovm_core::heap_types::OverlayDataInit {
            serial: 0,
            plist: Value::NIL,
            buffer: Some(buf_id),
            start: 0,
            end: 1,
            front_advance: false,
            rear_advance: false,
        });
        buf.overlays_mut().insert_overlay(overlay);
        let _ = buf.overlays_mut().overlay_put(
            overlay,
            Value::symbol("after-string"),
            Value::string("a\tb"),
        );
    }

    let frame_id =
        eval.frame_manager_mut()
            .create_frame("layout-overlay-tab-string", 640, 160, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let text_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text)
        .expect("text row");

    let logical_text = glyphs_logical_text(&text_row.glyphs[1]);
    assert!(
        !logical_text.contains('\t'),
        "overlay tab should not render as a literal tab, row={:?}",
        text_row.glyphs[1]
    );
    assert!(
        logical_text.contains("a      b"),
        "overlay tab should expand to the next tab stop, text={logical_text:?}"
    );
    assert!(
        text_row.glyphs[1]
            .iter()
            .any(|glyph| matches!(glyph.glyph_type, GlyphType::Stretch { width_cols: 6 })),
        "overlay tab should be a stretch glyph, row={:?}",
        text_row.glyphs[1]
    );
}

#[test]
fn layout_frame_rust_aligns_dired_filenames_after_nerd_icon_tabs() {
    let mut eval = Context::new();
    eval.eval_str(r#"(set-fontset-font t '(#xf48a . #xf48a) "JetBrainsMono Nerd Font")"#)
        .expect("install GNU-observed Dired icon fallback");
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let text = concat!(
        "  -rw-r--r-- 1 exec users 142286 Jul 28 00:11 main.rs\n",
        "  -rw-r--r-- 1 exec users  63333 Aug  3 16:37 main_test.rs\n",
    );
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert(text);
        // nerd-icons-dired makes this buffer-local so the icon suffix TAB is
        // only one logical tab column wide.
        buf.set_buffer_local("tab-width", Value::fixnum(1));
        buf.set_buffer_local(
            "face-remapping-alist",
            Value::list(vec![Value::list(vec![
                Value::symbol("default"),
                Value::list(vec![
                    Value::keyword("family"),
                    Value::string("JetBrainsMono Nerd Font"),
                ]),
                Value::symbol("default"),
            ])]),
        );

        for (serial, filename) in ["main.rs", "main_test.rs"].into_iter().enumerate() {
            let filename_start = text.find(filename).expect("fixture filename");
            let icon_and_tab = Value::string_with_text_properties(
                "\u{f48a}\t",
                vec![StringTextPropertyRun {
                    start: 0,
                    end: 1,
                    plist: Value::list(vec![
                        Value::symbol("face"),
                        Value::list(vec![
                            Value::keyword("family"),
                            Value::string("Symbols Nerd Font Mono"),
                        ]),
                    ]),
                }],
            );
            // nerd-icons-dired wraps the icon string in a `display' property
            // before installing it as an overlay after-string.
            let icon_face = Value::list(vec![
                Value::keyword("family"),
                Value::string("Symbols Nerd Font Mono"),
            ]);
            let after_string = Value::string_with_text_properties(
                "\u{f48a}\t",
                vec![
                    // `propertize' preserves the icon's existing face while
                    // adding the replacement `display' property.
                    StringTextPropertyRun {
                        start: 0,
                        end: 1,
                        plist: Value::list(vec![
                            Value::symbol("face"),
                            icon_face,
                            Value::symbol("display"),
                            icon_and_tab,
                        ]),
                    },
                    StringTextPropertyRun {
                        start: 1,
                        end: 2,
                        plist: Value::list(vec![Value::symbol("display"), icon_and_tab]),
                    },
                ],
            );
            let overlay = Value::make_overlay(neovm_core::heap_types::OverlayDataInit {
                serial: serial as u64,
                plist: Value::NIL,
                buffer: Some(buf_id),
                start: filename_start - 1,
                end: filename_start,
                front_advance: false,
                rear_advance: false,
            });
            buf.overlays_mut().insert_overlay(overlay);
            let _ = buf.overlays_mut().overlay_put(
                overlay,
                Value::symbol("after-string"),
                after_string,
            );
        }
    }

    let frame_id = eval.frame_manager_mut().create_frame(
        "layout-dired-nerd-icon-tab-alignment",
        1600,
        180,
        buf_id,
    );
    realize_test_gui_frame(&mut eval, frame_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let filename_x = |filename: &str| {
        let row = entry
            .matrix
            .rows
            .iter()
            .find(|row| {
                glyphs_logical_text(&row.glyphs[GlyphArea::Text.index()]).contains(filename)
            })
            .expect("Dired fixture row");
        let glyphs = &row.glyphs[GlyphArea::Text.index()];
        let icon = glyphs
            .iter()
            .position(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: '\u{f48a}' }))
            .expect("nerd icon glyph");
        let icon_glyph = &glyphs[icon];
        let tab_glyph = glyphs
            .get(icon + 1)
            .filter(|glyph| matches!(glyph.glyph_type, GlyphType::Stretch { .. }))
            .expect("tab stretch after nerd icon");
        let icon_face = state
            .faces
            .get(&icon_glyph.face_id)
            .expect("published nerd icon face");
        let tab_face = state
            .faces
            .get(&tab_glyph.face_id)
            .expect("published tab face");
        assert_eq!(
            icon_face.font_family, "Symbols Nerd Font Mono",
            "fixture must exercise the nerd-icons face"
        );
        assert_eq!(
            tab_face.font_family, "JetBrainsMono Nerd Font",
            "GNU ends the icon's one-character face run before the unpropertized TAB"
        );
        let binding = state
            .char_fonts
            .get(&icon_glyph.face_id)
            .and_then(|by_char| by_char.get(&'\u{f48a}'))
            .expect("finished frame must publish the icon's exact font binding");
        let resolved = state
            .fonts
            .get(&binding.resolved_font_id)
            .expect("icon binding must reference the finished frame font table");
        assert!(
            resolved.family.starts_with("JetBrainsMono")
                && !resolved
                    .family
                    .eq_ignore_ascii_case("Symbols Nerd Font Mono"),
            "GNU derives the non-ASCII icon font from the frame-default JetBrains fontset, not the inline Symbols primary; resolved={resolved:?}"
        );
        assert!(
            (icon_glyph.pixel_width - glyphs[icon + 2].pixel_width).abs() < 0.01,
            "the observed Dired icon must occupy one live default-face cell; icon={} following-cell={} row={glyphs:?}",
            icon_glyph.pixel_width,
            glyphs[icon + 2].pixel_width,
        );
        assert!(
            (tab_glyph.pixel_width - glyphs[icon + 2].pixel_width).abs() < 0.01,
            "the tab-width=1 suffix must occupy one live default-face cell; tab={} following-cell={} row={glyphs:?}",
            tab_glyph.pixel_width,
            glyphs[icon + 2].pixel_width,
        );
        row.pixel_x
            + glyphs[..=icon + 1]
                .iter()
                .map(|glyph| glyph.pixel_width)
                .sum::<f32>()
    };

    let main_x = filename_x("main.rs");
    let main_test_x = filename_x("main_test.rs");
    assert!(
        (main_x - main_test_x).abs() < 0.01,
        "GNU xdisp expands overlay-string TABs from the live row pen, keeping Dired filenames at one pixel x; main.rs={main_x} main_test.rs={main_test_x} rows={:?}",
        entry.matrix.rows,
    );
}

