#[test]
fn synchronous_window_end_query_observes_only_the_target_without_publishing_a_presentation() {
    let mut eval = Context::new();
    let buffer_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    eval.buffer_manager_mut()
        .get_mut(buffer_id)
        .expect("buffer")
        .insert(&"one two three four five six seven eight\n".repeat(20));
    let frame_id =
        eval.frame_manager_mut()
            .create_frame("targeted-window-end-query", 800, 320, buffer_id);
    let target = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    let sibling = eval
        .frame_manager_mut()
        .split_window(
            frame_id,
            target,
            neovm_core::window::SplitDirection::Horizontal,
            buffer_id,
            None,
            neovm_core::window::SplitPlacement::AfterTarget,
        )
        .expect("split");

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    let prior_presentation = engine
        .last_frame_display_state
        .as_ref()
        .expect("initial layout")
        .presentation_id;
    let prepared_id = neovm_core::window::geometry::PresentationId::new(prior_presentation.get());
    let accepted_output_before_query = eval
        .frame_manager()
        .get(frame_id)
        .and_then(|frame| frame.find_window(target))
        .and_then(neovm_core::window::Window::redisplay_output)
        .cloned()
        .expect("initial redisplay should publish atomic window output");
    assert!(
        eval.frame_manager_mut()
            .get_mut(frame_id)
            .expect("frame")
            .discard_display_presentation(prepared_id)
    );
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        frame
            .find_window_mut(target)
            .expect("target")
            .invalidate_window_end();
        frame
            .find_window_mut(sibling)
            .expect("sibling")
            .invalidate_window_end();
    }
    let target_end_before_query = eval
        .frame_manager()
        .get(frame_id)
        .and_then(|frame| frame.find_window(target))
        .and_then(neovm_core::window::Window::window_end_state);

    let _record = engine
        .query_window_layout(&mut eval, frame_id, target)
        .expect("targeted query should converge")
        .end();

    let frame = eval.frame_manager().get(frame_id).expect("frame");
    assert_eq!(
        frame
            .find_window(target)
            .expect("target")
            .window_end_state(),
        target_end_before_query,
        "GNU Fwindow_end owns a stack-local iterator and must not validate retained redisplay state"
    );
    assert!(matches!(
        frame
            .find_window(sibling)
            .expect("sibling")
            .window_end_state(),
        Some(neovm_core::window::WindowEndState::Stale(_))
    ));
    assert!(
        !frame.has_prepared_display_presentations(),
        "a logical layout query must not enter the renderer presentation lifecycle"
    );
    assert_eq!(
        engine
            .last_frame_display_state
            .as_ref()
            .expect("last real redisplay remains available")
            .presentation_id,
        prior_presentation,
        "the query must not replace the last renderer-facing frame output"
    );
    assert_eq!(
        frame
            .find_window(target)
            .expect("target")
            .redisplay_output(),
        Some(&accepted_output_before_query),
        "the query must not replace any part of the last accepted redisplay generation"
    );
}

#[test]
fn synchronous_window_end_query_on_child_frame_does_not_touch_parent_frame() {
    let mut eval = Context::new();
    let parent_buffer = eval
        .buffer_manager()
        .current_buffer()
        .expect("parent buffer")
        .id();
    eval.buffer_manager_mut()
        .get_mut(parent_buffer)
        .expect("parent buffer")
        .insert(&"parent frame line\n".repeat(80));
    let child_buffer = eval
        .buffer_manager_mut()
        .create_buffer(" *window-end-child*");
    eval.buffer_manager_mut()
        .get_mut(child_buffer)
        .expect("child buffer")
        .insert(&"child frame line with 好🙂β\n".repeat(80));

    let parent_frame =
        eval.frame_manager_mut()
            .create_frame("window-end-parent", 800, 320, parent_buffer);
    let child_frame =
        eval.frame_manager_mut()
            .create_frame("window-end-child", 360, 180, child_buffer);
    let parent_window = eval
        .frame_manager()
        .get(parent_frame)
        .expect("parent frame")
        .selected_window;
    let child_window = eval
        .frame_manager()
        .get(child_frame)
        .expect("child frame")
        .selected_window;
    eval.frame_manager_mut()
        .get_mut(child_frame)
        .expect("child frame")
        .parent_frame = Value::make_frame(parent_frame.0);

    let parent_record = {
        let buffer = eval
            .buffer_manager()
            .get(parent_buffer)
            .expect("parent buffer");
        neovm_core::window::WindowEndRecord::from_positions(
            neovm_core::buffer::LispCharPos1::from_one_based_usize(
                buffer.point_max_char_pos().get() + 1,
            ),
            buffer.point_max_emacs_byte_pos(),
            neovm_core::buffer::LispCharPos1::new(40),
            buffer.lisp_pos_to_emacs_byte_pos(neovm_core::buffer::LispCharPos1::new(40)),
            neovm_core::window::MatrixRow0::new(3),
        )
    };
    {
        let parent = eval
            .frame_manager_mut()
            .get_mut(parent_frame)
            .expect("parent frame")
            .find_window_mut(parent_window)
            .expect("parent window");
        parent.set_window_end_record(parent_record);
        parent.invalidate_window_end();
    }

    let mut engine = LayoutEngine::new_without_font_metrics();
    let child_end_before_query = eval
        .frame_manager()
        .get(child_frame)
        .and_then(|frame| frame.find_window(child_window))
        .and_then(neovm_core::window::Window::window_end_state);
    let _child_record = engine
        .query_window_layout(&mut eval, child_frame, child_window)
        .expect("child query should converge")
        .end();

    let parent = eval
        .frame_manager()
        .get(parent_frame)
        .expect("parent frame");
    assert_eq!(
        parent
            .find_window(parent_window)
            .expect("parent window")
            .window_end_state(),
        Some(neovm_core::window::WindowEndState::Stale(parent_record)),
        "a child-frame query must not lay out or publish into its parent"
    );
    assert!(!parent.has_prepared_display_presentations());

    let child = eval.frame_manager().get(child_frame).expect("child frame");
    assert_eq!(
        child
            .find_window(child_window)
            .expect("child window")
            .window_end_state(),
        child_end_before_query,
        "the returned child record is query-local, not retained redisplay state"
    );
    assert!(!child.has_prepared_display_presentations());
    assert!(
        engine.last_frame_display_state.is_none(),
        "a child-frame query must remain outside renderer publication"
    );
}

#[test]
fn synchronous_window_end_query_preserves_redisplay_only_window_state() {
    let mut eval = Context::new();
    let buffer_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    eval.buffer_manager_mut()
        .get_mut(buffer_id)
        .expect("buffer")
        .insert(&"line with enough text to wrap in a narrow window\n".repeat(80));
    let frame_id = eval.frame_manager_mut().create_frame(
        "side-effect-free-window-end-query",
        320,
        240,
        buffer_id,
    );
    let window_id = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;
    eval.eval_form(Value::list(vec![
        Value::symbol("set-window-start"),
        Value::make_window(window_id.0),
        Value::fixnum(240),
    ]))
    .expect("set explicit window start");

    let before = match eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .find_window(window_id)
        .expect("window")
    {
        neovm_core::window::Window::Leaf {
            window_start,
            point,
            force_start,
            ..
        } => (*window_start, *point, *force_start),
        other => panic!("expected leaf, got {other:?}"),
    };
    assert!(before.2, "set-window-start should arm force_start");

    let mut engine = LayoutEngine::new();
    let end_with_point_before_start = engine
        .query_window_layout(&mut eval, frame_id, window_id)
        .expect("exact query should converge")
        .end();

    let after = match eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .find_window(window_id)
        .expect("window")
    {
        neovm_core::window::Window::Leaf {
            window_start,
            point,
            force_start,
            ..
        } => (*window_start, *point, *force_start),
        other => panic!("expected leaf, got {other:?}"),
    };
    assert_eq!(
        after, before,
        "GNU Fwindow_end UPDATE walks from w->start but does not consume \
         force_start, rewrite the start marker, or move point"
    );

    let start = neovm_core::buffer::LispCharPos1::new(240);
    let start_byte = eval
        .buffer_manager()
        .get(buffer_id)
        .expect("buffer")
        .lisp_pos_to_emacs_byte_pos(start);
    eval.buffer_manager_mut()
        .goto_buffer_emacs_byte_pos(buffer_id, start_byte)
        .expect("move selected buffer point to window start");
    eval.set_window_point_for_redisplay(frame_id, window_id, start);
    let end_with_point_at_start = engine
        .query_window_layout(&mut eval, frame_id, window_id)
        .expect("control query should converge")
        .end();
    assert_eq!(
        end_with_point_before_start, end_with_point_at_start,
        "GNU Fwindow_end UPDATE walks from w->start, so its answer is \
         independent of point visibility"
    );
}

/// An active minibuffer holding a prompt line plus several candidate lines
/// must grow to one display row per logical line, render every line, and never
/// flatten content into one row.  Exercises the active-fido/vertico measure
/// path the unclamped GNU `resize_mini_window` walk now drives.
fn assert_active_minibuffer_grows_for_multiline_content(use_gui_metrics: bool) {
    let rows = layout_active_minibuffer_rows(
        "Find file: cand\nalpha.el\nbeta.el\ngamma.el",
        10,
        use_gui_metrics,
    );

    for needle in ["Find file: cand", "alpha.el", "beta.el", "gamma.el"] {
        assert!(
            rows.iter().any(|row| row.contains(needle)),
            "expected active minibuffer to grow and render {needle:?}, rows={rows:?}"
        );
    }
    assert!(
        !rows.iter().any(|row| row.contains("candalpha")),
        "multiline minibuffer content was flattened into one row: {rows:?}"
    );
    let content_rows = rows.iter().filter(|row| !row.trim().is_empty()).count();
    assert!(
        content_rows >= 4,
        "expected four content rows (one per logical line), got {content_rows}: {rows:?}"
    );
}

#[test]
fn active_minibuffer_grows_for_multiline_content_tty() {
    assert_active_minibuffer_grows_for_multiline_content(false);
}

#[test]
fn active_minibuffer_grows_for_multiline_content_gui() {
    assert_active_minibuffer_grows_for_multiline_content(true);
}

#[test]
fn active_minibuffer_that_grows_to_fit_resets_start_to_point_min() {
    let mut eval = Context::new();
    eval.obarray_mut()
        .set_symbol_value("resize-mini-windows", Value::symbol("grow-only"));
    eval.obarray_mut()
        .set_symbol_value("max-mini-window-height", Value::make_float(0.25));

    let root_buffer = eval
        .buffer_manager()
        .current_buffer()
        .expect("root buffer")
        .id();
    let minibuffer = eval.buffer_manager_mut().create_buffer(" *Minibuf-1*");
    let frame_id =
        eval.frame_manager_mut()
            .create_frame("minibuffer-start-after-grow", 160, 50, root_buffer);
    {
        let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
        frame.char_width = 1.0;
        frame.char_height = 1.0;
        frame.shrink_mini_window();
    }
    let minibuffer_window = eval
        .activate_minibuffer_window_for_buffer(minibuffer, LispString::from_utf8("Oracle: "), None)
        .expect("activate minibuffer")
        .expect("minibuffer window");
    eval.eval_form(Value::list(vec![
        Value::symbol("select-window"),
        Value::make_window(minibuffer_window.0),
    ]))
    .expect("select active minibuffer");

    let mut engine = LayoutEngine::new_without_font_metrics();
    engine.layout_frame_rust(&mut eval, frame_id);
    {
        let buffer = eval
            .buffer_manager_mut()
            .get_mut(minibuffer)
            .expect("minibuffer");
        for _ in 0..8 {
            buffer.insert("candidate-好β-abcdefghij\n");
        }
        let eob = buffer.point_max_emacs_byte_pos();
        buffer.goto_emacs_byte_pos(eob);
    }
    engine.layout_frame_rust(&mut eval, frame_id);

    let start = match eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .find_window(minibuffer_window)
        .expect("active minibuffer")
    {
        neovm_core::window::Window::Leaf { window_start, .. } => *window_start,
        other => panic!("expected leaf, got {other:?}"),
    };
    assert_eq!(
        start,
        neovm_core::buffer::LispCharPos1::ONE,
        "GNU resize_mini_window sets w->start to BEGV whenever all content \
         fits below max-mini-window-height"
    );
}

#[test]
