/// Child-frame independence (Slice 4 characterization; guards the Slice 5
/// mock-frame migration + the posframe face/width-independence property).
///
/// A detached child frame must carry its OWN identity (frame_id/parent_*/z_order),
/// resolve its OWN faces, and derive its OWN text width — never inherit the
/// parent's. Here an 800px parent and a 200px child must produce different
/// column counts, and the child state must report its own frame identity.
#[test]
fn child_frame_resolves_faces_and_width_independently_from_parent() {
    use crate::mock_frame::{
        MockChildFrameContent, MockFrameContent, MockStyledLine, MockWindowContent,
    };
    use neomacs_display_protocol::face::Face;
    use neomacs_display_protocol::types::{Color, Rect};

    let char_w = 8.0;
    let char_h = 16.0;

    let content = MockFrameContent {
        frame_id: 1,
        faces: vec![Face::new(FaceId::new(0))],
        windows: vec![MockWindowContent {
            window_id: 1,
            lines: vec![MockStyledLine::from_str(
                "parent buffer text",
                FaceId::new(0),
            )],
            mode_line: MockStyledLine::from_str("-- parent --", FaceId::new(0)),
            // Wide parent window: 800px / 8px = 100 cols.
            pixel_bounds: Rect::new(0.0, 0.0, 800.0, 15.0 * char_h),
            selected: true,
            truncated_lines: false,
        }],
        child_frames: vec![MockChildFrameContent {
            frame_id: 100,
            window: MockWindowContent {
                window_id: 2,
                lines: vec![MockStyledLine::from_str("child", FaceId::new(0))],
                mode_line: MockStyledLine::from_str("", FaceId::new(0)),
                // Narrow child: 200px / 8px = 25 cols — independent of the parent.
                pixel_bounds: Rect::new(0.0, 0.0, 200.0, 3.0 * char_h),
                selected: false,
                truncated_lines: false,
            },
            parent_x: 120.0,
            parent_y: 48.0,
            z_order: 1,
        }],
        frame_pixel_width: 800.0,
        frame_pixel_height: 16.0 * char_h,
        background: Color::from_pixel(0x00112233),
        menu_bar: None,
        minibuffer: Some(MockWindowContent {
            window_id: 999,
            lines: vec![MockStyledLine::from_str("", FaceId::new(0))],
            mode_line: MockStyledLine::from_str("", FaceId::new(0)),
            pixel_bounds: Rect::new(0.0, 15.0 * char_h, 800.0, char_h),
            selected: false,
            truncated_lines: false,
        }),
    };

    let mut engine = LayoutEngine::new();
    let states = engine.layout_mock_frame(&content, char_w, char_h);

    assert!(states.len() >= 2, "expected a parent + child frame state");
    let parent = &states[0];
    let child = &states[1];

    // The child carries its OWN identity, not the parent's.
    assert_eq!(child.frame_placement.frame().get(), 100);
    assert_eq!(
        child.frame_placement.parent().unwrap().get(),
        content.frame_id
    );
    assert_eq!(child.frame_placement.outer_in_parent().x(), 120.0);
    assert_eq!(child.frame_placement.outer_in_parent().y(), 48.0);
    assert_eq!(child.frame_placement.z_order(), 1);

    // The child resolves its own face map (not an empty/parent-shared identity).
    assert!(
        !child.faces.is_empty(),
        "child frame must resolve its own faces"
    );

    // The child's text width is independent of the parent's: 200px vs 800px
    // produce different column counts.
    let parent_cols = parent.window_matrices[0].matrix.ncols;
    let child_cols = child.window_matrices[0].matrix.ncols;
    assert_ne!(
        child_cols, parent_cols,
        "child width (200px) must derive its own ncols, not inherit the parent (800px): child={child_cols} parent={parent_cols}"
    );
}

/// Frame-snapshot contract: the display state must identify windows by
/// buffer NAME (not just file name) and realized faces by their Lisp face
/// name, so agents can assert on them from snapshot JSON/text.
#[test]
fn window_info_carries_buffer_name_and_faces_carry_lisp_names() {
    let mut eval = Context::new();
    convert_current_buffer_text_backend(&mut eval, BufferTextBackendKind::GapBuffer);
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    insert_fragmented_current_buffer_text(&mut eval, "snapshot names\n");
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("snapshot-names", 360, 180, buf_id);

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");

    let info = state
        .window_infos
        .iter()
        .find(|w| !w.is_minibuffer)
        .expect("non-minibuffer window info");
    assert!(
        !info.buffer_name.is_empty(),
        "buffer_name must be populated: {info:?}"
    );
    assert!(
        state
            .faces
            .values()
            .any(|f| f.lisp_name.as_deref() == Some("default")),
        "realized default face must carry its Lisp name: {:?}",
        state
            .faces
            .values()
            .map(|f| (f.id, f.lisp_name.clone()))
            .collect::<Vec<_>>()
    );
}

/// Phase 3 — a PLAIN (non-font-locked) edit takes the localized-edit fast path:
/// the rows ABOVE the edit are reused verbatim and only the edited line + the
/// rows below it are re-walked.
#[test]
fn phase3_plain_edit_is_localized() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _win) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    let m = measure_incremental_relayout(&mut engine, &mut eval, frame_id, |eval| {
        // Plain insert on line 10 (no fontification → props tick unchanged).
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(10 * 24 + 5));
        buffer.insert("x");
    });
    assert!(m.total_body_rows > 0, "expected body rows laid out");
    assert_eq!(
        m.stats.edit_windows, 1,
        "selected window took the localized-edit fast path (got {:?})",
        m.stats
    );
    assert!(
        m.stats.reused_rows > 0,
        "rows above the edit reused verbatim (got {:?})",
        m.stats
    );
    assert!(
        m.stats.relaid_body_rows > 0,
        "the edited line + rows below relaid (got {:?})",
        m.stats
    );
    assert_eq!(
        m.stats.reused_rows + m.stats.relaid_body_rows,
        m.total_body_rows,
        "body rows conserved (got {:?})",
        m.stats
    );
}

/// Phase 3 GOLDEN — localized-edit output must be BYTE-IDENTICAL to a full
/// rebuild of the same edited state.
#[test]
fn phase3_plain_edit_matches_full_rebuild_golden() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let edit_at = 10 * 24 + 5;

    let (mut eval_ref, frame_ref, buf_ref, _wr) = incr_editing_frame(&text, 800, 600);
    {
        let buffer = eval_ref
            .buffer_manager_mut()
            .get_mut(buf_ref)
            .expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buffer.insert("x");
    }
    let mut ref_engine = LayoutEngine::new();
    ref_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let reference = selected_window_layout_trace(&eval_ref, &ref_engine, frame_ref);

    let (mut eval, frame_id, buf_id, _wi) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buffer.insert("x");
    }
    engine.layout_frame_rust(&mut eval, frame_id);
    assert_eq!(
        engine.last_layout_stats().edit_windows,
        1,
        "expected the measured pass to take the localized-edit fast path"
    );
    let incremental = selected_window_layout_trace(&eval, &engine, frame_id);

    assert_eq!(
        incremental, reference,
        "localized-edit output must be byte-identical to a full rebuild"
    );
}

/// GNU's `try_window_id` validates the regenerated row even when the old row
/// contains only its newline.  Inserting the first visible character into an
/// empty line must therefore produce the same matrix through localized edit
/// replay as through an engine with no retained state.
#[test]
fn phase3_insert_into_empty_line_matches_full_rebuild_golden() {
    let text = "zero\nalpha\n\nbeta\n";
    let edit_at = "zero\nalpha\n".len();

    let (mut eval_ref, frame_ref, buf_ref, _reference_window) = incr_editing_frame(text, 800, 600);
    {
        let buffer = eval_ref
            .buffer_manager_mut()
            .get_mut(buf_ref)
            .expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buffer.insert("X");
    }
    let mut reference_engine = LayoutEngine::new();
    reference_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let reference = selected_window_layout_trace(&eval_ref, &reference_engine, frame_ref);

    let (mut eval, frame_id, buf_id, _incremental_window) = incr_editing_frame(text, 800, 600);
    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .insert("X");
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        engine.last_layout_stats().edit_windows,
        1,
        "the empty-line insertion must exercise localized edit replay"
    );
    let incremental_state = engine
        .last_frame_display_state
        .as_ref()
        .expect("incremental display state");
    let incremental_window =
        incremental_state
            .window_matrices
            .iter()
            .find(|window| {
                window.matrix.rows.iter().any(|row| {
                    glyphs_logical_text(&row.glyphs[GlyphArea::Text.index()]).contains('X')
                })
            })
            .expect("window containing the inserted character");
    let inserted_row = incremental_window
        .matrix
        .rows
        .iter()
        .position(|row| glyphs_logical_text(&row.glyphs[GlyphArea::Text.index()]).contains('X'))
        .expect("row containing the inserted character");
    assert_eq!(
        incremental_window.matrix.row_damage(inserted_row),
        neomacs_display_protocol::glyph_matrix::RowDamage::New,
        "a regenerated edit row must never be advertised to the TTY as verbatim reuse"
    );
    let incremental = selected_window_layout_trace(&eval, &engine, frame_id);
    assert_eq!(
        incremental, reference,
        "localized insertion into an empty row must match a full rebuild"
    );
}

/// A localized edit walk starts at the first damaged row, but point remains a
/// window-wide semantic input.  In particular, inserting a newline at BOL
/// moves point to the following display row, so `line-number-current-line`
/// must move with the cursor instead of following the partial walk's start.
#[test]
fn phase3_newline_edit_keeps_current_line_number_face_on_cursor_row() {
    let line = "line\n";
    let text = line.repeat(40);
    let edit_at = 9 * line.len();
    let (mut eval, frame_id, buf_id, selected_window) = incr_editing_frame(&text, 800, 600);
    eval.eval_str(
        "(progn
           (internal-set-lisp-face-attribute
             'line-number :background \"#000000\" (selected-frame))
           (internal-set-lisp-face-attribute
             'line-number-current-line :background \"#ff0000\" (selected-frame)))",
    )
    .expect("make current and ordinary line-number faces observably distinct");
    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.set_buffer_local("display-line-numbers", Value::T);
        buffer.goto_emacs_byte_pos(EmacsBytePos::new(edit_at));
    }

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    let line_number_prefix_len = {
        let state = engine
            .last_frame_display_state
            .as_ref()
            .expect("warm display state");
        let window = state
            .window_matrices
            .iter()
            .find(|entry| entry.window_id.get() == selected_window.0 as i64)
            .expect("warm selected window matrix");
        window
            .matrix
            .rows
            .iter()
            .filter(|row| row.enabled && row.role == GlyphRowRole::Text)
            .find_map(|row| {
                let text_glyphs = &row.glyphs[GlyphArea::Text.index()];
                let prefix_len = text_glyphs
                    .iter()
                    .take_while(|glyph| glyph.legacy_charpos() == NO_BUFFER_POSITION_CHARPOS)
                    .count();
                (prefix_len > 0 && prefix_len < text_glyphs.len()).then_some(prefix_len)
            })
            .expect("warm frame line-number prefix before buffer text")
    };
    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .insert("\n");
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        engine.last_layout_stats().edit_windows,
        1,
        "the regression must exercise localized edit replay"
    );
    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let window = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("selected window matrix");
    let cursor_row = window
        .matrix
        .rows
        .iter()
        .position(|row| row.enabled && row.role == GlyphRowRole::Text && row.cursor_col.is_some())
        .expect("cursor row");
    // Identify every expected prefix from glyph provenance, independently of
    // the face being tested.  Otherwise a whole prefix that fell back to the
    // default face would disappear from a face-filtered assertion.
    let line_number_prefixes_by_row = window
        .matrix
        .rows
        .iter()
        .enumerate()
        .filter(|(_, row)| row.enabled && row.role == GlyphRowRole::Text)
        .map(|(row_index, row)| {
            let text_glyphs = &row.glyphs[GlyphArea::Text.index()];
            assert!(
                text_glyphs.len() >= line_number_prefix_len,
                "visible text row {row_index} lost its complete line-number prefix: expected at least {line_number_prefix_len} glyphs, row={row:?}"
            );
            (row_index, &text_glyphs[..line_number_prefix_len])
        })
        .collect::<Vec<_>>();
    assert!(
        line_number_prefixes_by_row.len() > 1,
        "the regression fixture must include non-current numbered rows"
    );
    for (row_index, prefix) in line_number_prefixes_by_row {
        assert!(
            !prefix.is_empty(),
            "every visible text row must retain its line-number prefix; row {row_index} has none"
        );
        let expected_face = if row_index == cursor_row {
            "line-number-current-line"
        } else {
            "line-number"
        };
        let actual_faces = prefix
            .iter()
            .map(|glyph| {
                state
                    .faces
                    .get(&glyph.face_id)
                    .and_then(|face| face.lisp_name.as_deref())
            })
            .collect::<Vec<_>>();
        assert!(
            actual_faces.iter().all(|face| *face == Some(expected_face)),
            "numbered row {row_index} must use only {expected_face}, got {actual_faces:?}"
        );
    }
}

#[test]
fn phase3_delete_at_eob_does_not_relay_reused_prefix_from_buffer_start() {
    let text = ";; first scratch line\n;; second scratch line\n\n";
    let with_typed_char = format!("{text}a");
    let (mut eval, frame_id, buf_id, win) = incr_editing_frame(&with_typed_char, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        let end = buffer.point_max_emacs_byte_pos().get();
        buffer.delete_emacs_byte_range(emacs_byte_range(end - 1, end));
    }
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        engine.last_layout_stats().edit_windows,
        1,
        "expected the EOB deletion to exercise localized edit replay"
    );
    let state = engine.last_frame_display_state.as_ref().expect("state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == win.0 as i64)
        .expect("selected window");
    let rendered = enabled_window_row_texts(entry).join("");
    assert_eq!(
        rendered.matches(";; first scratch line").count(),
        1,
        "localized EOB deletion must not append a second copy of reused prefix rows: {rendered:?}"
    );
}

/// REDESIGN GOLDEN (empty-row real charpos, review round 2): the trailing
/// EOB placeholder row carries ZV (GNU MATRIX_ROW_START/END_CHARPOS with
/// ends_at_zv), so an edit that moves ZV must SHIFT it — the below-reuse fast
/// path and a full rebuild must both report the new ZV. Successor of the
/// pre-redesign edit_below_reuse_does_not_shift_trailing_placeholder_row,
/// which pinned the opposite ((0, 0)-sentinel) semantics. Trace equality
/// alone is deliberately not trusted here: both paths could agree on a wrong
/// value, so the placeholder's ZV is asserted explicitly per trace.
#[test]
fn edit_below_reuse_shifts_trailing_placeholder_to_new_zv() {
    let text = "alpha line\nbeta line\ncharlie line\ndelta line\n";
    let edit_byte: usize = 12; // inside "beta line" on line 2
    let zv_after = text.len() + 1; // ASCII; one char inserted

    // Reference: fresh engine over the post-edit buffer.
    let (mut eval_ref, frame_ref, buf_ref, _wr) = incr_editing_frame(text, 800, 600);
    {
        let buffer = eval_ref
            .buffer_manager_mut()
            .get_mut(buf_ref)
            .expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
        buffer.insert("X");
    }
    let mut ref_engine = LayoutEngine::new();
    ref_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let reference = selected_window_layout_trace(&eval_ref, &ref_engine, frame_ref);

    // Incremental: warm layout, edit, relay through below-reuse.
    let (mut eval, frame_id, buf_id, _win) = incr_editing_frame(text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.allow_below_reuse = true;
    let m = measure_incremental_relayout(&mut engine, &mut eval, frame_id, |eval| {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
        buffer.insert("X");
    });
    assert_eq!(
        m.stats.edit_windows, 1,
        "the edit must take the edit fast path (got {:?})",
        m.stats
    );
    let incremental = selected_window_layout_trace(&eval, &engine, frame_id);

    for (label, trace) in [("incremental", &incremental), ("reference", &reference)] {
        let placeholder = trace
            .matrix_rows
            .iter()
            .filter(|r| r.role == GlyphRowRole::Text && r.ends_at_zv)
            .next_back()
            .unwrap_or_else(|| panic!("{label}: no ends_at_zv row: {:#?}", trace.matrix_rows));
        assert!(
            !placeholder.displays_text,
            "{label}: the trailing placeholder displays no text"
        );
        assert_eq!(
            (placeholder.start_charpos, placeholder.end_charpos),
            (zv_after, zv_after),
            "{label}: the placeholder must shift to the post-edit ZV: {:#?}",
            trace.matrix_rows
        );
    }
    assert_eq!(
        incremental, reference,
        "\nbelow-reuse must match a full rebuild\n INC={:#?}\n REF={:#?}",
        incremental, reference
    );
}

/// REDESIGN GOLDEN (empty-row real charpos): an EMPTY buffer line mid-buffer
/// must carry its line's real buffer position on the matrix row
/// (start_charpos == end_charpos == the newline's 0-based position), not the
/// legacy (0,0) sentinel. GNU keeps MATRIX_ROW_START/END_CHARPOS real for every
/// enabled row. The second part edits above the empty line and asserts the edit
/// fast path stays byte-identical (role/start/end/pixel_y) to a full rebuild of
/// the same final state — the empty line (and the EOB placeholder below it) must
/// shift with the insert exactly as a fresh rebuild produces them.
#[test]
fn empty_line_row_carries_real_buffer_position() {
    let text = "alpha\n\ngamma\n";
    // Full rebuild: the empty line (line 2) is at 0-based charpos 6 (the second
    // newline). Its row must report start == end == 6, not the (0,0) sentinel.
    let (mut eval, frame_id, _buf_id, _win) = incr_editing_frame(text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    let trace = selected_window_layout_trace(&eval, &engine, frame_id);
    let empty = trace
        .matrix_rows
        .iter()
        .find(|r| r.role == GlyphRowRole::Text && !r.displays_text && r.start_charpos == 6)
        .unwrap_or_else(|| {
            panic!(
                "empty mid-buffer line row with real charpos 6 not found: {:#?}",
                trace.matrix_rows
            )
        });
    assert_eq!(
        (empty.start_charpos, empty.end_charpos),
        (6, 6),
        "the empty mid-buffer line must carry its real buffer position, not (0,0)"
    );

    // The incremental (edit fast path) half of this redesign lives in
    // edit_fast_path_reuses_empty_line_and_placeholder_rows below: an edit at
    // row 0 cannot exercise it (edit_replay bails when first_dirty == 0).
}

/// REDESIGN GOLDEN (empty-row real charpos, review round 2): the EDIT fast
/// path with below-reuse must reproduce a full rebuild byte-for-byte when the
/// reused region below the edit contains an EMPTY line and the EOB
/// placeholder. The edit lands on line 2 with an unchanged row ABOVE it so
/// edit_replay actually engages (first_dirty > 0; editing row 0 bails to a
/// full rebuild) and relays ONLY the edited line, below-reusing the empty
/// line, "delta", and the ZV placeholder with charpos shifted by the insert.
#[test]
fn edit_fast_path_reuses_empty_line_and_placeholder_rows() {
    let text = "alpha\nbeta\n\ndelta\n";
    let edit_byte: usize = 7; // inside "beta" on line 2

    // Reference: a fresh engine laying out the post-edit buffer.
    let (mut eval_ref, frame_ref, buf_ref, _wr) = incr_editing_frame(text, 800, 600);
    {
        let buffer = eval_ref
            .buffer_manager_mut()
            .get_mut(buf_ref)
            .expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
        buffer.insert("X");
    }
    let mut ref_engine = LayoutEngine::new();
    ref_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let reference = selected_window_layout_trace(&eval_ref, &ref_engine, frame_ref);

    // Incremental: warm layout, edit, relay. Must take the edit fast path and
    // relay only the edited line (the empty line and placeholder are reused).
    let (mut eval, frame_id, buf_id, _win) = incr_editing_frame(text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.allow_below_reuse = true;
    let m = measure_incremental_relayout(&mut engine, &mut eval, frame_id, |eval| {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
        buffer.insert("X");
    });
    assert_eq!(
        m.stats.edit_windows, 1,
        "the edit must take the edit fast path (got {:?})",
        m.stats
    );
    assert!(
        m.stats.relaid_body_rows <= 2,
        "below-reuse must relay only the edited line (got {:?})",
        m.stats
    );
    let incremental = selected_window_layout_trace(&eval, &engine, frame_id);
    assert_eq!(
        incremental, reference,
        "\nedit across an empty line + placeholder must match a full rebuild\n INC={:#?}\n REF={:#?}",
        incremental, reference
    );
}

/// REDESIGN GOLDEN (empty-row real charpos, review round 2): the
/// indicate-empty-lines viewport FILLER rows below the EOB placeholder are
/// produced outside the text walk, yet they are enabled Text rows in the
/// matrix. GNU produces the same rows in display_line with start = end = ZV
/// and ends_at_zv set, so ours must carry ZV too — a filler left at the
/// (0, 0) sentinel gets charpos-shifted by the edit fast path into
/// (delta, delta) while a full rebuild recreates it at (0, 0), committing a
/// non-canonical reusable matrix.
#[test]
fn edit_fast_path_shifts_indicate_empty_lines_fillers_to_zv() {
    let text = "alpha\nbeta\n\ndelta\n";
    let edit_byte: usize = 7; // inside "beta" on line 2
    let zv_after = text.len() + 1; // ASCII; one char inserted

    let enable_fillers = |eval: &mut Context| {
        eval.eval_str("(set-default 'indicate-empty-lines t)")
            .expect("enable indicate-empty-lines");
    };

    // Reference: fresh engine over the post-edit buffer, fillers enabled.
    let (mut eval_ref, frame_ref, buf_ref, _wr) = incr_editing_frame(text, 800, 600);
    enable_fillers(&mut eval_ref);
    {
        let buffer = eval_ref
            .buffer_manager_mut()
            .get_mut(buf_ref)
            .expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
        buffer.insert("X");
    }
    let mut ref_engine = LayoutEngine::new();
    ref_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let reference = selected_window_layout_trace(&eval_ref, &ref_engine, frame_ref);

    // Incremental: warm layout with fillers on, edit, relay via the fast path.
    let (mut eval, frame_id, buf_id, _win) = incr_editing_frame(text, 800, 600);
    enable_fillers(&mut eval);
    let mut engine = LayoutEngine::new();
    engine.allow_below_reuse = true;
    let m = measure_incremental_relayout(&mut engine, &mut eval, frame_id, |eval| {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
        buffer.insert("X");
    });
    assert_eq!(
        m.stats.edit_windows, 1,
        "the edit must take the edit fast path (got {:?})",
        m.stats
    );
    let incremental = selected_window_layout_trace(&eval, &engine, frame_id);

    // The filler producer must actually be exercised: beyond the placeholder,
    // the tall window over a 4-line buffer yields filler rows, all at ZV.
    for trace in [&incremental, &reference] {
        let zv_rows: Vec<_> = trace
            .matrix_rows
            .iter()
            .filter(|r| r.role == GlyphRowRole::Text && r.ends_at_zv && !r.displays_text)
            .collect();
        assert!(
            zv_rows.len() >= 2,
            "expected the EOB placeholder plus indicate-empty-lines fillers, got {}: {:#?}",
            zv_rows.len(),
            trace.matrix_rows
        );
        for row in zv_rows {
            assert_eq!(
                (row.start_charpos, row.end_charpos),
                (zv_after, zv_after),
                "every past-EOB row carries ZV like GNU, got ({}, {}): {:#?}",
                row.start_charpos,
                row.end_charpos,
                trace.matrix_rows
            );
        }
    }
    assert_eq!(
        incremental, reference,
        "\nedit with indicate-empty-lines fillers must match a full rebuild\n INC={:#?}\n REF={:#?}",
        incremental, reference
    );
}

/// Phase 5 (#44) — the fast paths attach `RowDamage` to each authoritative
/// matrix row: cursor-only reuses every body row (`Reused`), scroll marks its
/// reused rows `ReusedShifted{dvpos}`, and a full rebuild is all `New`.
#[test]
fn phase5_fast_paths_emit_row_damage() {
    use neomacs_display_protocol::glyph_matrix::RowDamage;

    fn selected_damage(
        engine: &LayoutEngine,
        win: neovm_core::window::WindowId,
    ) -> (Vec<RowDamage>, Vec<GlyphRowRole>) {
        let state = engine
            .last_frame_display_state
            .as_ref()
            .expect("display state");
        let entry = state
            .window_matrices
            .iter()
            .find(|e| e.window_id.get() == win.0 as i64)
            .expect("selected window matrix");
        (
            (0..entry.matrix.rows.len())
                .map(|idx| entry.matrix.row_damage(idx))
                .collect(),
            entry.matrix.rows.iter().map(|r| r.role).collect(),
        )
    }

    // --- cursor-only: all body rows Reused ---
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, win) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(10));
    }
    engine.layout_frame_rust(&mut eval, frame_id);
    assert_eq!(engine.last_layout_stats().cursor_only_windows, 1);
    let (damage, roles) = selected_damage(&engine, win);
    let mut reused_body = 0;
    for (dmg, role) in damage.iter().zip(&roles) {
        if *role == GlyphRowRole::Text {
            assert_eq!(*dmg, RowDamage::Reused, "cursor-only body row is Reused");
            reused_body += 1;
        }
    }
    assert!(reused_body > 0, "expected reused body rows");

    // --- scroll: reused rows ReusedShifted with a nonzero dvpos ---
    let line = "(defun f (a b) (+ a b))\n";
    let big = line.repeat(80);
    let (mut eval2, frame2, buf2, win2) = incr_editing_frame(&big, 800, 600);
    let mut engine2 = LayoutEngine::new();
    engine2.layout_frame_rust(&mut eval2, frame2);
    scroll_window_to(
        &mut eval2,
        frame2,
        win2,
        buf2,
        5 * line.len() as i64 + 1,
        7 * line.len(),
    );
    engine2.layout_frame_rust(&mut eval2, frame2);
    assert_eq!(engine2.last_layout_stats().scroll_windows, 1);
    let (damage2, _roles2) = selected_damage(&engine2, win2);
    assert!(
        damage2
            .iter()
            .any(|d| matches!(d, RowDamage::ReusedShifted { dvpos } if dvpos.get() != 0.0)),
        "scroll emits ReusedShifted rows with a nonzero dvpos"
    );
}

/// `(matrix row index, damage)` for every enabled buffer-text row of the
/// selected window, top to bottom.
fn enabled_body_row_damage(
    engine: &LayoutEngine,
    win: neovm_core::window::WindowId,
) -> Vec<(usize, neomacs_display_protocol::glyph_matrix::RowDamage)> {
    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|e| e.window_id.get() == win.0 as i64)
        .expect("selected window matrix");
    entry
        .matrix
        .rows
        .iter()
        .enumerate()
        .filter(|(_, row)| row.enabled && row.role == GlyphRowRole::Text)
        .map(|(idx, _)| (idx, entry.matrix.row_damage(idx)))
        .collect()
}

/// Row provenance names rows BY INDEX. A below-reuse edit relays a row in the
/// MIDDLE of the reused set (rows above verbatim, rows below shifted), and on
/// the window's first row it relays the very first one. Attributing "the
/// first N body rows" as reused marked the edited row itself `Reused`; the
/// terminal backend carries a `Reused` row from its previous screen without a
/// cell compare, so the screen kept the pre-edit text.
#[test]
fn phase5_below_reuse_edit_marks_only_the_edited_row_relaid() {
    use neomacs_display_protocol::glyph_matrix::RowDamage;

    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    for edit_line in [0usize, 10] {
        let (mut eval, frame_id, buf_id, win) = incr_editing_frame(&text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);
        {
            let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
            buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_line * 24 + 5));
            buffer.insert("x");
        }
        engine.layout_frame_rust(&mut eval, frame_id);
        let stats = engine.last_layout_stats().clone();
        assert_eq!(
            stats.edit_windows, 1,
            "line {edit_line}: took the edit fast path (got {stats:?})"
        );
        let body = enabled_body_row_damage(&engine, win);
        let (edited_idx, edited_damage) = body[edit_line];
        assert_eq!(
            edited_damage,
            RowDamage::New,
            "line {edit_line}: the edited row (matrix row {edited_idx}) was relaid"
        );
        let relaid: Vec<usize> = body
            .iter()
            .filter(|(_, damage)| damage.is_relaid())
            .map(|(idx, _)| *idx)
            .collect();
        assert_eq!(
            relaid,
            vec![edited_idx],
            "line {edit_line}: every other body row is marked Reused"
        );
        assert_eq!(
            stats.reused_rows,
            body.len() - 1,
            "line {edit_line}: the stats count the same reused rows"
        );
    }
}

/// A forward scroll keeps the overlapping rows at the TOP (shifted up) and
/// walks exactly the rows exposed at the bottom: `ReusedShifted` lands on
/// the kept rows and `New` on the exposed ones, row for row.
#[test]
fn phase5_forward_scroll_marks_kept_rows_shifted_and_exposed_rows_new() {
    use neomacs_display_protocol::glyph_matrix::RowDamage;

    let line = "(defun f (a b) (+ a b))\n";
    let big = line.repeat(80);
    let (mut eval, frame_id, buf_id, win) = incr_editing_frame(&big, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    let scrolled_rows = 5usize;
    scroll_window_to(
        &mut eval,
        frame_id,
        win,
        buf_id,
        scrolled_rows as i64 * line.len() as i64 + 1,
        7 * line.len(),
    );
    engine.layout_frame_rust(&mut eval, frame_id);
    let stats = engine.last_layout_stats().clone();
    assert_eq!(
        stats.scroll_windows, 1,
        "took the scroll fast path (got {stats:?})"
    );
    let body = enabled_body_row_damage(&engine, win);
    let (kept, exposed) = body.split_at(body.len() - scrolled_rows);
    assert!(
        kept.iter().all(|(_, damage)| matches!(
            damage,
            RowDamage::ReusedShifted { dvpos } if dvpos.get() < 0.0
        )),
        "the overlapping rows moved up verbatim: {kept:?}"
    );
    assert!(
        exposed.iter().all(|(_, damage)| damage.is_relaid()),
        "the rows exposed at the bottom were walked: {exposed:?}"
    );
    assert_eq!(stats.reused_shifted_rows, kept.len());
}

/// Phase 3 below-reuse (full GNU try_window_id) — a single-line edit that does
/// not change the row structure relays ONLY the edited line: the rows above are
/// reused verbatim AND the rows below are reused with a charpos shift (same
/// pixel_y). So relaid_body_rows is ~1, not "edited line + everything below".
///
/// (Enabled via the engine's `allow_below_reuse` opt-in; production default is
/// off until the render-side post-walk validation lands.)
#[test]
fn phase3_below_reuse_relays_only_edited_line() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _win) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.allow_below_reuse = true;
    let m = measure_incremental_relayout(&mut engine, &mut eval, frame_id, |eval| {
        // Plain single-char insert mid-line on line 10 (no newline, no wrap).
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(10 * 24 + 5));
        buffer.insert("x");
    });
    assert_eq!(
        m.stats.edit_windows, 1,
        "took the edit fast path (got {:?})",
        m.stats
    );
    assert!(
        m.stats.relaid_body_rows <= 2,
        "below-reuse relays only the edited line, not the rows below it (got {:?})",
        m.stats
    );
}

/// Phase 3 below-reuse GOLDEN — relaying only the edited line + reusing the rows
/// below (charpos-shifted) must be BYTE-IDENTICAL to a full rebuild of the same
/// edited state.
#[test]
fn phase3_below_reuse_matches_full_rebuild_golden() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let edit_at = 10 * 24 + 5;

    let (mut eval_ref, frame_ref, buf_ref, _wr) = incr_editing_frame(&text, 800, 600);
    {
        let buffer = eval_ref
            .buffer_manager_mut()
            .get_mut(buf_ref)
            .expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buffer.insert("x");
    }
    let mut ref_engine = LayoutEngine::new();
    ref_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let reference = selected_window_layout_trace(&eval_ref, &ref_engine, frame_ref);

    let (mut eval, frame_id, buf_id, _wi) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.allow_below_reuse = true;
    engine.layout_frame_rust(&mut eval, frame_id);
    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buffer.insert("x");
    }
    engine.layout_frame_rust(&mut eval, frame_id);
    assert_eq!(
        engine.last_layout_stats().edit_windows,
        1,
        "took the edit fast path"
    );
    let incremental = selected_window_layout_trace(&eval, &engine, frame_id);

    assert_eq!(
        incremental, reference,
        "below-reuse output must be byte-identical to a full rebuild"
    );
}

/// Drive a warm→edit→measured pass with below-reuse ENABLED (the default),
/// assert the output is byte-identical to a full rebuild of the edited state,
/// and return the measured stats. Used by the below-reuse safety-bail tests.
fn below_reuse_bail_golden_stats(insert_text: &str) -> LayoutStats {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let edit_at = 10 * 24 + 5;

    let (mut eval_ref, frame_ref, buf_ref, _wr) = incr_editing_frame(&text, 800, 600);
    {
        let buffer = eval_ref
            .buffer_manager_mut()
            .get_mut(buf_ref)
            .expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buffer.insert(insert_text);
    }
    let mut ref_engine = LayoutEngine::new();
    ref_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let reference = selected_window_layout_trace(&eval_ref, &ref_engine, frame_ref);

    let (mut eval, frame_id, buf_id, _wi) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new(); // allow_below_reuse defaults to true
    engine.layout_frame_rust(&mut eval, frame_id);
    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buffer.insert(insert_text);
    }
    engine.layout_frame_rust(&mut eval, frame_id);
    let incremental = selected_window_layout_trace(&eval, &engine, frame_id);
    assert_eq!(
        incremental, reference,
        "edit must be byte-identical to a full rebuild (below-reuse must bail safely)"
    );
    engine.last_layout_stats().clone()
}

/// A newline insert changes the line count, so below-reuse (which keeps the rows
/// below at the same pixel_y) MUST bail to above-only — caught by the ASCII gate.
#[test]
fn phase3_below_reuse_bails_on_newline_insert() {
    let stats = below_reuse_bail_golden_stats("\n");
    assert_eq!(
        stats.edit_windows, 1,
        "still the edit fast path (got {stats:?})"
    );
    assert!(
        stats.relaid_body_rows > 2,
        "above-only (not below-reuse, which would relay ~1) — got {stats:?}"
    );
}

/// A long ASCII insert that wraps the edited line changes the row structure, so
/// below-reuse MUST bail to above-only — caught by the width gate.
#[test]
fn phase3_below_reuse_bails_on_wrapping_insert() {
    let stats = below_reuse_bail_golden_stats(&"x".repeat(100));
    assert_eq!(
        stats.edit_windows, 1,
        "still the edit fast path (got {stats:?})"
    );
    assert!(
        stats.relaid_body_rows > 2,
        "above-only (not below-reuse) — got {stats:?}"
    );
}

/// A window whose layout inputs did not change AT ALL (point included) must
/// reuse its retained body verbatim — 0 relaid body rows — instead of
/// full-rebuilding. This is the multi-window win: editing one window leaves the
/// others untouched, so they should cost nothing. (No-change cursor-only.)
#[test]
fn no_change_relayout_reuses_verbatim() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, _buf, _win) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    let m = measure_incremental_relayout(&mut engine, &mut eval, frame_id, |_eval| {
        // Nothing changes between the warm and measured passes.
    });
    assert_eq!(
        m.stats.cursor_only_windows, 1,
        "the unchanged main window reuses verbatim via the cursor-only path (got {:?})",
        m.stats
    );
    assert!(
        m.stats.reused_rows >= 30,
        "the main window's body is reused, not relaid (got {:?})",
        m.stats
    );
    // The only body rows relaid are the 1-row minibuffer (excluded from
    // retention as a probe-pass hazard); the 36-row main window relays nothing.
    assert!(
        m.stats.relaid_body_rows <= 1,
        "the unchanged main window's 36 body rows are no longer relaid (got {:?})",
        m.stats
    );
}

/// No-change cursor-only must be BYTE-IDENTICAL to a full rebuild of the same
/// (unchanged) state.
#[test]
fn no_change_relayout_matches_full_rebuild_golden() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval_ref, frame_ref, _br, _wr) = incr_editing_frame(&text, 800, 600);
    let mut ref_engine = LayoutEngine::new();
    ref_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let reference = selected_window_layout_trace(&eval_ref, &ref_engine, frame_ref);

    let (mut eval, frame_id, _bi, _wi) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id); // warm
    engine.layout_frame_rust(&mut eval, frame_id); // measured: nothing changed
    assert_eq!(
        engine.last_layout_stats().cursor_only_windows,
        1,
        "unchanged window took the no-change cursor-only path"
    );
    let incremental = selected_window_layout_trace(&eval, &engine, frame_id);
    assert_eq!(
        incremental, reference,
        "no-change must be byte-identical to a full rebuild"
    );
}

/// Multi-window cross-window correctness (adversarial-review dimension D6): in a
/// split frame on two DIFFERENT buffers, editing one buffer must leave BOTH
/// windows' output byte-identical to a full rebuild — the edited window via its
/// fast path, the other via full rebuild, with no cross-window corruption.
#[test]
fn multi_window_edit_matches_full_rebuild_for_both_windows() {
    fn setup() -> (
        Context,
        neovm_core::window::FrameId,
        BufferId,
        neovm_core::window::WindowId,
        neovm_core::window::WindowId,
    ) {
        let mut eval = Context::new();
        let left_buf = eval
            .buffer_manager()
            .current_buffer()
            .expect("current buffer")
            .id();
        {
            let buf = eval.buffer_manager_mut().get_mut(left_buf).expect("left");
            buf.insert(&"(left line xx)\n".repeat(40));
        }
        let right_buf = eval.buffer_manager_mut().create_buffer("*right-incr*");
        {
            let buf = eval.buffer_manager_mut().get_mut(right_buf).expect("right");
            buf.insert(&"(right line yy)\n".repeat(40));
        }
        let frame_id = eval
            .frame_manager_mut()
            .create_frame("multi-golden", 800, 600, left_buf);
        let left_window = eval
            .frame_manager()
            .get(frame_id)
            .expect("frame")
            .selected_window;
        let right_window = eval
            .frame_manager_mut()
            .split_window(
                frame_id,
                left_window,
                neovm_core::window::SplitDirection::Horizontal,
                right_buf,
                None,
                neovm_core::window::SplitPlacement::AfterTarget,
            )
            .expect("split");
        (eval, frame_id, left_buf, left_window, right_window)
    }
    let edit_at = 5 * 15 + 4;

    // Reference: full rebuild of the edited state.
    let (mut eval_ref, frame_ref, left_ref, lw_ref, rw_ref) = setup();
    {
        let buf = eval_ref
            .buffer_manager_mut()
            .get_mut(left_ref)
            .expect("left");
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buf.insert("x");
    }
    let mut ref_engine = LayoutEngine::new();
    ref_engine.layout_frame_rust(&mut eval_ref, frame_ref);
    let ref_left = window_layout_trace(&eval_ref, &ref_engine, frame_ref, lw_ref);
    let ref_right = window_layout_trace(&eval_ref, &ref_engine, frame_ref, rw_ref);

    // Incremental: warm, edit the left buffer, measured.
    let (mut eval, frame_id, left_buf, lw, rw) = setup();
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    {
        let buf = eval.buffer_manager_mut().get_mut(left_buf).expect("left");
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        buf.insert("x");
    }
    engine.layout_frame_rust(&mut eval, frame_id);
    let inc_left = window_layout_trace(&eval, &engine, frame_id, lw);
    let inc_right = window_layout_trace(&eval, &engine, frame_id, rw);

    assert_eq!(
        inc_left, ref_left,
        "edited window must be byte-identical to a full rebuild"
    );
    assert_eq!(
        inc_right, ref_right,
        "the OTHER window must be byte-identical (no cross-window corruption)"
    );
}

/// DIAGNOSTIC: the goldens compare matrix face_ids but not the frame faces table.
/// Verify that the cursor-only fast path's reused body glyphs reference face_ids
/// that ARE registered in the (per-frame-cleared) frame faces table — otherwise
/// the renderer cannot resolve them (a latent dangling-face bug the goldens miss).
#[test]
fn cursor_only_reused_body_face_ids_are_registered_in_frame_faces() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, _buf, win) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id); // warm (registers faces)
    engine.layout_frame_rust(&mut eval, frame_id); // no-change cursor-only
    assert_eq!(
        engine.last_layout_stats().cursor_only_windows,
        1,
        "expected cursor-only"
    );
    let state = engine.last_frame_display_state.as_ref().expect("state");
    let faces = &state.faces;
    let entry = state
        .window_matrices
        .iter()
        .find(|e| e.window_id.get() == win.0 as i64)
        .expect("window");
    let mut missing: Vec<FaceId> = Vec::new();
    for row in entry.matrix.rows.iter().filter(|r| r.enabled) {
        for area in row.glyphs.iter() {
            for g in area.iter() {
                if !faces.contains_key(&g.face_id) {
                    missing.push(g.face_id);
                }
            }
        }
    }
    missing.sort_unstable();
    missing.dedup();
    assert!(
        missing.is_empty(),
        "cursor-only reused body uses face_ids NOT in the frame faces table: {missing:?} \
         (faces table has ids {:?})",
        {
            let mut ks: Vec<FaceId> = faces.keys().copied().collect();
            ks.sort_unstable();
            ks
        }
    );
}

