/// REGRESSION (face-id collision audit, 2026-06-27): the incremental fast paths
/// install retained body rows VERBATIM carrying prior-frame face_ids, but the
/// frame faces table is rebuilt from scratch each frame. For a MULTI-FACE
/// (font-locked/propertized) body those face_ids are never re-registered, so at
/// render `resolved_face` misses and falls back to white-fg. The byte-identical
/// goldens miss it (they compare integer face_ids, not the resolved face). This
/// asserts every reused body glyph's face_id is present in the frame faces table.
#[test]
fn cursor_only_reused_multiface_body_face_ids_are_registered_in_frame_faces() {
    let text = "(defun f (a b) (+ a b))\n".repeat(20);
    let (mut eval, frame_id, buf_id, win) = incr_editing_frame(&text, 800, 600);
    // Distinct :face per several lines BEFORE the warm pass, so the props tick is
    // stable and a later bare point move takes the cursor-only fast path.
    for (i, color) in ["red", "green", "blue", "magenta", "cyan"]
        .iter()
        .enumerate()
    {
        let start = i * 24 + 3;
        let end = start + 8;
        eval.eval_str(&format!(
            "(put-text-property {start} {end} 'face '(:foreground \"{color}\"))"
        ))
        .expect("put-text-property");
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id); // warm (allocates multi-face ids)
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buf");
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(60));
    }
    engine.layout_frame_rust(&mut eval, frame_id); // measured -> cursor-only
    assert_eq!(
        engine.last_layout_stats().cursor_only_windows,
        1,
        "expected the cursor-only fast path to fire"
    );
    let state = engine.last_frame_display_state.as_ref().expect("state");
    let faces = &state.faces;
    let entry = state
        .window_matrices
        .iter()
        .find(|e| e.window_id.get() == win.0 as i64)
        .expect("window");
    let mut missing: std::collections::BTreeSet<FaceId> = std::collections::BTreeSet::new();
    let mut total = 0usize;
    for row in entry
        .matrix
        .rows
        .iter()
        .filter(|r| r.enabled && r.role == GlyphRowRole::Text)
    {
        for g in row.glyphs[1].iter() {
            total += 1;
            if !faces.contains_key(&g.face_id) {
                missing.insert(g.face_id);
            }
        }
    }
    let mut keys: Vec<FaceId> = faces.keys().copied().collect();
    keys.sort_unstable();
    assert!(
        missing.is_empty(),
        "cursor-only reused MULTI-FACE body references face_ids absent from the frame \
         faces table: missing={missing:?}, faces_keys={keys:?}, total_body_glyphs={total}"
    );
}

/// REGRESSION (tab-line jitter, 2026-07-25): replay plans are gathered for all
/// windows before any window is rendered, but their retained face ids used to be
/// reserved one window at a time during rendering.  The left window could then
/// allocate a fresh chrome face id which the right window subsequently imported
/// as one of its retained body faces, overwriting the face behind the already
/// emitted left tab-line glyph.  The matrix still contained a valid integer id,
/// so checking only for missing face ids could not detect this corruption.
#[test]
fn cursor_only_two_windows_keep_fresh_tab_line_face_out_of_later_retained_body_namespace() {
    let mut eval = Context::new();
    let left = eval.buffer_manager().current_buffer().expect("buf").id();
    let right = eval
        .buffer_manager_mut()
        .create_buffer("*right-face-replay*");

    {
        let left_buffer = eval.buffer_manager_mut().get_mut(left).expect("left");
        left_buffer.insert(&"left body\n".repeat(30));
        left_buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(0));
        left_buffer.set_buffer_local(
            "tab-line-format",
            Value::string_with_text_properties(
                "\u{e632}",
                vec![StringTextPropertyRun {
                    start: 0,
                    end: 1,
                    plist: Value::list(vec![
                        Value::symbol("face"),
                        Value::list(vec![
                            Value::keyword("family"),
                            Value::string("Symbols Nerd Font Mono"),
                            Value::keyword("foreground"),
                            Value::string("#672d58"),
                        ]),
                    ]),
                }],
            ),
        );
    }
    {
        let right_buffer = eval.buffer_manager_mut().get_mut(right).expect("right");
        right_buffer.insert(&"right body\n".repeat(30));
        right_buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(0));
        right_buffer.set_buffer_local("tab-line-format", Value::string("RIGHT"));
        assert!(right_buffer.put_text_property(
            1,
            6,
            Value::symbol("face"),
            Value::list(vec![Value::keyword("foreground"), Value::string("#46ade7"),]),
        ));
    }

    let frame =
        eval.frame_manager_mut()
            .create_frame("two-window-tab-line-face-replay", 800, 600, left);
    realize_test_gui_frame(&mut eval, frame);
    let left_window = eval
        .frame_manager()
        .get(frame)
        .expect("frame")
        .selected_window;
    eval.frame_manager_mut()
        .split_window(
            frame,
            left_window,
            neovm_core::window::SplitDirection::Horizontal,
            right,
            None,
            neovm_core::window::SplitPlacement::AfterTarget,
        )
        .expect("split");

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame); // warm retained rows + faces
    let expected_icon_face = {
        let state = engine
            .last_frame_display_state
            .as_ref()
            .expect("warm display state");
        let left_entry = state
            .window_matrices
            .iter()
            .find(|entry| entry.window_id.get() == left_window.0 as i64)
            .expect("warm left window matrix");
        let left_tab_line = left_entry
            .matrix
            .rows
            .iter()
            .find(|row| row.enabled && row.role == GlyphRowRole::TabLine)
            .expect("warm left tab-line");
        let icon = left_tab_line.glyphs[GlyphArea::Text.index()]
            .iter()
            .find(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: '\u{e632}' }))
            .expect("warm left tab-line icon");
        state
            .faces
            .get(&icon.face_id)
            .expect("warm tab-line icon face must resolve")
            .clone()
    };

    engine.layout_frame_rust(&mut eval, frame); // both windows cursor-only
    assert_eq!(
        engine.last_layout_stats().cursor_only_windows,
        2,
        "the regression requires both windows to import retained faces"
    );

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let left_entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == left_window.0 as i64)
        .expect("left window matrix");
    let left_tab_line = left_entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::TabLine)
        .expect("left tab-line");
    let icon = left_tab_line.glyphs[GlyphArea::Text.index()]
        .iter()
        .find(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: '\u{e632}' }))
        .expect("left tab-line icon");
    let resolved_icon_face = state
        .faces
        .get(&icon.face_id)
        .expect("tab-line icon face must resolve");

    let mut expected_icon_face = expected_icon_face;
    expected_icon_face.id = resolved_icon_face.id;
    assert_eq!(
        resolved_icon_face, &expected_icon_face,
        "a later window's retained body face overwrote the fresh left tab-line face \
         id {}; resolved face={resolved_icon_face:?}",
        icon.face_id,
    );
}

/// The face-id collision fix re-registers a reused window's faces, which UNBLOCKS
/// reuse of a fully-unchanged NON-selected window: a redisplay where nothing
/// changed must reuse BOTH windows via cursor-only (no-change), not just the
/// selected one. Without non-selected reuse this would be 1 (the perf win is the
/// non-selected windows no longer full-rebuilding every frame).
#[test]
fn non_selected_unchanged_window_reuses_via_cursor_only() {
    let mut eval = Context::new();
    let left = eval.buffer_manager().current_buffer().expect("buf").id();
    eval.buffer_manager_mut()
        .get_mut(left)
        .expect("left")
        .insert(&"(left line)\n".repeat(30));
    let right = eval.buffer_manager_mut().create_buffer("*r-reuse*");
    eval.buffer_manager_mut()
        .get_mut(right)
        .expect("right")
        .insert(&"(right line)\n".repeat(30));
    // `insert` leaves point at buffer end (off-screen → cursor-only bails on the
    // missing cursor row); reset both to the top so each window's point sits in
    // its visible body and both windows are cursor-only eligible.
    for b in [left, right] {
        eval.buffer_manager_mut()
            .get_mut(b)
            .expect("buf")
            .goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(0));
    }
    let frame = eval
        .frame_manager_mut()
        .create_frame("mw-reuse", 800, 600, left);
    let lw = eval
        .frame_manager()
        .get(frame)
        .expect("frame")
        .selected_window;
    eval.frame_manager_mut()
        .split_window(
            frame,
            lw,
            neovm_core::window::SplitDirection::Horizontal,
            right,
            None,
            neovm_core::window::SplitPlacement::AfterTarget,
        )
        .expect("split");
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame); // warm
    engine.layout_frame_rust(&mut eval, frame); // nothing changed
    assert_eq!(
        engine.last_layout_stats().cursor_only_windows,
        2,
        "both the selected and the non-selected unchanged window must reuse via cursor-only"
    );
}

/// REVIEW GOLDEN (Codex P2): editing the LAST non-empty line of a
/// newline-terminated buffer under below-reuse bounds the walk to that one
/// row; consuming the final newline reaches ZV, but the row limit suppresses
/// beginning the placeholder, so the walk must NOT tag the finalized content
/// row ends_at_zv — the reused placeholder below it already carries the flag,
/// and a full rebuild tags only the placeholder.
#[test]
fn edit_below_reuse_last_line_leaves_zv_flag_to_the_placeholder() {
    let text = "alpha\ndelta\n";
    let edit_byte: usize = 8; // inside "delta", the LAST non-empty line

    let run = |incremental: bool| -> Vec<(usize, usize, bool, bool)> {
        let (mut eval, frame_id, buf_id, _w) = incr_editing_frame(text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.allow_below_reuse = true;
        if incremental {
            engine.layout_frame_rust(&mut eval, frame_id);
        }
        {
            let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
            buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
            buffer.insert("X");
        }
        engine.layout_frame_rust(&mut eval, frame_id);
        if incremental {
            assert_eq!(
                engine.last_layout_stats().edit_windows,
                1,
                "the edit must take the edit fast path (got {:?})",
                engine.last_layout_stats()
            );
        }
        selected_window_layout_trace(&eval, &engine, frame_id)
            .matrix_rows
            .iter()
            .filter(|r| r.role == GlyphRowRole::Text)
            .map(|r| {
                (
                    r.start_charpos,
                    r.end_charpos,
                    r.displays_text,
                    r.ends_at_zv,
                )
            })
            .collect()
    };
    let incremental = run(true);
    let reference = run(false);
    assert_eq!(
        incremental, reference,
        "only the placeholder reports ends_at_zv, on both paths"
    );
}

/// Per-row buffer-pointer identities (mouse-face source ranges etc.) of the
/// selected window's enabled body rows, keyed by row start charpos.
fn selected_pointer_identities(
    engine: &LayoutEngine,
    win: neovm_core::window::WindowId,
) -> Vec<(
    usize,
    Vec<neomacs_display_protocol::glyph_matrix::GlyphPointerSourceIdentity>,
)> {
    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|e| e.window_id.get() == win.0 as i64)
        .expect("selected window matrix");
    entry
        .matrix
        .rows
        .iter()
        .filter(|r| r.enabled && r.role == GlyphRowRole::Text)
        .map(|r| {
            (
                r.start_charpos,
                r.pointer_appearances()
                    .iter()
                    .map(|appearance| appearance.source)
                    .collect(),
            )
        })
        .collect()
}

/// REVIEW GOLDEN (Codex P2): a mouse-face source range on the rows BELOW the
/// edit carries buffer positions in its pointer identity; below-reuse must
/// shift them with the insert or hover would key the reused rows differently
/// from a fresh walk.
#[test]
fn edit_below_reuse_shifts_pointer_identities_below_the_insert() {
    let text = "alpha\nbeta\ngamma\ndelta\n";
    let edit_byte: usize = 8; // inside "beta"
    // mouse-face over gamma+delta (1-based 12..23), entirely below the edit.
    let put_prop = "(put-text-property 12 23 'mouse-face 'highlight)";

    let run = |incremental: bool| {
        let (mut eval, frame_id, buf_id, win) = incr_editing_frame(text, 800, 600);
        eval.eval_str(put_prop).expect("put-text-property");
        let mut engine = LayoutEngine::new();
        engine.allow_below_reuse = true;
        if incremental {
            engine.layout_frame_rust(&mut eval, frame_id);
        }
        {
            let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
            buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
            buffer.insert("X");
        }
        engine.layout_frame_rust(&mut eval, frame_id);
        let stats = engine.last_layout_stats().clone();
        (selected_pointer_identities(&engine, win), stats)
    };
    let (incremental, stats) = run(true);
    let (reference, _) = run(false);
    assert_eq!(stats.edit_windows, 1, "edit fast path engaged ({stats:?})");
    assert!(
        stats.relaid_body_rows <= 2,
        "below-reuse relays only the edited line ({stats:?})"
    );
    assert!(
        incremental
            .iter()
            .any(|(_, identities)| !identities.is_empty()),
        "the walk must record pointer identities for the mouse-face range: {incremental:?}"
    );
    assert_eq!(
        incremental, reference,
        "reused rows report the identities a fresh walk produces"
    );
}

/// REVIEW GOLDEN (Codex P2): a pointer range that BEGINS above the edit can be
/// restructured by the insert itself (interval split around non-inheriting
/// text), which no shift reproduces — below-reuse must fall back to the
/// above-only path (which relays the rows below) and stay canonical.
#[test]
fn edit_below_reuse_bails_on_pointer_range_crossing_the_edit() {
    let text = "alpha\nbeta\ngamma\ndelta\n";
    let edit_byte: usize = 8; // inside "beta"
    // mouse-face from inside "alpha" through "delta" (1-based 3..23) — its
    // identity on the rows below begins ABOVE the edit point.
    let put_prop = "(put-text-property 3 23 'mouse-face 'highlight)";

    let run = |incremental: bool| {
        let (mut eval, frame_id, buf_id, win) = incr_editing_frame(text, 800, 600);
        eval.eval_str(put_prop).expect("put-text-property");
        let mut engine = LayoutEngine::new();
        engine.allow_below_reuse = true;
        if incremental {
            engine.layout_frame_rust(&mut eval, frame_id);
        }
        {
            let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
            buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_byte));
            buffer.insert("X");
        }
        engine.layout_frame_rust(&mut eval, frame_id);
        let stats = engine.last_layout_stats().clone();
        (selected_pointer_identities(&engine, win), stats)
    };
    let (incremental, stats) = run(true);
    let (reference, _) = run(false);
    // The range reaches the edit point from the very first row, so no reuse
    // prefix is provably stable and the replay degrades to a full rebuild —
    // canonical, at the price of the fast path for this (uncommon) shape.
    assert_eq!(
        stats.edit_windows, 0,
        "no stable prefix -> no edit replay ({stats:?})"
    );
    assert!(
        incremental
            .iter()
            .any(|(_, identities)| !identities.is_empty()),
        "the walk must record pointer identities for the mouse-face range: {incremental:?}"
    );
    assert_eq!(
        incremental, reference,
        "crossing ranges must not survive reuse with stale identities"
    );
}

/// GUI overlay arrow: on a window-system frame with a left fringe, GNU draws
/// the arrow as a left-fringe bitmap (the default `overlay-arrow` →
/// `right-triangle`), NOT by overwriting the text — the opposite of the TTY
/// string branch. The marked row must carry that bitmap on its left fringe
/// while its text glyphs stay intact.
#[test]
fn gui_overlay_arrow_draws_left_fringe_bitmap_not_text() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let right_triangle_index: u16 = eval
        .eval_str("(get 'right-triangle 'fringe)")
        .expect("right-triangle fringe prop")
        .as_fixnum()
        .expect("fringe index") as u16;
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("alpha\nbeta\ngamma\n");
        buf.goto_emacs_byte_pos(EmacsBytePos::new(0));
    }
    // Mark the start of line 2 ("beta", 1-based char 7).
    eval.eval_str("(setq overlay-arrow-position (copy-marker 7))")
        .expect("set overlay-arrow-position");

    let frame_id = eval
        .frame_manager_mut()
        .create_frame("gui-arrow", 400, 200, buf_id);
    if let Some(frame) = eval.frame_manager_mut().get_mut(frame_id) {
        frame.set_window_system(Some(Value::symbol("neo")));
    }
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("window matrix entry");

    // The "beta" row (start charpos 6, 0-based) carries the arrow bitmap.
    let beta = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.start_charpos == 6)
        .unwrap_or_else(|| panic!("no beta row: {:#?}", entry.matrix.rows));
    assert_eq!(
        beta.overlay_arrow_bitmap.map(|i| i.bitmap_index),
        Some(right_triangle_index),
        "the marked row must carry the overlay-arrow (right-triangle) bitmap"
    );
    // GNU keeps the arrow in `overlay_arrow_bitmap`, a slot of its own, so the
    // row's own left-fringe slot stays free for an explicit (left-fringe …)
    // spec or an indicator. `fringe-bitmaps-at-pos` reports the two apart.
    assert_eq!(
        beta.left_fringe_bitmap, None,
        "the overlay arrow must not occupy the row's own left-fringe slot"
    );
    // The text is untouched — the GUI branch does not overwrite it.
    let text: String = beta.glyphs[GlyphArea::Text.index()]
        .iter()
        .filter_map(|g| match g.glyph_type {
            GlyphType::Char { ch } => Some(ch),
            _ => None,
        })
        .collect();
    assert!(
        text.starts_with("beta"),
        "GUI overlay arrow must not overwrite the text; got {text:?}"
    );
}

/// GNU copies the TTY overlay-arrow string into the row before
/// `set_cursor_from_row`. The copied cells belong to the arrow string, not to
/// the buffer positions they overwrite, so point at the first covered buffer
/// character resolves to the first surviving buffer glyph after the arrow.
#[test]
fn tty_overlay_arrow_moves_cursor_past_covered_buffer_glyphs() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("alpha\nbeta\ngamma\n");
    }
    eval.eval_str("(progn (goto-char 7) (setq overlay-arrow-position (copy-marker 7)))")
        .expect("set overlay-arrow-position");

    let frame_id = eval
        .frame_manager_mut()
        .create_frame("tty-arrow", 400, 200, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("window matrix entry");
    let beta = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::Text && row.start_charpos == 6)
        .unwrap_or_else(|| panic!("no beta row: {:#?}", entry.matrix.rows));
    let text: String = beta.glyphs[GlyphArea::Text.index()]
        .iter()
        .filter_map(|glyph| match glyph.glyph_type {
            GlyphType::Char { ch } => Some(ch),
            _ => None,
        })
        .collect();
    assert!(text.starts_with("=>ta"), "TTY arrow text: {text:?}");

    let cursor = state.phys_cursor.as_ref().expect("active cursor");
    assert_eq!(cursor.window_id.get(), selected_window.0 as i64);
    assert_eq!(cursor.row, 1);
    assert_eq!(cursor.col, 2, "cursor must follow the two covered glyphs");
}

/// An empty buffer line has no leading buffer glyphs for GNU's TTY overlay
/// arrow to replace.  The arrow string is therefore appended as two synthetic
/// display cells, and `set_cursor_from_row` places point after those cells.
/// Their provenance must remain redisplay-owned: spelling the old
/// `NO_BUFFER_POSITION_CHARPOS` sentinel as a buffer position makes the cursor
/// resolver mistake the first arrow cell for a visible buffer glyph after
/// point and snap the cursor back to column zero.
#[test]
fn tty_overlay_arrow_moves_empty_line_cursor_past_appended_arrow_cells() {
    let mut eval = Context::new();
    let buf_id = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("alpha\n\ngamma\n");
    }
    eval.eval_str("(progn (goto-char 7) (setq overlay-arrow-position (copy-marker 7)))")
        .expect("set overlay-arrow-position");

    let frame_id = eval
        .frame_manager_mut()
        .create_frame("tty-empty-arrow", 400, 200, buf_id);
    let selected_window = eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .selected_window;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected_window.0 as i64)
        .expect("window matrix entry");
    let empty = entry
        .matrix
        .rows
        .iter()
        .find(|row| {
            row.enabled
                && row.role == GlyphRowRole::Text
                && row.start_charpos == 6
                && row.end_charpos == 6
        })
        .unwrap_or_else(|| panic!("no empty row: {:#?}", entry.matrix.rows));
    let arrow_cells: Vec<_> = empty.glyphs[GlyphArea::Text.index()]
        .iter()
        .filter(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: '=' | '>' }))
        .collect();
    assert_eq!(
        arrow_cells.len(),
        2,
        "empty row must display the full arrow"
    );
    assert!(
        arrow_cells
            .iter()
            .all(|glyph| glyph.provenance == GlyphProvenance::mark()),
        "appended arrow cells must carry redisplay provenance"
    );

    let cursor = state.phys_cursor.as_ref().expect("active cursor");
    assert_eq!(cursor.window_id.get(), selected_window.0 as i64);
    assert_eq!(cursor.row, 1);
    assert_eq!(cursor.col, 2, "cursor must follow the appended arrow cells");
    assert_eq!(
        cursor.x,
        state.char_width * 2.0,
        "TTY publication derives its terminal column from cursor x, which must follow the arrow"
    );
}

// ---------------------------------------------------------------------------
// P4.3g: glyph-level shadows for TRUNCATED rows.
//
// The P4.2 stream harness proves what the PRODUCER emits. It is blind to row
// ASSEMBLY — fit decisions, overlay emission points, width accounting, cursor
// capture — because those happen after the element leaves the producer. Rungs
// that change what the RENDERER RECEIVES (P4.3's fit split, P4.5's per-char
// feeder, P4.6's overlay strings, P4.7's replacements) therefore need
// finished-GlyphRow proofs, and this is that net.
//
// Each case lays out a real frame with truncate-lines and pins the finished
// truncated row: how many cells it holds, that it ends in the shared '$'
// marker, that its visible text is exactly the fitting prefix, and that its
// glyph charpos stamps advance monotonically from the line start. Those four
// together move if any assembly decision at the fit boundary moves.
// ---------------------------------------------------------------------------

/// Lay out `text` with truncate-lines and return the first body row's glyphs.
fn truncated_first_row_glyphs(
    text: &str,
    setup: impl FnOnce(&mut Context, BufferId),
) -> Vec<neomacs_display_protocol::glyph_matrix::Glyph> {
    let (mut eval, _buf_id, _frame_id, rows, _cw, _ch) =
        layout_main_text_rows_with(text, |eval, buf_id| {
            eval.buffer_manager_mut().set_current(buf_id);
            eval.eval_str("(setq truncate-lines t)").expect("truncate");
            setup(eval, buf_id);
        });
    let _ = &mut eval;
    rows[0].glyphs[1].clone()
}

fn row_text(glyphs: &[neomacs_display_protocol::glyph_matrix::Glyph]) -> String {
    glyphs
        .iter()
        .filter_map(|glyph| match glyph.glyph_type {
            GlyphType::Char { ch } => Some(ch),
            _ => None,
        })
        .collect()
}

/// The invariants every truncated row must satisfy, whatever the content.
fn assert_truncated_row_shape(
    label: &str,
    glyphs: &[neomacs_display_protocol::glyph_matrix::Glyph],
    expected_prefix: &str,
) {
    assert!(
        !glyphs.is_empty(),
        "{label}: the truncated row produced no glyphs"
    );
    let n = glyphs.len();
    assert!(
        matches!(glyphs[n - 1].glyph_type, GlyphType::Char { ch: '$' }),
        "{label}: a truncated row must end in the '$' marker, got {:?}",
        glyphs[n - 1].glyph_type
    );
    let text = row_text(&glyphs[..n - 1]);
    assert_eq!(
        text, expected_prefix,
        "{label}: the truncated row's visible text must be the fitting prefix"
    );
    // Buffer-stamped cells must advance monotonically: a fit-boundary change
    // that re-produced or skipped a character shows up here even when the
    // visible text happens to survive.
    let mut previous: Option<usize> = None;
    for glyph in &glyphs[..n - 1] {
        if glyph.legacy_charpos()
            == neomacs_display_protocol::glyph_matrix::NO_BUFFER_POSITION_CHARPOS
        {
            continue;
        }
        if let Some(previous) = previous {
            assert!(
                glyph.legacy_charpos() >= previous,
                "{label}: glyph charpos stamps must not go backwards ({previous} then {})",
                glyph.legacy_charpos()
            );
        }
        previous = Some(glyph.legacy_charpos());
    }
}

/// The baseline: a plain over-wide line. The cell count is a GOLDEN, not
/// derived from the row — deriving the expectation from the row under test is
/// a tautology that cannot catch a fit-boundary shift, which is exactly the
/// failure this family exists to catch.
const TRUNCATED_ROW_CELLS: usize = 80;

#[test]
fn truncate_shadow_plain_over_wide_line() {
    let glyphs =
        truncated_first_row_glyphs(&format!("{}\nshort\n", "abcdefghij".repeat(12)), |_, _| {});
    assert_eq!(
        glyphs.len(),
        TRUNCATED_ROW_CELLS,
        "the fitting prefix width is a pinned golden"
    );
    let expected: String = "abcdefghij"
        .repeat(12)
        .chars()
        .take(TRUNCATED_ROW_CELLS - 1)
        .collect();
    assert_truncated_row_shape("plain", &glyphs, &expected);
}

/// A face seam inside the DISCARDED tail: the seam is past the fit boundary,
/// so it must not perturb the row at all.
#[test]
fn truncate_shadow_face_seam_in_the_discarded_tail() {
    let baseline =
        truncated_first_row_glyphs(&format!("{}\nshort\n", "abcdefghij".repeat(12)), |_, _| {});
    let fit = baseline.len() - 1;
    let seamed = truncated_first_row_glyphs(
        &format!("{}\nshort\n", "abcdefghij".repeat(12)),
        move |eval, _| {
            let start = fit + 5;
            eval.eval_str(&format!(
                "(put-text-property {} {} 'face '(:weight bold))",
                start + 1,
                start + 4
            ))
            .expect("face property in the tail");
        },
    );
    assert_eq!(
        baseline, seamed,
        "a face seam beyond the fit boundary must not change the truncated row"
    );
}

/// A face seam STRADDLING the fit boundary: the row must still be the same
/// fitting prefix, with the seam's cells carrying their own face.
#[test]
fn truncate_shadow_face_seam_straddling_the_fit_boundary() {
    let baseline =
        truncated_first_row_glyphs(&format!("{}\nshort\n", "abcdefghij".repeat(12)), |_, _| {});
    let fit = baseline.len() - 1;
    let glyphs = truncated_first_row_glyphs(
        &format!("{}\nshort\n", "abcdefghij".repeat(12)),
        move |eval, _| {
            eval.eval_str(&format!(
                "(put-text-property {} {} 'face '(:weight bold))",
                fit - 2,
                fit + 4
            ))
            .expect("face property across the boundary");
        },
    );
    assert_eq!(glyphs.len(), TRUNCATED_ROW_CELLS);
    let expected: String = "abcdefghij"
        .repeat(12)
        .chars()
        .take(TRUNCATED_ROW_CELLS - 1)
        .collect();
    assert_truncated_row_shape("straddling face seam", &glyphs, &expected);
    assert_eq!(
        glyphs.len(),
        baseline.len(),
        "a face seam must not change how much of the line fits"
    );
}

/// Multibyte at the fit boundary: the byte/char reseat is the part most likely
/// to go wrong when the resume position is recomputed rather than carried.
#[test]
fn truncate_shadow_multibyte_at_the_fit_boundary() {
    let line: String = format!("{}漢字漢字漢字{}\nshort\n", "a".repeat(60), "b".repeat(40));
    let glyphs = truncated_first_row_glyphs(&line, |_, _| {});
    let n = glyphs.len();
    assert!(
        matches!(glyphs[n - 1].glyph_type, GlyphType::Char { ch: '$' }),
        "multibyte truncated row must end in the marker"
    );
    // A double-width char occupies two cells; the trailing cell repeats the
    // base's charpos, so collapse by charpos to recover the character text.
    let mut text = String::new();
    let mut previous_charpos: Option<usize> = None;
    for glyph in &glyphs[..n - 1] {
        if previous_charpos == Some(glyph.legacy_charpos()) {
            continue;
        }
        previous_charpos = Some(glyph.legacy_charpos());
        if let GlyphType::Char { ch } = glyph.glyph_type {
            text.push(ch);
        }
    }
    assert!(
        line.starts_with(&text),
        "the truncated row's text must be a prefix of the line, got {text:?}"
    );
    assert!(
        text.contains('漢'),
        "the corpus must reach the multibyte span, got {text:?}"
    );
    let mut previous: Option<usize> = None;
    for glyph in &glyphs[..n - 1] {
        if glyph.legacy_charpos()
            == neomacs_display_protocol::glyph_matrix::NO_BUFFER_POSITION_CHARPOS
        {
            continue;
        }
        if let Some(previous) = previous {
            assert!(
                glyph.legacy_charpos() >= previous,
                "charpos stamps must not regress"
            );
        }
        previous = Some(glyph.legacy_charpos());
    }
}

// A narrow-window case was attempted here and removed: `(split-window-right)`
// in this harness does not narrow the row that `layout_main_text_rows_with`
// returns (the laid-out row still measures the full 80 cells), so the case
// asserted nothing. Reinstating it needs a harness that lays out the SPLIT
// window, not the original one.

// ---------------------------------------------------------------------------
// P4.4: glyph-level shadows for rows whose seam is an OVERLAY-STRING ANCHOR.
//
// The producer ends every run at every overlay boundary (text_source.rs
// `next_property_change`, this engine's compute_stop_pos), so an overlay-string
// anchor always meets a run at the run's START. That makes exactly one
// renderer decision load-bearing: the whole-run and fitting-prefix paths must
// REFUSE a run that starts on an anchor, because only the char path emits
// overlay strings (`starts_at_overlay_string`, text_run.rs). If that refusal
// ever stops firing the string vanishes from the row — invisible to the stream
// harness, which measures producer emission, and visible here.
//
// Every case pins the row's full text AND its cell count as explicit goldens
// derived from the corpus, never from the row under test.
// ---------------------------------------------------------------------------

/// Lay out `text` with an overlay created by `overlay_form` and return the
/// first body row's glyphs.
fn overlay_string_first_row_glyphs(
    text: &str,
    overlay_form: &str,
    truncate: bool,
) -> Vec<neomacs_display_protocol::glyph_matrix::Glyph> {
    let overlay_form = overlay_form.to_owned();
    let (_eval, _buf_id, _frame_id, rows, _cw, _ch) =
        layout_main_text_rows_with(text, move |eval, buf_id| {
            eval.buffer_manager_mut().set_current(buf_id);
            if truncate {
                eval.eval_str("(setq truncate-lines t)").expect("truncate");
            }
            eval.eval_str(&overlay_form).expect("overlay");
        });
    rows[0].glyphs[1].clone()
}

#[test]
fn overlay_string_shadow_before_string_at_a_mid_run_anchor() {
    // The anchor sits inside what would otherwise be one whole run of "hello
    // world": the run must be refused so the "[" is emitted. Golden row text
    // and cell count are read off the corpus: 11 buffer chars + 1 string char
    // + the appended newline space.
    let glyphs = overlay_string_first_row_glyphs(
        "hello world\nnext\n",
        "(overlay-put (make-overlay 4 9) 'before-string \"[\")",
        false,
    );
    assert_eq!(glyphs_logical_text(&glyphs), "hel[lo world ");
    assert_eq!(
        glyphs.len(),
        13,
        "11 text cells + the string cell + the \
         appended newline space"
    );
}

#[test]
fn overlay_string_shadow_after_string_at_a_mid_run_anchor() {
    // The after-string anchors at the overlay's END, which is likewise a
    // mid-run position on the unanchored row.
    let glyphs = overlay_string_first_row_glyphs(
        "hello world\nnext\n",
        "(overlay-put (make-overlay 4 9) 'after-string \"]\")",
        false,
    );
    assert_eq!(glyphs_logical_text(&glyphs), "hello wo]rld ");
    assert_eq!(glyphs.len(), 13);
}

#[test]
fn overlay_string_shadow_both_strings_at_one_overlay() {
    let glyphs = overlay_string_first_row_glyphs(
        "hello world\nnext\n",
        "(let ((ov (make-overlay 4 9))) \
           (overlay-put ov 'before-string \"[\") \
           (overlay-put ov 'after-string \"]\"))",
        false,
    );
    assert_eq!(glyphs_logical_text(&glyphs), "hel[lo wo]rld ");
    assert_eq!(glyphs.len(), 14);
}

#[test]
fn overlay_string_shadow_anchor_at_row_start() {
    // The degenerate position: the anchor coincides with the row's first
    // character, so there is no run to cut — the string still has to render
    // ahead of the buffer text.
    let glyphs = overlay_string_first_row_glyphs(
        "hello world\nnext\n",
        "(overlay-put (make-overlay 1 3) 'before-string \"<\")",
        false,
    );
    assert_eq!(glyphs_logical_text(&glyphs), "<hello world ");
    assert_eq!(glyphs.len(), 13);
}

#[test]
fn overlay_string_shadow_anchor_inside_a_truncated_row() {
    // The compound case: an anchor inside the FITTING prefix of a truncated
    // row. Here `prefix_to_fit` must bail (it cannot emit the string) and the
    // char path must both render the string and reach the truncation marker.
    // The row still holds the pinned 80 cells: 78 buffer chars, the string
    // cell, and the '$'.
    let line = "abcdefghij".repeat(12);
    let glyphs = overlay_string_first_row_glyphs(
        &format!("{line}\nshort\n"),
        "(overlay-put (make-overlay 11 13) 'before-string \"|\")",
        true,
    );
    assert_eq!(
        glyphs.len(),
        TRUNCATED_ROW_CELLS,
        "an overlay string inside the fitting prefix must not change the row width"
    );
    let expected: String = format!("{}|{}$", &line[..10], &line[10..TRUNCATED_ROW_CELLS - 2]);
    assert_eq!(glyphs_logical_text(&glyphs), expected);
}

#[test]
fn overlay_string_shadow_anchor_at_the_truncate_boundary() {
    // The anchor sits on the LAST character that would fit. The string takes
    // that cell, the character it anchors is pushed past the edge, and the row
    // is still marker-terminated at the pinned width: the case where a fit
    // decision and a string emission meet in the same cell.
    let line = "abcdefghij".repeat(12);
    let anchor_charpos = TRUNCATED_ROW_CELLS - 2; // 0-based; make-overlay is 1-based
    let glyphs = overlay_string_first_row_glyphs(
        &format!("{line}\nshort\n"),
        &format!(
            "(overlay-put (make-overlay {} {}) 'before-string \"|\")",
            anchor_charpos + 1,
            anchor_charpos + 3
        ),
        true,
    );
    assert_eq!(glyphs.len(), TRUNCATED_ROW_CELLS);
    let expected: String = format!("{}|$", &line[..TRUNCATED_ROW_CELLS - 2]);
    assert_eq!(
        glyphs_logical_text(&glyphs),
        expected,
        "the string takes the last fitting cell and the marker still terminates the row"
    );
}

/// The glyph sibling of the O5 collection pin, and the case that catches a
/// wrong base-face ORIGIN: an overlay carrying BOTH a `face` and a
/// `before-string`. GNU `face_for_overlay_string` (xfaces.c:7034-7092)
/// "simply disregards the `face' properties of all overlays", so the string
/// is realized against the buffer text's face at the anchor — NOT the face
/// the overlay paints on the text it covers. Resolving the string through
/// `DisplayOrigin::DisplayPropertyString` instead of `OverlayString` would
/// tint it with the overlay's face and red this test.
#[test]
fn overlay_string_shadow_base_face_ignores_the_overlays_own_face() {
    // An ANONYMOUS face (attribute plist): a named face resolves or not
    // depending on what Lisp the build dumped.
    let glyphs = overlay_string_first_row_glyphs(
        "hello world\nnext\n",
        "(let ((ov (make-overlay 4 9))) \
           (overlay-put ov 'face '(:foreground \"#ff0000\")) \
           (overlay-put ov 'before-string \"[\"))",
        false,
    );
    assert_eq!(glyphs_logical_text(&glyphs), "hel[lo world ");
    assert_eq!(glyphs.len(), 13);
    // Cell 0..=2 are the un-overlaid "hel", cell 3 is the string, cells
    // 4..=8 are the overlay-faced "lo wo".
    let plain_face = glyphs[0].face_id;
    let overlay_face = glyphs[4].face_id;
    assert_ne!(
        overlay_face, plain_face,
        "the corpus must actually realize a distinct overlay face, else the \
         assertions below are vacuous"
    );
    // The string resolves its OWN base face from the buffer text at the
    // anchor, which carries no `face` property here, so it lands on the
    // engine's Default face id rather than on the window's realized base
    // text face (the resolver reuses the installed default instead of
    // minting a window-specific id for it).
    assert_eq!(
        glyphs[3].face_id,
        FaceId::from(neomacs_display_protocol::face::BasicFaceId::Default),
        "an overlay string is realized against the buffer text at its anchor"
    );
    assert_ne!(
        glyphs[3].face_id, overlay_face,
        "the overlay's own face must never tint its string (GNU \
         face_for_overlay_string disregards overlay faces)"
    );
}

/// Two anchors on one row: the strings must land at their OWN anchors, in
/// row order. An insertion that sorted after the text segment starting at the
/// same position would put each string one character late.
#[test]
fn overlay_string_shadow_two_anchors_on_one_row() {
    let glyphs = overlay_string_first_row_glyphs(
        "hello world\nnext\n",
        "(progn \
           (overlay-put (make-overlay 3 4) 'before-string \"<\") \
           (overlay-put (make-overlay 9 10) 'before-string \">\"))",
        false,
    );
    assert_eq!(glyphs_logical_text(&glyphs), "he<llo wo>rld ");
    assert_eq!(
        glyphs.len(),
        14,
        "11 text cells + two string cells + the appended newline space"
    );
}

// ---------------------------------------------------------------------------
// P4.5: glyph-level shadows for the PER-CHAR path.
//
// The per-char split feeder is not a measurement shortcut (unlike P4.3's fit
// split): deleting it changes how many append calls a row sees, and three
// pieces of renderer state are driven by those calls — cursor capture
// (char_render.rs), the word-wrap candidate hook (record_word_wrap_candidate),
// and trailing-whitespace tracking. This family aims at exactly those three,
// not at row content, which the existing shadow families already cover.
//
// Geometry goldens used below, established once and stated here rather than
// derived from the row under test: a 640px frame lays out 79 buffer cells per
// row (the 80th column carries the wrap indicator), and an 88px frame lays out
// 10 cells per row. Both corpora wrap, so every row after the first is produced
// through the overflow path the per-char feeder drives.
// ---------------------------------------------------------------------------

/// The first buffer charpos of each text row that displays text — where the
/// renderer decided to break.
fn row_break_charposes(trace: &BackendLayoutTrace) -> Vec<usize> {
    trace
        .matrix_rows
        .iter()
        .filter(|row| !row.mode_line && row.role == GlyphRowRole::Text && row.displays_text)
        .filter_map(|row| {
            row.glyph_areas[1]
                .iter()
                .find_map(|glyph| match glyph.kind {
                    GlyphKindTrace::Char(_) => Some(glyph.charpos),
                    _ => None,
                })
        })
        .collect()
}

/// The characters of each text row that displays text.
fn row_texts(trace: &BackendLayoutTrace) -> Vec<String> {
    trace
        .matrix_rows
        .iter()
        .filter(|row| !row.mode_line && row.role == GlyphRowRole::Text && row.displays_text)
        .map(|row| {
            row.glyph_areas[1]
                .iter()
                .filter_map(|glyph| match glyph.kind {
                    GlyphKindTrace::Char(ch) => Some(ch),
                    _ => None,
                })
                .collect()
        })
        .collect()
}

fn char_wrap_cursor_at(text: &str, point_byte: usize) -> (i64, i64) {
    let trace = layout_trace_with_buffer_setup(text, 640, 240, move |buffer, _, _| {
        buffer.set_buffer_local("truncate-lines", Value::NIL);
        buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(point_byte));
    });
    let cursor = trace.phys_cursor.as_ref().expect("phys cursor");
    (cursor.row, cursor.col)
}

/// Cursor placement across a CHARACTER-WRAPPED line. Every row here is assembled
/// through the per-char path (the line's single run never fits), so the cursor
/// slot comes from `capture_cursor_info_for_main_char_if_point` on the exact
/// append call that carries point. Goldens are stated, not derived: 79 cells per
/// row means point 79 is the first character of the continuation row.
#[test]
fn p45_cursor_shadow_tracks_point_across_a_char_wrapped_line() {
    let text = format!("{}\n", "a".repeat(100));

    assert_eq!(char_wrap_cursor_at(&text, 0), (0, 0), "line start");
    assert_eq!(char_wrap_cursor_at(&text, 1), (0, 1), "second character");
    assert_eq!(
        char_wrap_cursor_at(&text, 78),
        (0, 78),
        "the last character that fits on the first row"
    );
    assert_eq!(
        char_wrap_cursor_at(&text, 79),
        (1, 0),
        "the wrap character opens the continuation row"
    );
    assert_eq!(
        char_wrap_cursor_at(&text, 80),
        (1, 1),
        "the character after the wrap"
    );
    assert_eq!(
        char_wrap_cursor_at(&text, 100),
        (1, 21),
        "end of line: 100 chars = 79 on the first row plus 21 on the second"
    );

    // The break itself is pinned separately so a cursor golden cannot silently
    // absorb a break that moved.
    let trace = layout_trace_with_buffer_setup(&text, 640, 240, |buffer, _, _| {
        buffer.set_buffer_local("truncate-lines", Value::NIL);
    });
    assert_eq!(row_break_charposes(&trace), vec![0, 79]);
}

/// Word-wrap break positions on the C9 corpora from tmp/p4-test-inventory.md.
/// The candidate hook fires per rendered character on the per-char path, so
/// these break positions are the direct observable of the feeder this rung
/// deletes. 10 cells per row at 88px.
#[test]
fn p45_word_wrap_break_shadow_pins_the_c9_corpora() {
    fn word_wrap_trace(text: &'static str) -> BackendLayoutTrace {
        layout_trace_with_buffer_setup(text, 88, 240, |buffer, _, _| {
            buffer.set_buffer_local("truncate-lines", Value::NIL);
            buffer.set_buffer_local("word-wrap", Value::T);
        })
    }

    // C9a candidate-at-space: the break takes the whole word to the next row,
    // which resumes at the 'b' (charpos 5), and the row that broke keeps the
    // trailing space of the word boundary. GNU's word-wrap branch
    // (`back_to_wrap`, src/xdisp.c:26360-26388) marks the row continued without
    // producing IT_CONTINUATION, so the broken row carries no marker.
    let c9a = word_wrap_trace("aaaa bbbbbb\n");
    assert_eq!(row_break_charposes(&c9a), vec![0, 5]);
    assert_eq!(row_texts(&c9a), vec!["aaaa ", "bbbbbb "]);

    // C9b candidate-mid-run: the b-word is itself longer than the row, so after
    // the space break it CHARACTER-wraps with no candidate inside it. Only that
    // second, mid-element break produces the marker
    // (src/xdisp.c:26421-26432).
    let c9b = word_wrap_trace("aaaa bbbbbbbbbbbb\n");
    assert_eq!(row_break_charposes(&c9b), vec![0, 5, 15]);
    assert_eq!(row_texts(&c9b), vec!["aaaa ", "bbbbbbbbbb\\", "bb "]);

    // C9c no candidate at all: word wrap degrades to character wrap at the row
    // edge.
    let c9c = word_wrap_trace("aaaaaaaaaaaa\n");
    assert_eq!(row_break_charposes(&c9c), vec![0, 10]);
    assert_eq!(row_texts(&c9c), vec!["aaaaaaaaaa\\", "aa "]);

    // C9d candidate before a tab: the tab expands from column 5 to the next stop
    // (column 8), so the line ends at exactly the row edge and never breaks —
    // the case that pins tab expansion and the candidate hook interacting.
    let c9d = word_wrap_trace("aaaa \tbb\n");
    assert_eq!(row_break_charposes(&c9d), vec![0]);
    assert_eq!(row_texts(&c9d), vec!["aaaa bb "]);
}

/// Cursor placement inside a WORD-WRAPPED row: the candidate space stays on the
/// row that broke, and the word that moved down opens the continuation row.
#[test]
fn p45_cursor_shadow_tracks_point_across_a_word_wrap_break() {
    fn cursor_at(point_byte: usize) -> (i64, i64) {
        let trace =
            layout_trace_with_buffer_setup("aaaa bbbbbb\n", 88, 240, move |buffer, _, _| {
                buffer.set_buffer_local("truncate-lines", Value::NIL);
                buffer.set_buffer_local("word-wrap", Value::T);
                buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(point_byte));
            });
        let cursor = trace.phys_cursor.as_ref().expect("phys cursor");
        (cursor.row, cursor.col)
    }

    assert_eq!(cursor_at(3), (0, 3), "inside the first word");
    assert_eq!(cursor_at(4), (0, 4), "the candidate space itself");
    // CURRENT BEHAVIOUR, pinned as-is: point on the word that moved down is
    // placed in the broken row's filler column rather than at the start of the
    // continuation row. GNU puts it at the continuation row's first column, so
    // this is an open parity question — recorded here rather than "fixed" mid
    // rung, because the shadow's job is to detect a CHANGE in what the per-char
    // feeder's removal does to cursor capture.
    assert_eq!(cursor_at(5), (0, 5), "the word that moved to the next row");
    assert_eq!(cursor_at(10), (1, 5), "the last character of the word");
}

/// Trailing-whitespace highlighting across a WRAPPED boundary.
///
/// Measured, not assumed: the highlight is NOT produced by the per-char
/// `TrailingWhitespaceRenderState` tracker at all — it is a row-finalization
/// pass over finished glyphs (`HighlightTrailingWhitespaceMutation`, GNU
/// highlight_trailing_whitespace), ordered by line_end::plan at true line ends
/// only. Mutating either tracker (per-char or whole-run) leaves this test green;
/// perturbing the finalization pass reds it. So what this case guards is the
/// glyph-level input that pass consumes — which row each buffer space lands on,
/// and which glyphs carry buffer positions — exactly what changes if the
/// per-char rewiring moves a character between rows.
#[test]
fn p45_trailing_whitespace_shadow_survives_a_wrapped_row_boundary() {
    // The line is 11 characters wide in a 10-cell row, so its single run never
    // fits and EVERY glyph on both rows — the trailing spaces included — is
    // appended through the per-char path this rung rewires.
    let trace = layout_trace_with_buffer_setup("aaaaaaaa   \n", 88, 240, |buffer, _, _| {
        buffer.set_buffer_local("truncate-lines", Value::NIL);
        buffer.set_buffer_local("show-trailing-whitespace", Value::T);
    });
    assert_eq!(row_break_charposes(&trace), vec![0, 10]);
    assert_eq!(row_texts(&trace), vec!["aaaaaaaa  \\", "  "]);

    let continuation = trace
        .matrix_rows
        .iter()
        .filter(|row| !row.mode_line && row.role == GlyphRowRole::Text && row.displays_text)
        .nth(1)
        .expect("continuation row");
    let highlighted: Vec<usize> = continuation.glyph_areas[1]
        .iter()
        .filter(|glyph| glyph.face.contains("trailing-whitespace"))
        .map(|glyph| glyph.charpos)
        .collect();
    // Charpos 10 is the third trailing space, the only buffer glyph on the
    // continuation row; the row's other glyph is the appended positionless
    // newline space, which GNU never highlights.
    assert_eq!(highlighted, vec![10]);

    // The spaces that stayed on the CONTINUED row are NOT highlighted: the
    // highlight is row-scoped and fires only on the row where the line actually
    // ends (GNU highlights trailing whitespace on the row that reaches the
    // newline, not on a continued row). Pinning both halves is what makes this
    // a statement about the tracker rather than about one row.
    let first = trace
        .matrix_rows
        .iter()
        .find(|row| !row.mode_line && row.role == GlyphRowRole::Text && row.displays_text)
        .expect("first row");
    let highlighted_first: Vec<usize> = first.glyph_areas[1]
        .iter()
        .filter(|glyph| glyph.face.contains("trailing-whitespace"))
        .map(|glyph| glyph.charpos)
        .collect();
    assert!(
        highlighted_first.is_empty(),
        "a continued row must not highlight trailing whitespace, got {highlighted_first:?}"
    );
}

// ---------------------------------------------------------------------------
// P4.6: the overlay-string ORDERING and CURSOR net.
//
// P4.6 moves collection and ordering of overlay strings from the renderer-side
// session into the producer. These cases pin what the finished row shows for
// the ordering rules the dossier calls the minefield (tmp/p4-test-inventory.md
// section 2), so the move is glyph-for-glyph observable. Deliberately NOT
// pinned, per the inventory: equal-priority same-kind order (GNU's qsort is
// unstable there) and anything about GNU's 16-chunk re-collection (this engine
// walks a snapshot).
// ---------------------------------------------------------------------------

/// Lay out `text` with several overlays and return the first body row's text.
fn overlay_string_row_text(text: &str, overlay_forms: &[&str]) -> String {
    let forms = overlay_forms
        .iter()
        .map(|form| (*form).to_owned())
        .collect::<Vec<_>>();
    let (_eval, _buf_id, _frame_id, rows, _cw, _ch) =
        layout_main_text_rows_with(text, move |eval, buf_id| {
            eval.buffer_manager_mut().set_current(buf_id);
            for form in forms {
                eval.eval_str(&form).expect("overlay form");
            }
        });
    glyphs_logical_text(&rows[0].glyphs[1])
}

/// O1: an after-string and a before-string from DIFFERENT overlays at the same
/// position — the after-string comes first (GNU compare_overlay_entries: "let
/// after-strings appear in front of before-strings if they come from different
/// overlays").
#[test]
fn overlay_string_shadow_after_string_precedes_before_string_at_one_anchor() {
    let text = overlay_string_row_text(
        "hello world\n",
        &[
            "(overlay-put (make-overlay 1 4) 'after-string \"A\")",
            "(overlay-put (make-overlay 4 9) 'before-string \"B\")",
        ],
    );
    assert_eq!(text, "helAB'lo world ".replace('\'', ""));
}

/// O3: within a group the priority sort direction REVERSES — before-strings
/// ascend by priority, after-strings descend.
#[test]
fn overlay_string_shadow_before_strings_ascend_and_after_strings_descend_by_priority() {
    let before = overlay_string_row_text(
        "hello world\n",
        &[
            "(let ((ov (make-overlay 4 9))) (overlay-put ov 'priority 5) \
               (overlay-put ov 'before-string \"5\"))",
            "(let ((ov (make-overlay 4 9))) (overlay-put ov 'priority 1) \
               (overlay-put ov 'before-string \"1\"))",
        ],
    );
    assert_eq!(before, "hel15lo world ");

    let after = overlay_string_row_text(
        "hello world\n",
        &[
            "(let ((ov (make-overlay 1 4))) (overlay-put ov 'priority 5) \
               (overlay-put ov 'after-string \"5\"))",
            "(let ((ov (make-overlay 1 4))) (overlay-put ov 'priority 1) \
               (overlay-put ov 'after-string \"1\"))",
        ],
    );
    assert_eq!(after, "hel51lo world ");
}

/// O4: a CONS priority degrades to 0 for STRING ordering (GNU
/// load_overlay_strings: FIXNUMP (priority) ? XFIXNUM : 0), so the cons-priority
/// string sorts as priority 0 among before-strings and lands first.
#[test]
fn overlay_string_shadow_cons_priority_degrades_to_zero_for_string_order() {
    let text = overlay_string_row_text(
        "hello world\n",
        &[
            "(let ((ov (make-overlay 4 9))) (overlay-put ov 'priority '(7 . 1)) \
               (overlay-put ov 'before-string \"C\"))",
            "(let ((ov (make-overlay 4 9))) (overlay-put ov 'priority 3) \
               (overlay-put ov 'before-string \"3\"))",
        ],
    );
    assert_eq!(text, "helC3lo world ");
}

/// O6: an empty string produces nothing and a non-string value is ignored —
/// neither may leave a glyph or perturb the row.
#[test]
fn overlay_string_shadow_empty_and_non_string_values_are_dropped() {
    let baseline = overlay_string_row_text("hello world\n", &[]);
    assert_eq!(baseline, "hello world ");

    let dropped = overlay_string_row_text(
        "hello world\n",
        &[
            "(overlay-put (make-overlay 4 9) 'before-string \"\")",
            "(overlay-put (make-overlay 4 9) 'after-string 42)",
        ],
    );
    assert_eq!(dropped, baseline);
}

/// O7: an overlay whose own text is invisible shows BOTH of its strings, once,
/// where the elided text was. GNU reaches that by collecting both strings at
/// both endpoints (xdisp.c:7157-7173) while the iterator only ever stops at the
/// end of the invisible run; this engine reaches the same row the same way, and
/// this is the assertion that says so in glyphs rather than in collection.
#[test]
fn overlay_string_shadow_invisible_overlay_shows_both_strings_once() {
    let text = overlay_string_row_text(
        "abcdefgh\n",
        &[
            "(let ((ov (make-overlay 4 7))) (overlay-put ov 'invisible t) \
               (overlay-put ov 'before-string \"B\") \
               (overlay-put ov 'after-string \"A\"))",
        ],
    );
    // "def" is hidden; the overlay's before-string leads its after-string
    // (the same-overlay rule) in the single place they appear.
    assert_eq!(text, "abcBAgh ");

    // The control that makes the elision half load-bearing: the same overlay
    // WITHOUT `invisible` keeps its text and puts each string at its own end.
    let visible = overlay_string_row_text(
        "abcdefgh\n",
        &["(let ((ov (make-overlay 4 7))) \
               (overlay-put ov 'before-string \"B\") \
               (overlay-put ov 'after-string \"A\"))"],
    );
    assert_eq!(visible, "abcBdefAgh ");
}

/// Cursor placement AROUND an anchor. Overlay strings are not cursor targets
/// unless they carry a `cursor` text property, so point on the anchor character
/// must land on the buffer character, at the column AFTER the inserted string.
#[test]
fn overlay_string_shadow_cursor_lands_on_the_buffer_char_after_an_inserted_string() {
    fn cursor_at(point_byte: usize) -> (i64, i64) {
        let trace =
            layout_trace_with_buffer_setup("hello world\n", 640, 240, move |buffer, buf_id, _| {
                // The overlay is built directly rather than through eval so the
                // setup closure keeps its `&mut Buffer` shape.
                let start = buffer.char_pos_to_emacs_byte_pos_clamped(CharPos0::new(3));
                let end = buffer.char_pos_to_emacs_byte_pos_clamped(CharPos0::new(8));
                let overlay = Value::make_overlay(neovm_core::heap_types::OverlayDataInit {
                    serial: 0,
                    plist: Value::NIL,
                    buffer: Some(buf_id),
                    start: start.get(),
                    end: end.get(),
                    front_advance: false,
                    rear_advance: false,
                });
                buffer.overlays_mut().insert_overlay(overlay);
                buffer
                    .overlays_mut()
                    .overlay_put(overlay, Value::symbol("before-string"), Value::string("[["))
                    .expect("before-string");
                buffer.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(point_byte));
            });
        let cursor = trace.phys_cursor.as_ref().expect("phys cursor");
        (cursor.row, cursor.col)
    }

    // charpos 2 is before the anchor: unshifted.
    assert_eq!(cursor_at(2), (0, 2));
    // charpos 3 is the anchor character itself ('l', where the overlay starts).
    // The two string cells are inserted BEFORE it, so the cursor sits at column
    // 3 + 2.
    assert_eq!(cursor_at(3), (0, 5));
    // A character after the anchor keeps the same shift.
    assert_eq!(cursor_at(6), (0, 8));
}

/// An overlay string is emitted EXACTLY ONCE per anchor, including when its
/// anchor character is the one that wraps.
///
/// Before P4.6 the renderer re-ran the overlay-string session on every char
/// step, and a wrap re-steps the anchor character, so the string was drawn twice
/// — once at the end of the row that broke and again at the start of the
/// continuation row (both the character-wrap and the word-wrap paths did this).
/// Producer-owned emission with insertion semantics fixes it: the anchor is
/// surfaced once and the marker survives the row-transition retry, which is
/// GNU's model (an overlay string is consumed once, its overlay_string_index
/// advancing past it).
///
/// What this case does NOT claim: that the string travels with its anchor
/// character across the break. It stays on the row it was appended to while the
/// character moves down, which is a separate divergence from GNU and predates
/// this rung.
#[test]
fn overlay_string_shadow_emits_once_across_a_wrap_at_its_own_anchor() {
    let line = format!("{}Xbbb\n", "a".repeat(78));
    let anchored = |anchor_char: usize| -> Vec<String> {
        let text = line.clone();
        let (_eval, _buf_id, _frame_id, rows, _cw, _ch) =
            layout_main_text_rows_with(&text, move |eval, buf_id| {
                eval.buffer_manager_mut().set_current(buf_id);
                eval.eval_str("(setq truncate-lines nil)").expect("wrap");
                eval.eval_str(&format!(
                    "(overlay-put (make-overlay {} {}) 'before-string \"S\")",
                    anchor_char + 1,
                    anchor_char + 2
                ))
                .expect("overlay");
            });
        rows.iter()
            .map(|row| glyphs_logical_text(&row.glyphs[1]))
            .filter(|text| !text.is_empty())
            .collect()
    };

    // Anchor ON the wrap edge: the string takes the last cell of the broken row
    // and the continuation row starts at the buffer character, unrepeated.
    let at_edge = anchored(78);
    assert_eq!(at_edge.len(), 2);
    assert!(
        at_edge[0].ends_with("aaaaS\\"),
        "the broken row must end with the string then the wrap indicator, got {:?}",
        at_edge[0]
    );
    assert_eq!(at_edge[1], "Xbbb ");

    // Anchor mid-row, for contrast: also exactly once.
    let mid_row = anchored(4);
    assert_eq!(mid_row.len(), 2);
    assert_eq!(mid_row[0].matches('S').count(), 1);
    assert_eq!(mid_row[1], "Xbbb ");
}

/// GNU checkpoints the complete display iterator before the first glyph after
/// whitespace.  When that glyph comes from an overlay before-string, the
/// string travels with its anchor word to the continuation row and is emitted
/// exactly once there.
#[test]
fn overlay_string_shadow_emits_once_across_a_word_wrap_break() {
    let (_eval, _buf_id, _frame_id, rows, _cw, _ch) = layout_main_text_rows_with(
        &format!("{} bbbbbbbbbb\n", "a".repeat(70)),
        |eval, buf_id| {
            eval.buffer_manager_mut().set_current(buf_id);
            eval.eval_str("(setq truncate-lines nil)").expect("wrap");
            eval.eval_str("(setq word-wrap t)").expect("word-wrap");
            eval.eval_str("(overlay-put (make-overlay 72 74) 'before-string \"SS\")")
                .expect("overlay");
        },
    );
    let texts: Vec<String> = rows
        .iter()
        .map(|row| glyphs_logical_text(&row.glyphs[1]))
        .filter(|text| !text.is_empty())
        .collect();
    assert_eq!(texts.len(), 2);
    assert_eq!(texts[0].matches('S').count(), 0, "the string must travel");
    assert_eq!(texts[1], "SSbbbbbbbbbb ");
}

/// `may_wrap` still gates the overlay-string checkpoint.  A string anchored
/// inside an unbroken word stays on the character-wrapped row; merely being a
/// producer-owned insertion element must not manufacture a word boundary.
#[test]
fn overlay_string_does_not_create_a_wrap_candidate_without_preceding_whitespace() {
    let (_eval, _buf_id, _frame_id, rows, _cw, _ch) = layout_main_text_rows_with(
        &format!("{}bbbbbbbbbb\n", "a".repeat(71)),
        |eval, buf_id| {
            eval.buffer_manager_mut().set_current(buf_id);
            eval.eval_str("(setq truncate-lines nil)").expect("wrap");
            eval.eval_str("(setq word-wrap t)").expect("word-wrap");
            eval.eval_str("(overlay-put (make-overlay 72 74) 'before-string \"SS\")")
                .expect("overlay");
        },
    );
    let texts: Vec<String> = rows
        .iter()
        .map(|row| glyphs_logical_text(&row.glyphs[1]))
        .filter(|text| !text.is_empty())
        .collect();

    assert_eq!(texts.len(), 2);
    assert_eq!(texts[0].matches('S').count(), 2);
    assert_eq!(texts[1].matches('S').count(), 0);
}

// ---------------------------------------------------------------------------
// P4.6 sub-step 3a: a NEWLINE INSIDE an overlay string.
//
// Verified before anything was added, and nothing needed adding: the retained
// session already meets DisplayRowRenderStop::RowBreak inside the string and
// runs OverlayStringRowBreakRenderContext::finish_row, which drives the ordinary
// DisplayRowLineBreakTransitionRequest and re-emits the continuation-row
// prelude. What follows pins what that path already establishes - row flags,
// end-of-buffer marking and row bounds - so a later rung cannot quietly change
// any of it, and records the one place the engine deliberately parts company
// with GNU's find_row_edges table.
// ---------------------------------------------------------------------------

/// The rows a newline-bearing before-string produces, as
/// (text, continued, ends_at_zv).
fn newline_string_rows(
    text: &'static str,
    anchor_charpos0: usize,
    truncate: bool,
) -> Vec<(String, bool, bool)> {
    let form = format!(
        "(overlay-put (make-overlay {} {}) 'before-string \"X\\nY\")",
        anchor_charpos0 + 1,
        anchor_charpos0 + 2
    );
    let (_eval, _buf_id, _frame_id, rows, _cw, _ch) =
        layout_main_text_rows_with(text, move |eval, buf_id| {
            eval.buffer_manager_mut().set_current(buf_id);
            eval.eval_str(if truncate {
                "(setq truncate-lines t)"
            } else {
                "(setq truncate-lines nil)"
            })
            .expect("wrap mode");
            eval.eval_str(&form).expect("overlay");
        });
    rows.iter()
        .map(|row| {
            (
                glyphs_logical_text(&row.glyphs[1]),
                row.continued,
                row.ends_at_zv,
            )
        })
        .filter(|(text, _, ends_at_zv)| !text.is_empty() || *ends_at_zv)
        .collect()
}

/// A newline inside an overlay string breaks the row where it appears, and the
/// buffer character the string was anchored to opens the next row.
///
/// The row is NOT marked `continued`: GNU distinguishes "line ends in a newline
/// from string" from "line is continued from string" (find_row_edges,
/// xdisp.c:25248-25263), and a newline ENDS the line. Only the overflow
/// transition marks Continued/Continuation in this engine, so the distinction
/// falls out of which transition the break runs.
#[test]
fn overlay_string_newline_breaks_the_row_without_marking_it_continued() {
    let mid_row = newline_string_rows("hello world\nsecond\n", 3, false);
    assert_eq!(
        mid_row,
        vec![
            ("helX ".to_owned(), false, false),
            ("Ylo world ".to_owned(), false, false),
            ("second ".to_owned(), false, false),
            (String::new(), false, true),
        ]
    );

    // At a row start the string owns the whole first row and the buffer line
    // begins on the next one.
    let row_start = newline_string_rows("hello world\nsecond\n", 0, false);
    assert_eq!(
        row_start,
        vec![
            ("X ".to_owned(), false, false),
            ("Yhello world ".to_owned(), false, false),
            ("second ".to_owned(), false, false),
            (String::new(), false, true),
        ]
    );
}

/// The same in a TRUNCATE window. A string newline is not an overflow, so the
/// wrap policy has nothing to say about it and both windows agree row for row.
#[test]
fn overlay_string_newline_behaves_identically_under_truncation() {
    for anchor in [3, 0] {
        assert_eq!(
            newline_string_rows("hello world\nsecond\n", anchor, true),
            newline_string_rows("hello world\nsecond\n", anchor, false),
            "a newline inside a string is not an overflow, so wrap policy \
             cannot change it (anchor {anchor})"
        );
    }
}

/// Row BOUNDS across a string newline, and the deliberate divergence.
///
/// A row's published bounds are built by `note_display_buffer_pos`, which only
/// BUFFER characters call: overlay-string glyphs contribute none, so the row
/// that ends in the string's newline is bounded by the last buffer character
/// before the anchor and the next row starts at the anchor itself. (Verified by
/// mutation, and worth stating because the intuitive guess is wrong - the
/// anchor-boundary hit range that `finish_row` maintains is a separate,
/// hit-testing observable and does NOT feed these numbers.)
///
/// GNU instead fabricates one past the end for such a row ("Line ends in a
/// newline from string: max_pos + 1", xdisp.c:25248-25263), because its rows
/// carry the string's own positions. Glyphs now retain those string indices,
/// but row bounds remain the independent buffer-scan track: adopting the
/// provenance pair does not by itself implement GNU's once-per-string `+1`
/// synthesis for a string-supplied newline. This test records that separate
/// row-lifecycle divergence.
#[test]
fn overlay_string_newline_leaves_row_bounds_on_the_anchor_boundary() {
    fn bounds(anchor_charpos0: usize) -> Vec<(Option<usize>, Option<usize>)> {
        let trace = layout_trace_with_buffer_setup(
            "hello world\nsecond\n",
            640,
            240,
            move |buffer, buf_id, _| {
                let start =
                    buffer.char_pos_to_emacs_byte_pos_clamped(CharPos0::new(anchor_charpos0));
                let end =
                    buffer.char_pos_to_emacs_byte_pos_clamped(CharPos0::new(anchor_charpos0 + 1));
                let overlay = Value::make_overlay(neovm_core::heap_types::OverlayDataInit {
                    serial: 0,
                    plist: Value::NIL,
                    buffer: Some(buf_id),
                    start: start.get(),
                    end: end.get(),
                    front_advance: false,
                    rear_advance: false,
                });
                buffer.overlays_mut().insert_overlay(overlay);
                buffer
                    .overlays_mut()
                    .overlay_put(
                        overlay,
                        Value::symbol("before-string"),
                        Value::string("X\nY"),
                    )
                    .expect("before-string");
            },
        );
        trace
            .output_rows
            .iter()
            .take(3)
            .map(|row| {
                (
                    row.start_buffer_pos.map(|pos| pos.to_one_based_usize()),
                    row.end_buffer_pos.map(|pos| pos.to_one_based_usize()),
                )
            })
            .collect()
    }

    // Anchor on the 4th character (1-based 4). The first row displays chars 1-3
    // plus the string's "X"; the string's newline ends it there, and the
    // anchor character opens the next row.
    assert_eq!(
        bounds(3),
        vec![
            (Some(1), Some(3)),
            (Some(4), Some(12)),
            (Some(13), Some(19)),
        ]
    );

    // A row made ENTIRELY of string glyphs carries no buffer bounds at all.
    // GNU's degenerate answer is min_pos == max_pos; this engine's Option says
    // the same thing without inventing a position, and a consumer that needs
    // one falls back to the following row's start.
    assert_eq!(
        bounds(0),
        vec![(None, None), (Some(1), Some(12)), (Some(13), Some(19))]
    );
}

// ---------------------------------------------------------------------------
// P4.7 step 0: pre-existing-divergence detectors for the replacement rung.
//
// R1 and R6 from the phase-4 inventory describe GNU rules the engine is
// believed to already follow. They are written BEFORE the rung so that if
// either is red, the divergence is fixed on its own commit rather than being
// absorbed into a refactor that would then be blamed for it.
// ---------------------------------------------------------------------------

/// The first body row's logical text, laid out with `setup` run against the
/// fixture's own Context.
fn display_prop_first_row_text(text: &str, setup: &str) -> String {
    let setup = setup.to_owned();
    let (_eval, _buf_id, _frame_id, rows, _cw, _ch) =
        layout_main_text_rows_with(text, move |eval, buf_id| {
            eval.buffer_manager_mut().set_current(buf_id);
            eval.eval_str(&setup).expect("display property setup");
        });
    glyphs_logical_text(&rows[0].glyphs[1])
}

/// R1: an OVERLAY-sourced `display` property covers exactly the overlay, not
/// the extent over which the resolved value happens to stay the same.
///
/// GNU xdisp.c:6337-6363 sets the covered range's end to `OVERLAY_END
/// (overlay)` unconditionally, and its comment names both failure directions
/// that the alternative - `display_prop_end`, which finds another `display`
/// property "coming from some other overlay or text property on buffer
/// positions before this overlay's end" - would cause: "we risk displaying
/// this overlay's display string/image twice, or fail to display text that
/// should be".
#[test]
fn overlay_sourced_display_property_covers_exactly_the_overlay() {
    // Direction 1, "fail to display text that should be": the SAME string
    // object continues past the overlay end as a text property. The overlay
    // covers [3,9); the text property covers [9,10) and is its own, second
    // replacement. Swallowing "j" into one replacement renders one "S".
    assert_eq!(
        display_prop_first_row_text(
            "abcdefghij\n",
            "(let ((s \"S\")) \
               (overlay-put (make-overlay 4 10) 'display s) \
               (put-text-property 10 11 'display s))",
        ),
        "abcSS ",
        "the overlay's range and the text property's range are two separate \
         replacements, even sharing one string object"
    );
}

/// R1, second direction: see
/// [`overlay_sourced_display_property_covers_exactly_the_overlay`].
#[test]
fn overlay_sourced_display_property_is_not_re_entered_mid_overlay() {
    // Direction 2, "displaying this overlay's display string twice": a
    // higher-priority overlay interrupts the resolved value mid-range. The
    // outer overlay still covers [3,9) in one replacement, so its "S" is
    // emitted once and the inner "T" is never reached.
    assert_eq!(
        display_prop_first_row_text(
            "abcdefghij\n",
            "(let ((outer (make-overlay 4 10)) (inner (make-overlay 6 8))) \
               (overlay-put outer 'display \"S\") \
               (overlay-put outer 'priority 0) \
               (overlay-put inner 'display \"T\") \
               (overlay-put inner 'priority 10))",
        ),
        "abcSj ",
        "an overlay display property is one replacement over the whole \
         overlay; resuming inside it would emit the string twice"
    );
}

/// GNU `handle_stop` loads overlay strings before it dispatches the display
/// property on the buffer character at the same position.  Org numbering uses
/// exactly this shape for linked headlines: its numbering overlay ends where
/// the link's display replacement begins.
#[test]
fn overlay_after_string_at_display_replacement_start_is_not_dropped() {
    assert_eq!(
        display_prop_first_row_text(
            "** link\n",
            "(let ((numbering (make-overlay 1 4))) \
               (overlay-put numbering 'after-string \"3.1 \") \
               (put-text-property 4 8 'display \"Title\"))",
        ),
        "** 3.1 Title ",
        "an overlay after-string is an insertion before a display replacement \
         anchored at the same buffer position"
    );
}

/// Org hides the link target immediately after the stars and numbering
/// overlay.  GNU carries the overlay string across that invisible-text stop;
/// the insertion must not disappear with the skipped buffer run.
#[test]
fn overlay_after_string_at_invisible_run_start_is_not_dropped() {
    assert_eq!(
        display_prop_first_row_text(
            "** hiddenTitle\n",
            "(let ((numbering (make-overlay 1 4))) \
               (overlay-put numbering 'after-string \"3.1 \") \
               (put-text-property 4 10 'invisible t))",
        ),
        "** 3.1 Title ",
        "an overlay after-string remains visible when hidden text starts at \
         its attachment position"
    );
}

/// An image whose file cannot be loaded still REPLACES its covered range: the
/// covered text does not reappear, and the walk resumes past that range exactly
/// once.
///
/// GNU renders an image it cannot load as its own placeholder rather than
/// revealing the text underneath (`lookup_image` hands back a "broken image"
/// glyph); the covered range was already taken over by
/// `handle_single_display_spec`. This engine reaches the same answer through
/// `media_fallback_placeholder` (display_property.rs) — `[img]` for an image —
/// so the replacement resolves and only its CONTENT is a stand-in.
///
/// Pinned for P4.7 because it is the observable the frame semantics turn on:
/// whatever a replacement resolves to, the resume is the covered range's end E
/// and "g" follows the placeholder once. Nothing at this level covered a media
/// replacement's resume before.
#[test]
fn an_unloadable_image_replacement_still_covers_its_range() {
    // The spec covers 1-based [4,7) — "def" — and resolves to the placeholder,
    // so the row reads abc[img]ghij: the covered chars are gone and "g"
    // follows exactly once.
    assert_eq!(
        display_prop_first_row_text(
            "abcdefghij\n",
            "(put-text-property 4 7 'display \
               '(image :type png :file \"/nonexistent-neomacs-p47-pin.png\"))",
        ),
        "abc[img]ghij ",
        "an unloadable image is still a replacement over its whole covered \
         range; the covered text must not reappear and must not be re-walked"
    );
}

/// A `display` spec the renderer cannot resolve DECLINES the replacement: the
/// covered text displays normally, exactly once, and the walk resumes at the
/// covered range's end E exactly once.
///
/// This is the render-time fallback branch
/// (`BufferDisplayPropertyTextReplacementRenderOutcome::Fallback`,
/// display_property_render.rs), which had NO coverage of any kind before this
/// pin. It is GNU-shaped rather than a compromise: `handle_display_prop`
/// returning 0 for a spec `handle_single_display_spec` will not take means the
/// covered text is simply displayed, i.e. the frame was never pushed.
///
/// Reaching it needs a degenerate spec. Every well-formed media spec resolves
/// (an image falls back to the `[img]` placeholder, see
/// [`an_unloadable_image_replacement_still_covers_its_range`]; xwidget and
/// surface specs are self-contained and take the `direct_replacement`
/// short-circuit), so the reachable case is a spec that CLASSIFIES as a string
/// replacement and then cannot be read as one: a unibyte string whose bytes are
/// not valid UTF-8, which `as_utf8_str` rejects.
///
/// TRIPWIRE — do not weaken this to "renders something". The resume is the
/// whole point: this branch is where a future producer-owned exit breaks FIRST,
/// because the producer cannot know at production time that resolution will
/// decline, so a producer that popped past the covered range on its own would
/// double-advance here (the fallback item spans the covered range and publishes
/// its own end). Asserting the covered text appears once and `g` follows once
/// is what catches that.
#[test]
fn an_unresolvable_display_replacement_declines_and_resumes_at_the_covered_end() {
    // The spec covers 1-based [4,7) — "def". Resolution declines, so the row is
    // the untouched line: "def" appears once (not dropped, not doubled) and "g"
    // follows it once (the walk resumed at E, not at the covered start).
    assert_eq!(
        display_prop_first_row_text(
            "abcdefghij\n",
            "(put-text-property 4 7 'display (unibyte-string 200 201))",
        ),
        "abcdefghij ",
        "a display spec that cannot be resolved is not a replacement: the \
         covered text displays once and the walk resumes at the covered end"
    );
}

/// A replacing `display` spec inside an OVERLAY string is honored; one inside a
/// DISPLAY string is not, however deeply the display string was reached.
///
/// GNU draws the line at `it->string_from_display_prop_p`, not at "is this a
/// string": `handle_display_prop` refuses to recurse only when the string it is
/// walking came from a `display` property (xdisp.c:5934-5942, 6334-6335), so an
/// overlay string is ordinary displayable text whose own `display` properties
/// apply, while a display string's are inert.
///
/// This engine mirrors the distinction with
/// `LispStringSourceFrame::from_display_property`, derived from
/// `LispStringSourceOrigin` — false for `OverlayString`, true for
/// `BufferDisplayReplacement` — and, crucially, hardcoded true for any frame
/// PUSHED by a replacement (`push_with_replacement_source`, display_source.rs).
/// That last part is what makes the ban transitive rather than one level deep,
/// and it is the half a reader is most likely to assume rather than check.
#[test]
fn a_replacing_display_spec_is_honored_in_an_overlay_string_but_not_below_it() {
    // Level 1: the overlay's before-string carries a `display` property whose
    // value replaces it. The overlay string is NOT from a display property, so
    // the spec applies and "S" renders as "R".
    assert_eq!(
        display_prop_first_row_text(
            "ab\n",
            "(overlay-put (make-overlay 2 3) 'before-string \
               (propertize \"S\" 'display \"R\"))",
        ),
        "aRb ",
        "an overlay string is ordinary text: its own display property applies"
    );

    // Level 2: that replacement string in turn carries a `display` property.
    // It came from a display property, so its own is inert — "R" renders as
    // itself, NOT as "Q".
    assert_eq!(
        display_prop_first_row_text(
            "ab\n",
            "(overlay-put (make-overlay 2 3) 'before-string \
               (propertize \"S\" 'display (propertize \"R\" 'display \"Q\")))",
        ),
        "aRb ",
        "a display property inside a display string is inert, even when the \
         display string was reached from an overlay string"
    );
}

/// R6: a REPLACING `display` spec beats `invisible`; a non-replacing one does
/// not.
///
/// GNU's handler order is face then display then invisible
/// (`it_props`, xdisp.c:1012-1021), and `handle_display_prop` returns
/// HANDLED_RETURN for a replacing spec (xdisp.c:5974), short-circuiting the
/// rest of the chain so `handle_invisible_prop` never runs. A non-replacing
/// spec returns HANDLED_NORMALLY, so invisibility still applies.
#[test]
fn a_replacing_display_spec_beats_invisible_and_a_non_replacing_one_does_not() {
    assert_eq!(
        display_prop_first_row_text(
            "abcdefghij\n",
            "(progn (put-text-property 4 7 'invisible t) \
                    (put-text-property 4 7 'display \"S\"))",
        ),
        "abcSghij ",
        "a replacing display spec short-circuits the handler chain before \
         handle_invisible_prop runs"
    );
    assert_eq!(
        display_prop_first_row_text(
            "abcdefghij\n",
            "(progn (put-text-property 4 7 'invisible t) \
                    (put-text-property 4 7 'display '(space-width 2)))",
        ),
        "abcghij ",
        "a non-replacing spec leaves the chain running, so the text stays \
         hidden"
    );
}

/// The first body row's glyphs, laid out with `setup` run against the
/// fixture's own Context.
fn display_prop_first_row_glyphs(
    text: &str,
    setup: &str,
) -> Vec<neomacs_display_protocol::glyph_matrix::Glyph> {
    let setup = setup.to_owned();
    let (_eval, _buf_id, _frame_id, rows, _cw, _ch) =
        layout_main_text_rows_with(text, move |eval, buf_id| {
            eval.buffer_manager_mut().set_current(buf_id);
            eval.eval_str(&setup).expect("display property setup");
        });
    rows[0].glyphs[1].clone()
}

/// R3: a `(space …)` spec stamps the COVERED BUFFER POSITION.
///
/// This is the exception that breaks the naive "replacements are string-like"
/// rule: `handle_single_display_spec` sets `it->position = start_pos` for the
/// space arm (xdisp.c:6600-6606), and `produce_stretch_glyph` recovers the
/// object from the STACK - the buffer when nothing is nested
/// (xdisp.c:32935-32943) - so the glyph carries a genuine buffer position B,
/// unlike its string sibling. The SAME `display` property is string-stamped
/// when its value is a string and buffer-stamped when it is `(space …)`.
#[test]
fn a_space_display_spec_stamps_the_covered_buffer_position() {
    let glyphs = display_prop_first_row_glyphs(
        "abcdefghij\n",
        "(put-text-property 4 6 'display '(space :width 4))",
    );
    assert_eq!(
        glyphs_logical_text(&glyphs),
        "abc    fghij ",
        "the covered [3,5) renders as 4 columns of stretch"
    );
    // One stretch glyph of 4 columns sits at index 3, between "abc" and the
    // resumed buffer text.
    assert!(
        matches!(
            glyphs[3].glyph_type,
            GlyphType::Stretch { width_cols: 4, .. }
        ),
        "expected a 4-column stretch, got {:?}",
        glyphs[3].glyph_type
    );
    assert_eq!(
        glyphs[3].legacy_charpos(),
        3,
        "the stretch stamps the COVERED START - a genuine buffer position \
         (GNU append_stretch_glyph charpos = B), not a redisplay sentinel"
    );
    assert_eq!(
        glyphs[4].legacy_charpos(),
        5,
        "the character after the stretch is the covered range's end"
    );
}

/// R7: an EMPTY display string still consumes its covered range.
///
/// GNU pushes the string and pops it in `handle_stop` rather than discarding
/// it at creation (xdisp.c:4265-4275), so the covered text is replaced by
/// nothing rather than displayed.
#[test]
fn an_empty_display_string_consumes_its_covered_range() {
    assert_eq!(
        display_prop_first_row_text("abcdefghij\n", "(put-text-property 4 7 'display \"\")"),
        "abcghij ",
        "the covered [3,6) is replaced by nothing, not rendered literally"
    );
}

/// A TAB renders as a stretch glyph, and that glyph stands for a real buffer
/// character, so it must carry that character's position.
///
/// GNU produces the tab through the same stretch machinery as a `(space …)`
/// spec and stamps `CHARPOS (it->position)` on it like any other buffer
/// glyph; a tab whose glyph reported position 0 would send every click on an
/// indented line's leading whitespace to the top of the buffer.
#[test]
fn a_tab_stretch_carries_its_own_buffer_position() {
    // The setup form is a no-op: this test is about the tab's stretch glyph,
    // not about any display property.  It used `(ignore)', which stopped
    // working on a bare `Context' when DIVERGENCES.md 152 deleted that Rust
    // subr -- `ignore' is a `defun' in subr.el, which a bare Context has not
    // loaded.  `nil' needs no function at all.
    let glyphs = display_prop_first_row_glyphs("ab\tcd\n", "nil");
    assert!(
        matches!(glyphs[2].glyph_type, GlyphType::Stretch { .. }),
        "expected the tab to render as a stretch, got {:?}",
        glyphs[2].glyph_type
    );
    assert_eq!(
        glyphs[2].legacy_charpos(),
        2,
        "the tab's stretch glyph carries the tab character's own position"
    );
}

// ---------------------------------------------------------------------------
// P5.2 pin ladder: when must the chrome format be re-evaluated?
//
// GNU's decision is extracted in tmp/p52-gnu-extraction.md. These pins state
// the behavioural contract a skip must not break, in the instrument that will
// grade the skip: `mode_line_eval_count()`, which counts `format-mode-line`
// runs for `mode-line-format` and is reset at the top of every
// `layout_frame_rust`. Counts are written as explicit goldens, never derived
// from the frame under test.
// ---------------------------------------------------------------------------

/// Read the rendered mode-line text of the frame's last display state.
fn rendered_mode_line_text(engine: &LayoutEngine) -> String {
    engine
        .last_frame_display_state
        .as_ref()
        .map(|state| {
            state
                .window_matrices
                .iter()
                .flat_map(|wm| wm.matrix.rows.iter())
                .filter(|row| row.role == GlyphRowRole::ModeLine && row.enabled)
                .flat_map(|row| row.glyphs[1].iter())
                .filter_map(|g| match &g.glyph_type {
                    neomacs_display_protocol::glyph_matrix::GlyphType::Char { ch } => Some(*ch),
                    _ => None,
                })
                .collect::<String>()
        })
        .unwrap_or_default()
}

/// CONTRACT: an edit to the buffer re-evaluates the mode line. GNU reaches
/// this through `bset_redisplay` + the modified-star flip
/// (xdisp.c:17487-17488) and, once `redisplay_window` runs with
/// `line-number-mode` on, through `w->base_line_pos > 0` (xdisp.c:21414).
/// `%l`/`%p` honesty depends on it, so this must stay green after any skip.
#[test]
fn p52_buffer_modification_re_evaluates_the_mode_line() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("ML"));
        // The harness fills the buffer by inserting, which leaves it modified.
        // Start unmodified so the edit below is the modified-star flip this
        // contract cites (an edit on an already-starred buffer is the settled
        // case pinned by `p52_in_line_edit_reuses_chrome_only_after_the_modified_star_has_settled`).
        buf.set_modified(false);
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .insert("x");
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        1,
        "an edited buffer must re-evaluate mode-line-format exactly once"
    );
}

/// CONTRACT: `setq-local mode-line-format` re-evaluates, and the new format
/// reaches the screen. GNU covers this with an `add-variable-watcher` on
/// `mode-line-format` calling `set-buffer-redisplay`
/// (lisp/frame.el:3752-3779 -> xdisp.c:922-931), which sets both
/// `update_mode_lines` and `prevent_redisplay_optimizations_p`.
///
/// P5.2(b) note: the CHANGE is made through Lisp, deliberately. The watcher
/// this pin cites is a property of the SET path, so writing the buffer slot
/// directly (as this pin did before the skip existed) exercises a path no
/// production caller takes — grep confirms nothing in Rust sets these three
/// buffer-locals — and would assert that redisplay notices a change nothing
/// announced. The window-parameter override, which is the one real way to
/// change a window's chrome format without touching the buffer, dirties the
/// window in `builtin_set_window_parameter`.
#[test]
fn p52_setting_mode_line_format_re_evaluates_and_reaches_the_screen() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("BEFORE"));
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);
    assert!(rendered_mode_line_text(&engine).contains("BEFORE"));

    // `setq-local` is a subr.el macro and this Context is bare, so use what it
    // expands to. The point is that the value travels the production set
    // chokepoint (which is where the chrome watcher lives), not which surface
    // syntax gets it there.
    eval.eval_str("(set (make-local-variable 'mode-line-format) \"AFTER\")")
        .expect("eval");
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        1,
        "a changed mode-line-format must be re-evaluated"
    );
    let text = rendered_mode_line_text(&engine);
    assert!(
        text.contains("AFTER") && !text.contains("BEFORE"),
        "the new mode-line-format must reach the screen, got {text:?}"
    );
}

/// CONTRACT: `force-mode-line-update` re-evaluates. This is the escape hatch
/// that makes every skip legal: GNU's `Fforce_mode_line_update` (buffer.c)
/// sets `bset_update_mode_line` AND `prevent_redisplay_optimizations_p`, the
/// second of which is what disqualifies the one-line optimization that
/// otherwise skips chrome entirely (xdisp.c:17575-17577).
#[test]
fn p52_force_mode_line_update_re_evaluates_the_mode_line() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("ML"));
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    eval.eval_str("(force-mode-line-update)").expect("eval");
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        1,
        "force-mode-line-update must re-evaluate mode-line-format"
    );
}

/// CONTRACT (the flag half): each event GNU answers with
/// `bset_update_mode_line` / `wset_update_mode_line` must raise neomacs's
/// chrome dirty flag. The trigger inventory is §2 of
/// tmp/p52-gnu-extraction.md; this pins one case per GNU call site so the
/// skip that will consult the flag inherits a checked invalidation set
/// rather than an assumed one.
///
/// The flag is cleared at the end of every accepted layout, so each case
/// starts from a laid-out frame and asserts the transition.
#[test]
fn p52_chrome_dirty_flag_is_raised_by_each_gnu_trigger() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);

    // force-mode-line-update — GNU Fforce_mode_line_update (buffer.c).
    {
        let (mut eval, frame_id, _buf, _sel) = incr_editing_frame(&text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);
        assert!(
            !eval.chrome_dirty().is_any_dirty(),
            "layout clears the chrome dirty flag"
        );
        eval.eval_str("(force-mode-line-update)").expect("eval");
        assert!(
            eval.chrome_dirty().is_any_dirty(),
            "force-mode-line-update must raise the chrome dirty flag"
        );
    }

    // Setting mode-line-format — GNU's add-variable-watcher on the three
    // chrome formats (lisp/frame.el:3752-3779 -> xdisp.c:922-931).
    for var in ["mode-line-format", "header-line-format", "tab-line-format"] {
        let (mut eval, frame_id, _buf, _sel) = incr_editing_frame(&text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);
        assert!(!eval.chrome_dirty().is_any_dirty());
        eval.eval_str(&format!("(setq {var} \"X\")")).expect("eval");
        assert!(
            eval.chrome_dirty().is_any_dirty(),
            "setting {var} must raise the chrome dirty flag"
        );
    }

    // rename-buffer — GNU buffer.c:1718, the `%b` case.
    {
        let (mut eval, frame_id, _buf, _sel) = incr_editing_frame(&text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);
        assert!(!eval.chrome_dirty().is_any_dirty());
        eval.eval_str("(rename-buffer \"renamed-for-p52\")")
            .expect("eval");
        assert!(
            eval.chrome_dirty().is_any_dirty(),
            "rename-buffer must raise the chrome dirty flag"
        );
    }

    // kill-all-local-variables — GNU buffer.c:3046, the major-mode chokepoint.
    {
        let (mut eval, frame_id, _buf, _sel) = incr_editing_frame(&text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);
        assert!(!eval.chrome_dirty().is_any_dirty());
        eval.eval_str("(kill-all-local-variables)").expect("eval");
        assert!(
            eval.chrome_dirty().is_any_dirty(),
            "kill-all-local-variables must raise the chrome dirty flag"
        );
    }

    // set-window-buffer — GNU window.c:4383. Window-scoped.
    {
        let (mut eval, frame_id, buf_id, selected) = incr_editing_frame(&text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);
        assert!(!eval.chrome_dirty().is_any_dirty());
        let other = eval.buffer_manager_mut().create_buffer("p52-other-buffer");
        assert_ne!(other, buf_id);
        eval.eval_str("(set-window-buffer (selected-window) \"p52-other-buffer\")")
            .expect("eval");
        assert!(
            eval.chrome_dirty().is_dirty(selected),
            "set-window-buffer must dirty the window that changed buffers"
        );
    }

    // narrow-to-region / widen — GNU carries these through clip_changed
    // (xdisp.c:20471-20475 and the escalation at :17498). `%n` and `%p`.
    for form in [
        "(narrow-to-region 1 20)",
        "(progn (narrow-to-region 1 20) (widen))",
    ] {
        let (mut eval, frame_id, _buf, _sel) = incr_editing_frame(&text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);
        assert!(!eval.chrome_dirty().is_any_dirty());
        eval.eval_str(form).expect("eval");
        assert!(
            eval.chrome_dirty().is_any_dirty(),
            "{form} must raise the chrome dirty flag"
        );
    }

    // set-window-start — GNU window.c:1969. Window-scoped, not buffer-scoped:
    // this is the one case that must dirty a NAMED window.
    {
        let (mut eval, frame_id, _buf, selected) = incr_editing_frame(&text, 800, 600);
        let mut engine = LayoutEngine::new();
        engine.layout_frame_rust(&mut eval, frame_id);
        assert!(!eval.chrome_dirty().is_any_dirty());
        eval.eval_str("(set-window-start (selected-window) 20)")
            .expect("eval");
        assert!(
            eval.chrome_dirty().is_dirty(selected),
            "set-window-start must dirty the window whose start moved"
        );
    }
}

/// CONTRACT: changing the selected window re-evaluates the mode line of BOTH
/// windows, because the mode-line face flips active/inactive and the face is
/// chosen from the real selected window
/// (`CURRENT_MODE_LINE_ACTIVE_FACE_ID_3`, dispextern.h:1541-1549). GNU gets
/// there through select_window -> wset_redisplay -> windows_or_buffers_changed
/// -> update_mode_lines (xdisp.c:17545-17550), which is frame-wide, so the
/// golden is 2 evals for a two-window frame, not 1.
#[test]
fn p52_selected_window_change_re_evaluates_both_windows_mode_lines() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("ML"));
    }
    let right = eval
        .frame_manager_mut()
        .split_window(
            frame_id,
            selected,
            neovm_core::window::SplitDirection::Horizontal,
            buf_id,
            None,
            neovm_core::window::SplitPlacement::AfterTarget,
        )
        .expect("split window");
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);
    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        2,
        "a two-window frame evaluates mode-line-format once per window"
    );

    eval.frame_manager_mut()
        .get_mut(frame_id)
        .expect("frame")
        .selected_window = right;
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        2,
        "a selected-window change must re-evaluate BOTH windows' mode lines \
         (the active/inactive face flips on both)"
    );
}

/// GNU realizes the selected window's mode-line cache slot from
/// `mode-line-active`, not from its `mode-line` parent
/// (`realize_basic_faces`, xfaces.c; `display_mode_lines`, xdisp.c).  This is
/// observable even when both rows carry the right numeric basic-face ids: the
/// selected row must receive the active face's explicit decoration and font
/// overrides before its height is measured.
#[test]
fn selected_mode_line_realizes_active_face_and_matches_inactive_metrics() {
    use neomacs_display_protocol::face::FaceAttributes;
    use neovm_core::face::{Color, Face, FaceHeight};

    let (mut eval, frame_id, buf_id, selected) = incr_editing_frame("body\n", 800, 240);
    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.set_buffer_local("mode-line-format", Value::string("ML"));
    }

    // Deliberately make the parent visibly and metrically incompatible with
    // both leaf faces.  This is the minimal version of the user's theme:
    // selecting the parent leaks an overline and shrinks only the active row.
    {
        let table = eval.face_table_mut();

        let mut parent = Face::new("mode-line");
        parent.foreground = Some(Color::rgb(0xff, 0x00, 0x00));
        parent.height = Some(FaceHeight::Absolute(80));
        parent.overline = Some(true);
        table.define("mode-line", parent);

        let mut active = Face::new("mode-line-active");
        active.inherit = Some(Value::symbol("mode-line"));
        active.foreground = Some(Color::rgb(0xff, 0xff, 0xff));
        active.height = Some(FaceHeight::Absolute(140));
        active.overline = Some(false);
        table.define("mode-line-active", active);

        let mut inactive = Face::new("mode-line-inactive");
        inactive.inherit = Some(Value::symbol("mode-line"));
        inactive.foreground = Some(Color::rgb(0x80, 0x80, 0x80));
        inactive.height = Some(FaceHeight::Absolute(140));
        inactive.overline = Some(false);
        table.define("mode-line-inactive", inactive);
    }

    let inactive = eval
        .frame_manager_mut()
        .split_window(
            frame_id,
            selected,
            neovm_core::window::SplitDirection::Horizontal,
            buf_id,
            None,
            neovm_core::window::SplitPlacement::AfterTarget,
        )
        .expect("split window");
    {
        let frames = eval.frame_manager_mut();
        frames
            .get_mut(frame_id)
            .expect("frame")
            .set_window_system(Some(Value::symbol("neo")));
        for window_id in [selected, inactive] {
            frames.set_window_parameter(
                window_id,
                Value::symbol("mode-line-format"),
                Value::string("ML"),
            );
        }
    }

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("frame display state");

    let mode_line = |window_id: neovm_core::window::WindowId| {
        let entry = state
            .window_matrices
            .iter()
            .find(|entry| entry.window_id.get() == window_id.0 as i64)
            .unwrap_or_else(|| panic!("window {window_id:?} matrix"));
        entry
            .matrix
            .rows
            .iter()
            .find(|row| row.enabled && row.role == GlyphRowRole::ModeLine)
            .unwrap_or_else(|| {
                panic!(
                    "window {window_id:?} mode-line row; selected={} rows={:?}",
                    entry.selected,
                    entry
                        .matrix
                        .rows
                        .iter()
                        .map(|row| (row.enabled, row.role, row.height_px))
                        .collect::<Vec<_>>()
                )
            })
    };
    let active_row = mode_line(selected);
    let inactive_row = mode_line(inactive);
    let active_glyph = active_row.glyphs[GlyphArea::Text.index()]
        .iter()
        .find(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: 'M' }))
        .expect("active mode-line text glyph");
    let active_face = state
        .faces
        .get(&active_glyph.face_id)
        .expect("published active mode-line face");

    assert_eq!(
        active_face.lisp_name.as_deref(),
        Some("mode-line-active"),
        "the selected row must realize GNU's mode-line-active face"
    );
    assert!(
        !active_face.attributes.contains(FaceAttributes::OVERLINE),
        "mode-line-active's explicit nil must suppress its parent's overline"
    );
    assert_eq!(
        active_row.height_px, inactive_row.height_px,
        "equal active/inactive face heights must produce equal mode-line rows"
    );
}

#[test]
fn buffer_owned_mode_line_string_remaps_its_named_face() {
    use neomacs_display_protocol::types::Color;

    let (mut eval, frame_id, buf_id, selected) = incr_editing_frame("body\n", 800, 240);
    let mode_line = Value::string_with_text_properties(
        "M",
        vec![StringTextPropertyRun {
            start: 0,
            end: 1,
            plist: Value::list(vec![
                Value::symbol("face"),
                Value::symbol("mode-line-remap-probe"),
            ]),
        }],
    );
    {
        let buffer = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buffer.set_buffer_local("mode-line-format", mode_line);
        buffer.set_buffer_local(
            "face-remapping-alist",
            Value::list(vec![Value::list(vec![
                Value::symbol("mode-line-remap-probe"),
                Value::list(vec![Value::keyword("foreground"), Value::string("#ff0000")]),
                Value::symbol("mode-line-remap-probe"),
            ])]),
        );
    }
    assert!(eval.frame_manager_mut().select_frame(frame_id));
    let face_results = eval.eval_str_each(
        "(internal-make-lisp-face 'mode-line-remap-probe)
         (internal-set-lisp-face-attribute
          'mode-line-remap-probe :foreground \"#00ff00\" (selected-frame))",
    );
    assert!(
        face_results.iter().all(Result::is_ok),
        "install mode-line probe face, got {face_results:?}"
    );

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("frame display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected.0 as i64)
        .expect("selected window matrix");
    let mode_line_row = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::ModeLine)
        .expect("mode-line row");
    let glyph = mode_line_row.glyphs[GlyphArea::Text.index()]
        .iter()
        .find(|glyph| matches!(glyph.glyph_type, GlyphType::Char { ch: 'M' }))
        .expect("mode-line probe glyph");
    let face = state
        .faces
        .get(&glyph.face_id)
        .expect("mode-line probe face");
    assert_eq!(
        face.foreground,
        Color::from_pixel(0x00ff0000),
        "buffer-owned mode-line string must apply the named face's buffer-local remapping"
    );
}

/// GNU `lookup_named_face` starts an inherited basic face from the frame's
/// unremapped default face (xfaces.c), so buffer-local `default` scaling affects
/// body text but not a mode line that has no direct remapping.  Treemacs relies
/// on exactly this separation: `treemacs-text-scale` remaps only `default`.
#[test]
fn buffer_default_text_scale_does_not_shrink_inactive_mode_line() {
    use neovm_core::face::{Face, FaceHeight};

    let (mut eval, frame_id, main_buffer, selected) = incr_editing_frame("main body\n", 800, 240);
    realize_test_gui_frame(&mut eval, frame_id);
    let side_buffer = eval
        .buffer_manager_mut()
        .create_buffer("*treemacs-like-scaled-buffer*");
    {
        let buffer = eval
            .buffer_manager_mut()
            .get_mut(main_buffer)
            .expect("main buffer");
        buffer.set_buffer_local("mode-line-format", Value::string("MAIN"));
    }
    {
        let buffer = eval
            .buffer_manager_mut()
            .get_mut(side_buffer)
            .expect("scaled side buffer");
        buffer.insert("scaled body\n");
        buffer.set_buffer_local("mode-line-format", Value::string("TREEMACS"));
        buffer.set_buffer_local(
            "face-remapping-alist",
            Value::list(vec![Value::list(vec![
                Value::symbol("default"),
                Value::list(vec![Value::keyword("height"), Value::make_float(0.7)]),
                Value::symbol("default"),
            ])]),
        );
    }
    {
        let table = eval.face_table_mut();

        let mut default = Face::new("default");
        default.height = Some(FaceHeight::Absolute(140));
        table.define("default", default);

        let mut mode_line = Face::new("mode-line");
        mode_line.height = Some(FaceHeight::Relative(1.0));
        table.define("mode-line", mode_line);

        let mut active = Face::new("mode-line-active");
        active.inherit = Some(Value::symbol("mode-line"));
        table.define("mode-line-active", active);

        let mut inactive = Face::new("mode-line-inactive");
        inactive.inherit = Some(Value::symbol("mode-line"));
        table.define("mode-line-inactive", inactive);
    }

    let side = eval
        .frame_manager_mut()
        .split_window(
            frame_id,
            selected,
            neovm_core::window::SplitDirection::Horizontal,
            side_buffer,
            None,
            neovm_core::window::SplitPlacement::AfterTarget,
        )
        .expect("split window");
    {
        let frames = eval.frame_manager_mut();
        frames
            .get_mut(frame_id)
            .expect("frame")
            .set_window_system(Some(Value::symbol("neo")));
        for (window_id, label) in [(selected, "MAIN"), (side, "TREEMACS")] {
            frames.set_window_parameter(
                window_id,
                Value::symbol("mode-line-format"),
                Value::string(label),
            );
        }
    }

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("frame display state");
    let window_rows = |window_id: neovm_core::window::WindowId| {
        state
            .window_matrices
            .iter()
            .find(|entry| entry.window_id.get() == window_id.0 as i64)
            .unwrap_or_else(|| panic!("window {window_id:?} matrix"))
            .matrix
            .rows
            .iter()
            .filter(|row| row.enabled)
            .collect::<Vec<_>>()
    };
    let main_rows = window_rows(selected);
    let side_rows = window_rows(side);
    fn row_for_role<'a>(rows: &'a [&MatrixRow], role: GlyphRowRole) -> &'a MatrixRow {
        rows.iter()
            .copied()
            .find(|row| row.role == role)
            .unwrap_or_else(|| panic!("{role:?} row in {rows:?}"))
    }
    fn body_text_row<'a>(rows: &'a [&MatrixRow]) -> &'a MatrixRow {
        rows.iter()
            .copied()
            .find(|row| row.role == GlyphRowRole::Text && row.displays_text)
            .unwrap_or_else(|| panic!("body text row in {rows:?}"))
    }
    let main_body = body_text_row(&main_rows);
    let side_body = body_text_row(&side_rows);
    let main_mode_line = row_for_role(&main_rows, GlyphRowRole::ModeLine);
    let side_mode_line = row_for_role(&side_rows, GlyphRowRole::ModeLine);

    assert!(
        side_body.height_px < main_body.height_px,
        "precondition: the side buffer's default remap must shrink its body text; main={main_body:?} side={side_body:?}"
    );
    assert_eq!(
        side_mode_line.height_px, main_mode_line.height_px,
        "a default-only buffer remap must not scale the inactive mode line"
    );
}

/// CONTRACT: the header line and the tab line share the mode line's contract.
/// GNU regenerates all three in one `display_mode_lines` call
/// (xdisp.c:28027+), so a chrome skip is per window, never per chrome kind —
/// these counters must move together with `mode_line_eval_count`.
#[test]
fn p52_header_and_tab_lines_are_evaluated_with_the_mode_line() {
    use crate::display_status_line::{
        header_line_eval_count, mode_line_eval_count, tab_line_eval_count,
    };
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("ML"));
        buf.set_buffer_local("header-line-format", Value::string("HL"));
        buf.set_buffer_local("tab-line-format", Value::string("TL"));
        // Start unmodified so the edit below is the modified-star flip that
        // regenerates all three chrome lines (see the mode-line contract).
        buf.set_modified(false);
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .insert("x");
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(mode_line_eval_count(), 1, "mode line evaluated once");
    assert_eq!(header_line_eval_count(), 1, "header line evaluated once");
    assert_eq!(tab_line_eval_count(), 1, "tab line evaluated once");
}

/// Lisp entered from redisplay may write its own bookkeeping window
/// parameters on every evaluation: `tab-line-format` stores `tab-line-cache`
/// and, through `tab-line-tabs-fixed-window-buffers`, `tab-line-buffers`.
/// Those writes bump the window-parameter generation, which the BODY
/// boundary must keep watching (a `:window` face filter may read any
/// parameter).  Chrome runs after GNU has completed the body, so the
/// WindowChrome boundary tolerates the bump instead of invalidating the
/// attempt; without that tolerance every attempt that evaluated a tab line
/// invalidated itself and the frame was rejected once the retry budget ran
/// out — `neomacs -nw` froze on its last accepted frame the moment
/// `global-tab-line-mode` was enabled.
#[test]
fn tab_line_that_rewrites_its_bookkeeping_parameter_converges() {
    let text = "body line\n".repeat(4);
    let (mut eval, frame_id, buf_id, selected) = incr_editing_frame(&text, 640, 160);
    let format = Value::list(vec![Value::list(vec![
        Value::symbol(":eval"),
        Value::list(vec![
            Value::symbol("progn"),
            Value::list(vec![
                Value::symbol("set-window-parameter"),
                Value::NIL,
                Value::list(vec![
                    Value::symbol("quote"),
                    Value::symbol("tab-line-buffers"),
                ]),
                Value::list(vec![Value::symbol("list"), Value::string("tick")]),
            ]),
            Value::string("TAB"),
        ]),
    ])]);
    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .set_buffer_local("tab-line-format", format);

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("the frame converges instead of being rejected");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| entry.window_id.get() == selected.0 as i64)
        .expect("selected window matrix");
    let tab_line = entry
        .matrix
        .rows
        .iter()
        .find(|row| row.enabled && row.role == GlyphRowRole::TabLine)
        .expect("tab-line row");
    assert_eq!(row_text(&tab_line.glyphs[GlyphArea::Text.index()]), "TAB");
    assert_eq!(
        crate::display_status_line::tab_line_eval_count(),
        1,
        "the bookkeeping write did not force a layout retry"
    );
}

/// WORK LIST (expected RED today): a redisplay that only moved point inside
/// an unchanged buffer must NOT re-evaluate the mode line. This is GNU's
/// one-line optimization (xdisp.c:17572-17726): it re-displays the cursor's
/// glyph row and `goto update`, never entering `redisplay_window`, so
/// `display_mode_lines` never runs — even with `%l` in the format. neomacs
/// classifies the same redisplay as cursor-only but re-walks chrome anyway
/// (buffer_source/render_plan.rs:706-713).
#[test]
fn p52_cursor_only_redisplay_does_not_re_evaluate_the_mode_line() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("ML"));
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(10));
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        engine.last_layout_stats().cursor_only_windows,
        1,
        "precondition: this redisplay is classified cursor-only"
    );
    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        0,
        "a cursor-only redisplay must not re-evaluate mode-line-format (GNU's \
         one-line optimization never reaches display_mode_lines)"
    );
}

/// CONTRACT (RED before (b)'s precondition (i), and it must STAY red-then-green
/// for the right reason): a cursor-only redisplay that moves point to ANOTHER
/// LINE must re-evaluate the mode line whenever `%l` is displayed.
///
/// This is the pin that separates GNU's actual skip from the flags-only version
/// of it. GNU's one-line optimization is entered only while point stays on the
/// recorded line — `PT >= CHARPOS (tlbufpos) && PT <= Z - CHARPOS (tlendpos)`,
/// xdisp.c:17591-17593 — and when point leaves that line control reaches the
/// `cancel:` label whose comment is literally "Text changed drastically or point
/// moved off of line" (xdisp.c:17813), after which a full `redisplay_window`
/// regenerates the mode line. That structural restriction is the ENTIRE reason
/// `%l` cannot go stale while GNU skips.
///
/// neomacs's cursor-only path has no such restriction on its own:
/// `RetainedWindowKey::cursor_only_eligible` compares every field EXCEPT
/// `point` (incremental_layout.rs), so point may move to any retained row. A
/// skip gated on the chrome dirty flags alone would therefore freeze `%l` — and
/// `%l` is in OUR default mode line, not just GNU's: `line-number-mode` is
/// `:init-value t` (lisp/simple.el:9380) and `mode-line-position-line-format` is
/// `'(" L%l")` (lisp/bindings.el:687).
///
/// Note the sibling pin `p52_cursor_only_redisplay_does_not_re_evaluate_the_mode_line`
/// moves point WITHIN line 1 and so goes green on the flags alone; this one is
/// the reason precondition (i) (point remains in the same retained row) exists.
#[test]
fn p52_cursor_only_motion_to_another_line_re_evaluates_the_mode_line() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        // `%l` displayed, nothing else — the format under test is the line
        // number itself, so a stale eval is directly observable.
        buf.set_buffer_local("mode-line-format", Value::string("L%l"));
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);
    assert!(
        rendered_mode_line_text(&engine).contains("L1"),
        "precondition: the first layout displays line 1, got {:?}",
        rendered_mode_line_text(&engine)
    );

    // Line 1 is 24 bytes ("(defun f (a b) (+ a b))\n"), so byte 30 is on line 2.
    // Point moves ONLY — no edit, no scroll, no tick movement.
    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(30));
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        engine.last_layout_stats().cursor_only_windows,
        1,
        "precondition: this redisplay is still classified cursor-only"
    );
    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        1,
        "point crossing a line boundary must re-evaluate mode-line-format: GNU \
         declines its one-line optimization once PT leaves the recorded line \
         (xdisp.c:17591-17593, cancel: at :17813), which is what keeps %l honest"
    );
    assert!(
        rendered_mode_line_text(&engine).contains("L2"),
        "the re-evaluated mode line must show the NEW line number, got {:?}",
        rendered_mode_line_text(&engine)
    );
}

/// CONTRACT: a replay that SKIPS the chrome walk must still publish the chrome
/// rows' faces into this frame's output.
///
/// The chrome render does three things beyond emitting glyph rows, and face
/// publication is the one with no other owner: `install_measured_window_display_row`
/// calls `install_faces` -> `publish_output_face` for every face the chrome row
/// resolved (display_rendered_row_output_install.rs). Re-installing a retained
/// chrome row verbatim moves the GLYPHS but not that publication, so the row's
/// `FaceId`s would dangle in `FrameDisplayState.faces` and the renderer would
/// draw the mode line with whatever those ids happen to mean this frame.
///
/// The fix is to extend the replay's `retained_face_ids()` — which today
/// iterates body rows only — so Phase A admits the chrome rows' ids before
/// install. This pin is the detector for that extension; without it a
/// face-install bug is invisible to every text-content assertion, because the
/// characters are all correct.
#[test]
fn p52_skipped_chrome_replay_still_publishes_the_chrome_faces() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("ML"));
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    // A same-line cursor move: the redisplay the skip is built for.
    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(10));
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("frame display state");
    let mode_line_face_ids: Vec<_> = state
        .window_matrices
        .iter()
        .flat_map(|wm| wm.matrix.rows.iter())
        .filter(|row| row.role == GlyphRowRole::ModeLine && row.enabled)
        .flat_map(|row| row.referenced_face_ids())
        .collect();
    assert!(
        !mode_line_face_ids.is_empty(),
        "precondition: the mode-line row references at least one face"
    );
    for face_id in mode_line_face_ids {
        assert!(
            state.faces.contains_key(&face_id),
            "chrome face {face_id:?} referenced by the mode-line row is missing \
             from this frame's published face table — a skipped chrome walk must \
             still admit the retained chrome rows' faces"
        );
    }
}

/// CONTRACT: an in-line edit stops re-evaluating the mode line, but only once
/// GNU's modified-star has settled — the pin that covers the EDIT replay, which
/// is where the typing workload actually lives.
///
/// Two redisplays, two different answers, both GNU's:
///
/// 1. The FIRST edit to a clean buffer flips `%*` / `%+`. GNU has no trigger for
///    this; `redisplay_internal` compares `(SAVE_MODIFF < MODIFF) !=
///    w->last_had_star` per window per redisplay (xdisp.c:17487-17488) and sets
///    `w->update_mode_line`, disqualifying the one-line optimization. So this
///    redisplay must re-evaluate.
/// 2. The SECOND edit on the same line changes nothing the chrome shows: the
///    star is already set, no line boundary moved, point stayed in its row. This
///    is exactly GNU's optimization-1 case, which never enters
///    `redisplay_window` and so never reaches `display_mode_lines`.
///
/// The edit is placed mid-screen deliberately. An edit on the window's FIRST
/// visible row has no rows above to reuse, so `edit_replay` declines
/// (`first_dirty == 0`) and the window takes the full path, which always walks
/// chrome — a pin written at the buffer start would pass no matter what the
/// skip does.
#[test]
fn p52_in_line_edit_reuses_chrome_only_after_the_modified_star_has_settled() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let edit_at = 10 * 24 + 5;
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("ML"));
        // Point must already sit on the row about to be edited BEFORE the
        // warm-up layout. Otherwise the first edit is refused by the
        // cursor-row clause rather than by the star, and the star precondition
        // goes untested (a deliberate-mutation run proved exactly that).
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        // ...and the buffer must be CLEAN, or there is no star to flip: the
        // harness fills the buffer by inserting, which leaves it modified.
        // Set the flag directly rather than through `set-buffer-modified-p`,
        // whose GNU-faithful tail calls `force-mode-line-update` and would
        // make the dirty flag, not the star, the thing under test.
        buf.set_modified(false);
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("x");
    }
    engine.layout_frame_rust(&mut eval, frame_id);
    assert_eq!(
        engine.last_layout_stats().edit_windows,
        1,
        "precondition: the first edit takes the localized-edit fast path"
    );
    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        1,
        "the modified-star flip must re-evaluate the mode line (GNU \
         xdisp.c:17487-17488 sets w->update_mode_line on the flip)"
    );
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.insert("y");
    }
    engine.layout_frame_rust(&mut eval, frame_id);
    assert_eq!(
        engine.last_layout_stats().edit_windows,
        1,
        "precondition: the second edit also takes the localized-edit fast path"
    );
    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        0,
        "a second in-line edit must NOT re-evaluate the mode line: nothing the \
         chrome displays changed, which is GNU's one-line optimization \
         (xdisp.c:17572-17726, never reaches display_mode_lines)"
    );
}

/// CONTRACT: chrome that displays a COLUMN is never reused.
///
/// `%c` is the one point-dependent construct the same-screen-row precondition
/// does not pin — point moving within a row changes the column while the row is
/// unchanged. GNU refuses in exactly this case, via `mode_line_update_needed`
/// (xdisp.c:13831-13837) setting `w->update_mode_line`. We refuse on the mere
/// PRESENCE of the spec rather than comparing its value, which is stricter than
/// GNU and free in the default configuration (`column-number-mode` is off,
/// lisp/simple.el:9387); comparing values is the later relaxation.
#[test]
fn p52_chrome_displaying_a_column_is_never_reused() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let edit_at = 10 * 24 + 5;
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("C%c"));
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    // Two in-line edits. The second is the one a column-free format would skip
    // (see p52_in_line_edit_reuses_chrome_only_after_the_modified_star_has_settled);
    // with %c displayed, BOTH must re-evaluate.
    for step in ["x", "y"] {
        eval.buffer_manager_mut()
            .get_mut(buf_id)
            .expect("buffer")
            .insert(step);
        engine.layout_frame_rust(&mut eval, frame_id);
        assert_eq!(
            engine.last_layout_stats().edit_windows,
            1,
            "precondition: edit {step:?} takes the localized-edit fast path"
        );
        assert_eq!(
            crate::display_status_line::mode_line_eval_count(),
            1,
            "chrome displaying %c must be re-evaluated on every edit, including \
             {step:?} — the column changes while the screen row does not"
        );
        activate_last_engine_presentation(&mut eval, &engine, frame_id);
    }
}

/// CONTRACT: a genuine SCROLL re-evaluates the mode line.
///
/// This is P5.2(b)'s answer to the handoff's open scroll question, and it is
/// enforced structurally rather than by trusting a trigger to have fired:
/// `%p` is computed from window-start and window-end (GNU xdisp.c:29406), so
/// chrome whose visible region moved is stale by definition. The reuse
/// predicate therefore requires `dvpos == 0` AND an unchanged window-start,
/// which no scroll replay can satisfy. GNU agrees from the other side — every
/// scroll command calls `wset_update_mode_line` (window.c:6279, 6418, 6603,
/// 6864) — but we do not depend on the internal scroll path routing through the
/// `set-window-start` builtin that P5.2(a) wired.
#[test]
fn p52_scroll_re_evaluates_the_mode_line() {
    let line = "(defun f (a b) (+ a b))\n";
    let text = line.repeat(80);
    let new_window_start = 5 * line.len() as i64 + 1;
    let point_byte = 7 * line.len();

    let (mut eval, frame_id, buf_id, win) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("ML"));
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    scroll_window_to(
        &mut eval,
        frame_id,
        win,
        buf_id,
        new_window_start,
        point_byte,
    );
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        engine.last_layout_stats().scroll_windows,
        1,
        "precondition: this redisplay takes the pure-scroll fast path"
    );
    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        1,
        "a scroll moves the visible region, so %p may have changed: chrome must \
         be regenerated even though the buffer text did not change"
    );
}

/// CONTRACT: an edit that adds a LINE re-evaluates the mode line.
///
/// GNU's one-line optimization requires all text outside the cursor's line to
/// be unchanged (`text_outside_line_unchanged_p`, xdisp.c:17604). An inserted
/// newline renumbers every line below it, so `%l` for any later point — and the
/// line count itself — moves. The reuse predicate refuses whenever the edit
/// spans a newline or the walk regenerates more than one row.
#[test]
fn p52_edit_that_adds_a_line_re_evaluates_the_mode_line() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let edit_at = 10 * 24 + 5;
    let (mut eval, frame_id, buf_id, _selected) = incr_editing_frame(&text, 800, 600);
    {
        let buf = eval.buffer_manager_mut().get_mut(buf_id).expect("buffer");
        buf.set_buffer_local("mode-line-format", Value::string("L%l"));
        buf.goto_emacs_byte_pos(neovm_core::buffer::EmacsBytePos::new(edit_at));
        // Modified before the warm-up layout, so the star has already settled
        // and this pin isolates the line-structure clause.
        buf.insert("x");
    }
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    activate_last_engine_presentation(&mut eval, &engine, frame_id);

    eval.buffer_manager_mut()
        .get_mut(buf_id)
        .expect("buffer")
        .insert("\nnew line");
    engine.layout_frame_rust(&mut eval, frame_id);

    assert_eq!(
        crate::display_status_line::mode_line_eval_count(),
        1,
        "an edit that inserts a newline changes the line structure, so the mode \
         line must be regenerated (GNU text_outside_line_unchanged_p)"
    );
}

/// CONTRACT: `widen` on an ALREADY-WIDE buffer must not dirty chrome.
///
/// GNU sets `clip_changed` only when the bounds actually move — the assignment
/// sits inside `if (BEGV != s || ZV != e)` (editfns.c:2990), and the
/// `narrow-to-region` side is guarded the same way (:3104, :3121). Porting it
/// unconditionally looks conservative and is not: font-lock wraps its work in
/// `save-restriction` + `widen`, so a no-op widen runs about twice per
/// keystroke. Measured on the tty-typing fixture before this guard existed:
/// 440 chrome-dirty marks over 200 keystrokes, chrome left permanently dirty,
/// and a chrome skip rate of exactly zero — the whole of P5.2's win silently
/// disabled by a trigger that was too eager rather than missing.
#[test]
fn p52_widening_an_already_wide_buffer_does_not_dirty_chrome() {
    let text = "(defun f (a b) (+ a b))\n".repeat(40);
    let (mut eval, frame_id, _buf, _selected) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    assert!(!eval.chrome_dirty().is_any_dirty(), "layout acknowledges");

    eval.eval_str("(widen)").expect("eval");
    assert!(
        !eval.chrome_dirty().is_any_dirty(),
        "widening an already-wide buffer changes no bound, so it must not \
         dirty chrome (GNU editfns.c:2990 guards clip_changed the same way)"
    );

    // The guard must not cost the real case: a narrowing still dirties, and so
    // does the widen that undoes it.
    eval.eval_str("(narrow-to-region 1 20)").expect("eval");
    assert!(
        eval.chrome_dirty().is_any_dirty(),
        "a real narrowing must dirty chrome"
    );
    engine.layout_frame_rust(&mut eval, frame_id);
    assert!(!eval.chrome_dirty().is_any_dirty(), "layout acknowledges");
    eval.eval_str("(widen)").expect("eval");
    assert!(
        eval.chrome_dirty().is_any_dirty(),
        "the widen that undoes a narrowing moves the bounds, so it must dirty"
    );
}

/// GNU runs `window-scroll-functions` from redisplay itself, not only from
/// `set-window-buffer`.
///
/// `redisplay_window` calls `run_window_scroll_functions` (src/xdisp.c:19222)
/// at every site where it commits a window start it did not simply inherit:
/// the `w->force_start` branch (src/xdisp.c:20728), the `try_scrolling` result
/// (src/xdisp.c:19645), and the recenter fallback (src/xdisp.c:21227). A
/// redisplay that keeps the start it was handed reaches none of those sites
/// and must stay silent.
#[test]
fn redisplay_runs_window_scroll_functions_when_it_commits_a_start() {
    let text = "line of scroll fixture text\n".repeat(200);
    let (mut eval, frame_id, _buf, selected) = incr_editing_frame(&text, 800, 600);
    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    eval.eval_str(
        "(progn (setq neomacs-wsf-log nil)
                (setq window-scroll-functions
                      (list (lambda (window start)
                              (setq neomacs-wsf-log
                                    (cons (list window start) neomacs-wsf-log))))))",
    )
    .expect("install window-scroll-functions hook");

    // A redisplay that keeps the start it was handed must not run the hook.
    engine.layout_frame_rust(&mut eval, frame_id);
    let quiet = eval
        .eval_str("(format \"%S\" neomacs-wsf-log)")
        .expect("read log")
        .as_str_owned()
        .expect("log string");
    assert_eq!(
        quiet, "nil",
        "a redisplay that inherits its window start reaches no \
         run_window_scroll_functions site in GNU"
    );

    // An explicit start (GNU `w->force_start`) must run it, with the window
    // and the committed start charpos as arguments. Point moves with the
    // start so this exercises the hook, not the separate question of what
    // GNU's force_start branch does to a point left outside the window.
    eval.eval_str("(goto-char 400)").expect("move point");
    eval.eval_form(Value::list(vec![
        Value::symbol("set-window-start"),
        Value::make_window(selected.0),
        Value::fixnum(400),
    ]))
    .expect("set an explicit window start");
    let FrameLayoutAttempt::Prepared(presentation) =
        engine.redisplay_frame_attempt(&mut eval, frame_id)
    else {
        panic!("redisplay aborted after scroll hook");
    };
    let presentation_id =
        neovm_core::window::geometry::PresentationId::new(presentation.presentation_id.get());
    eval.frame_manager_mut()
        .get_mut(frame_id)
        .expect("frame")
        .activate_display_presentation(presentation_id)
        .expect("activate presentation");
    let forced = eval
        .eval_str("(format \"%S\" neomacs-wsf-log)")
        .expect("read log")
        .as_str_owned()
        .expect("log string");
    assert_eq!(
        forced, "((#<window 1 on *scratch*> 400))",
        "GNU's force_start branch runs window-scroll-functions with the \
         forced start (src/xdisp.c:20728)"
    );
}

#[test]
fn every_row_carries_a_slot_for_its_own_line_terminator() {
    // Ledger 204, reproducing ledger 201 section 6 residual 1 at the row level.
    //
    // GNU's display line has a position for its own terminator, and every
    // screen column past the last glyph belongs to it.  Measured, GNU Emacs
    // 31.0.90, `-nw` in an 80-column pty, buffer "abcdef\nghijkl\n"
    // (scripts/eol-slot-audit.el):
    //
    //   row 0 by x: 1 2 3 4 5 6 7 7 7 7 ... 7      (the \n ending line 1 is 7)
    //   row 1 by x: 8 9 10 11 12 13 14 14 14 ...   (the \n ending line 2 is 14)
    //   posn-at-point at 7  -> (7 (6 . 0) (6 . 0))
    //
    // The mechanism is `display_line` recording `it->eol_pos = it->current.pos`
    // at `ITERATOR_AT_END_OF_LINE_P` (src/xdisp.c:26541) and `find_row_edges`
    // turning it into `row->maxpos = eol_pos + 1` (src/xdisp.c:25342-25344),
    // plus `move_it_in_display_line_to` breaking with `MOVE_NEWLINE_OR_CR`
    // BEFORE consuming the newline (src/xdisp.c:26663-26693), so the iterator
    // comes to rest ON the terminator whenever the goal is past the row.
    //
    // This port publishes one `DisplayPointSnapshot` per drawn glyph, and the
    // terminator draws none, so the row stops one position short: the slot
    // exists only at the accessible end of the buffer
    // (`row_lifecycle.rs`, `push_text_insertion_boundary` under
    // `tail.is_at_accessible_end()`).
    let trace = layout_trace_for_plain_text("abcdef\nghijkl\n");
    let snapshot = WindowDisplaySnapshot {
        points: trace.points,
        rows: trace.output_rows,
        ..WindowDisplaySnapshot::default()
    };

    let row_report = |row: i64| -> String {
        let points: Vec<(i64, i64)> = snapshot
            .points
            .iter()
            .filter(|point| point.row == row)
            .map(|point| (point.buffer_pos.as_i64(), point.col))
            .collect();
        format!("row {row} publishes (pos, col) {points:?}")
    };

    // Ledger 201's minimal reproduction, as a position query.
    for (terminator, row, col) in [(7_i64, 0_i64, 6_i64), (14, 1, 6)] {
        let slot = snapshot
            .point_for_buffer_pos(LispCharPos1::new(terminator))
            .unwrap_or_else(|| {
                panic!(
                    "GNU answers posn-at-point at the newline ending a line; this row has no \
                     slot for position {terminator}: {}",
                    row_report(row)
                )
            });
        assert_eq!(
            (slot.row, slot.col),
            (row, col),
            "the terminator slot of a line sits one column past its last glyph, \
             like GNU's eol_pos: {}",
            row_report(row)
        );
    }

    // The same fact from the other direction: every column past the last glyph
    // of a row belongs to that row's terminator, which is GNU's
    // "row 0 by x: 1,2,3,4,5,6,7,7,7,7" figure.
    let row0 = snapshot
        .rows
        .iter()
        .find(|row| row.row == 0)
        .expect("layout must publish row 0")
        .clone();
    let past_end = snapshot
        .point_at_coords(text_area_at(
            row0.end_x + 4 * row0.height,
            row0.y + row0.height / 2,
        ))
        .expect("a column inside the window always resolves to some position");
    assert_eq!(
        past_end.buffer_pos,
        LispCharPos1::new(7),
        "a column past everything row 0 draws belongs to row 0's own newline: {}",
        row_report(0)
    );
}

#[test]
fn an_empty_line_row_is_anchored_on_its_own_terminator() {
    // Ledger 204, widening.  A row with no glyphs of its own is the case GNU
    // spells out inside `display_line`: when the line end is reached with
    // `used_before == 0` it stamps the newline's own position onto the row's
    // first glyph, `row->glyphs[TEXT_AREA]->charpos = CHARPOS (it->position)`
    // (src/xdisp.c:26535-26537).  Measured, GNU Emacs 31.0.90, buffer
    // "abc\n\ndef\n" in an 80-column pty: `row 1 by x` is 5 in every column,
    // and `posn-at-point` at 5 answers `(5 (0 . 1) (0 . 1))`.
    let trace = layout_trace_for_plain_text("abc\n\ndef\n");
    let snapshot = WindowDisplaySnapshot {
        points: trace.points,
        rows: trace.output_rows,
        ..WindowDisplaySnapshot::default()
    };
    let rows: Vec<(i64, Option<i64>, Option<i64>)> = snapshot
        .rows
        .iter()
        .map(|row| {
            (
                row.row,
                row.start_buffer_pos.map(LispCharPos1::as_i64),
                row.end_buffer_pos.map(LispCharPos1::as_i64),
            )
        })
        .collect();

    let slot = snapshot
        .point_for_buffer_pos(LispCharPos1::new(5))
        .unwrap_or_else(|| {
            panic!("the empty line's own newline (position 5) has no slot; rows are {rows:?}")
        });
    assert_eq!(
        (slot.row, slot.col),
        (1, 0),
        "an empty line's row is anchored on the newline that is the whole of it; rows are {rows:?}"
    );
}

#[test]
fn a_coordinate_below_every_row_answers_the_end_of_the_buffer() {
    // Ledger 205, reproducing ledger 204 section 8 residual 1 at the row level.
    //
    // GNU answers a coordinate query from an ITERATOR, not from a row.
    // `buffer_posn_from_coords` runs `move_it_to (&it, -1, 0, *y, -1,
    // MOVE_TO_X | MOVE_TO_Y)` from the window's own start (src/dispnew.c:6278-6285),
    // and a Y below every line the buffer can produce makes that walk run out of
    // buffer rather than out of rows: `move_it_in_display_line_to` breaks with
    // `MOVE_POS_MATCH_OR_ZV` the moment `get_next_display_element` fails
    // ("Stop when ZV reached", src/xdisp.c:10251-10258), `move_it_to` takes its
    // `reached = 5` exit (src/xdisp.c:10984), and `*pos = it.current`
    // (src/dispnew.c:6353) is therefore point-max.  `make_lispy_position` has no
    // other answer to give: for `part == ON_TEXT` it always calls
    // `buffer_posn_from_coords` and sets `posn = make_fixnum (textpos)`
    // (src/keyboard.c:6014 and 6024).
    //
    // Measured, GNU Emacs 31.0.90, 80x24 pty, buffer "abcdef\nghijkl\n"
    // (scripts/below-content-audit.el):
    //
    //   row 2  x=0   (15 (0 . 2) (0 . 2) nil)     the drawn end-of-buffer row
    //   row 3  x=0   (15 (0 . 3) (0 . 2) nil)     below it -- STILL 15
    //   row 20 x=79  (15 (79 . 20) (79 . 2) nil)
    //
    // The third element is `posn-actual-col-row`, the raw (COL . ROW) cell
    // `buffer_posn_from_coords` fills from `it.hpos`/`it.vpos`
    // (src/dispnew.c:6432-6433).  It reports row **2** for a click on row 3:
    // the row the ITERATOR stopped on.  That is what distinguishes the answer
    // this port must give -- the last text row's own end -- from the answer a
    // port would give by emitting filler rows below the buffer and letting a
    // click land on one of them.
    let trace = layout_trace_for_plain_text("abcdef\nghijkl\n");
    let snapshot = WindowDisplaySnapshot {
        points: trace.points,
        rows: trace.output_rows,
        ..WindowDisplaySnapshot::default()
    };
    let rows: Vec<(i64, i64, i64, Option<i64>, Option<i64>)> = snapshot
        .rows
        .iter()
        .map(|row| {
            (
                row.row,
                row.y,
                row.height,
                row.start_buffer_pos.map(LispCharPos1::as_i64),
                row.end_buffer_pos.map(LispCharPos1::as_i64),
            )
        })
        .collect();
    let last_text_row = snapshot
        .rows
        .iter()
        .filter(|row| row.end_buffer_pos.is_some())
        .max_by_key(|row| row.y)
        .expect("layout must publish at least one row carrying buffer text")
        .clone();

    // One row below the last one that draws anything, and one further down
    // still: GNU answers point-max on both, in every column.
    for step in [1_i64, 2] {
        let y = last_text_row.y + step * last_text_row.height.max(1) + last_text_row.height / 2;
        for x in [0_i64, 5, 40] {
            let hit = snapshot
                .point_at_coords(text_area_at(x, y))
                .unwrap_or_else(|| {
                    panic!(
                        "GNU answers point-max for a coordinate below the last row that draws \
                     anything; this snapshot answers nothing at (x={x}, y={y}). \
                     rows (row, y, height, start, end) are {rows:?}"
                    )
                });
            assert_eq!(
                hit.buffer_pos,
                LispCharPos1::new(15),
                "a coordinate below every row belongs to the end of the buffer, \
                 which is where GNU's iterator comes to rest; rows are {rows:?}"
            );
            assert_eq!(
                hit.row, last_text_row.row,
                "GNU reports the row its ITERATOR stopped on, not the row that was \
                 clicked: posn-actual-col-row answers row 2 for a click on row 3"
            );
        }
    }
}

#[test]
fn an_empty_buffer_answers_its_only_position_at_every_row() {
    // Ledger 205, widening.  An empty buffer is the extreme of the same case:
    // ZV is point-min, the walk produces exactly one row, and every screen row
    // below it is below the end of the buffer.  Measured, GNU Emacs 31.0.90,
    // 80x24 pty, an empty buffer: all 21 body rows answer
    // `(1 (X . ROW) (X . 0) nil)` -- position 1 everywhere, with
    // `posn-actual-col-row` pinned to row 0.
    let trace = layout_trace_for_plain_text("");
    let snapshot = WindowDisplaySnapshot {
        points: trace.points,
        rows: trace.output_rows,
        ..WindowDisplaySnapshot::default()
    };
    let first_row = snapshot
        .rows
        .iter()
        .find(|row| row.end_buffer_pos.is_some())
        .expect("an empty buffer still draws one row")
        .clone();
    for step in [1_i64, 2, 3] {
        let y = first_row.y + step * first_row.height.max(1);
        let hit = snapshot
            .point_at_coords(text_area_at(0, y))
            .unwrap_or_else(|| {
                panic!("an empty buffer answers position 1 at every row; got nothing at y={y}")
            });
        assert_eq!(
            (hit.buffer_pos, hit.row),
            (LispCharPos1::new(1), first_row.row),
            "every row of an empty buffer belongs to its single position"
        );
    }
}

#[test]
fn a_window_full_of_text_has_a_row_at_every_coordinate() {
    // Ledger 205, the falsifiable half of
    // `a_coordinate_below_every_row_answers_the_end_of_the_buffer`.
    //
    // "Below the last row" must only ever mean the end of the BUFFER, never the
    // end of the WINDOW.  GNU distinguishes the two by which exit `move_it_to`
    // takes: `reached = 5/7/8` are the ZV breaks (src/xdisp.c:10984, 11030,
    // 11107) and `reached = 6` is "TO_Y is in this line"
    // (src/xdisp.c:10995 and 11023).  A window whose rows reach the bottom of its
    // text area can only take the second, so `BelowLastTextRow` must be
    // unreachable inside it -- otherwise the fix would answer point-max for a
    // coordinate that really has text on it.
    let text = (0..200).map(|i| format!("line {i}\n")).collect::<String>();
    let trace = layout_trace_for_plain_text(&text);
    let snapshot = WindowDisplaySnapshot {
        points: trace.points,
        rows: trace.output_rows,
        ..WindowDisplaySnapshot::default()
    };
    let text_rows: Vec<&DisplayRowSnapshot> = snapshot
        .rows
        .iter()
        .filter(|row| row.end_buffer_pos.is_some())
        .collect();
    assert!(
        text_rows.len() > 2,
        "the fixture must fill the window, or this guard asserts nothing: it \
         published {} text rows",
        text_rows.len()
    );
    let bottom = text_rows
        .iter()
        .map(|row| row.y + row.height.max(1))
        .max()
        .expect("text rows");
    for y in 0..bottom {
        assert!(
            matches!(
                snapshot.row_at_y(y),
                neovm_core::window::WindowSnapshotRowAtY::Within(_)
            ),
            "y={y} is above {bottom}, the bottom of a window whose text rows fill it, \
             so a published row must own it; the below-buffer arm is GNU's ZV exit \
             and is not reachable here"
        );
    }
    // And the row immediately below the last one is the arm under test, on the
    // same snapshot -- so the guard above is a statement about WHERE the arm
    // fires, not a claim that it never does.
    assert!(matches!(
        snapshot.row_at_y(bottom + 1),
        neovm_core::window::WindowSnapshotRowAtY::BelowLastTextRow(_)
    ));
}

/// GNU `handle_fontified_prop` runs when the display iterator reaches a visible
/// buffer position.  A character-count estimate cannot stand in for that
/// contract: outline/org folding can jump over an arbitrarily large hidden
/// span while the text after it remains in the same window.
#[test]
fn redisplay_fontifies_visible_text_after_a_large_invisible_span() {
    const PREFIX: &str = "visible\n";
    const HIDDEN_LINE: &str = "hidden\n";
    const HIDDEN_LINES: usize = 50_000;
    const TAIL: &str = "TAIL\n";

    let hidden = HIDDEN_LINE.repeat(HIDDEN_LINES);
    let text = format!("{PREFIX}{hidden}{TAIL}");
    let tail_charpos = PREFIX.chars().count() + hidden.chars().count();
    let tail_lisp_pos = tail_charpos + 1;
    let (mut eval, frame_id, _buf_id, window_id) = incr_editing_frame(&text, 360, 140);

    eval.eval_str(&format!(
        r#"
        (setq buffer-invisibility-spec t)
        (put-text-property {} {} 'invisible t)
        (setq redisplay-fontify-calls nil)
        (setq fontification-functions
              (list (lambda (start)
                      (setq redisplay-fontify-calls
                            (cons start redisplay-fontify-calls))
                      (let ((end (min (point-max) (+ start 80))))
                        (put-text-property start end 'fontified t)
                        (put-text-property start end 'font-lock-face
                                           'font-lock-warning-face)))))
        "#,
        PREFIX.chars().count() + 1,
        tail_lisp_pos,
    ))
    .expect("install folded region and fontification hook");
    let frame = eval.frame_manager_mut().get_mut(frame_id).expect("frame");
    let window = frame.find_window_mut(window_id).expect("window");
    let neovm_core::window::Window::Leaf { force_start, .. } = window else {
        panic!("selected window must be a leaf");
    };
    *force_start = true;

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let rows = trace_text_rows(&selected_window_layout_trace(&eval, &engine, frame_id));
    assert!(
        rows.iter().any(|row| row.contains("TAIL")),
        "the fixture must display text after the folded span, rows={rows:?}"
    );
    assert!(
        rows.iter().all(|row| !row.contains("hidden")),
        "the fixture must reach TAIL by eliding the large middle span, rows={rows:?}"
    );
    let live_start = match eval
        .frame_manager()
        .get(frame_id)
        .expect("frame")
        .find_window(window_id)
        .expect("window")
    {
        neovm_core::window::Window::Leaf { window_start, .. } => *window_start,
        other => panic!("selected window must remain a leaf, got {other:?}"),
    };
    assert_eq!(
        live_start,
        LispCharPos1::ONE,
        "the fixture must keep BOB and the post-fold tail in one visible window"
    );
    let tail_props = printed_eval_result(
        &mut eval,
        &format!(
            "(prin1-to-string (list (get-text-property {tail_lisp_pos} 'fontified) \
              (get-text-property {tail_lisp_pos} 'font-lock-face) \
              redisplay-fontify-calls))"
        ),
    );
    assert!(
        tail_props.starts_with("(t font-lock-warning-face"),
        "every visible buffer position must be fontified before its glyphs are accepted; \
         tail props/calls={tail_props}"
    );
}

/// Dashboard centers its banner with a `line-prefix` whose `display` value is
/// a list of two `(when FORM . SPEC)` clauses, `(display-graphic-p)` first and
/// its negation second.  GNU evaluates FORM (xdisp.c:6130-6160) and, for a
/// string object, stops at the first replacing spec (xdisp.c:6034-6040); the
/// engine used to take every non-nil FORM as true, so a graphic frame got
/// the text-terminal alignment.  The clauses are listed text-terminal first
/// here so that the first-replacing rule alone cannot pass the test: only
/// evaluating the forms selects the graphic clause.  The bare test
/// evaluator has no frame.el, so the graphic test is `framep` of the
/// selected frame (`neo` on the realized GUI frame), which
/// `display-graphic-p` reduces to.
#[test]
fn line_prefix_when_clauses_are_decided_by_evaluating_their_forms() {
    let mut eval = Context::new();
    let root = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("when-prefix", 640, 200, root);
    realize_test_gui_frame(&mut eval, frame_id);
    eval.eval_str(
        "(progn
           (insert \"X\\n\")
           (put-text-property 1 2 'line-prefix
             (propertize \" \" 'display
               '((when (not (eq (framep (selected-frame)) 'neo)) space :align-to 20)
                 (when (eq (framep (selected-frame)) 'neo) space :align-to 10)))))",
    )
    .expect("buffer with a conditional line prefix");
    assert!(
        eval.eval_str("(eq (framep (selected-frame)) 'neo)")
            .expect("framep")
            .is_truthy(),
        "the test frame must be graphic for the first clause to apply"
    );

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);

    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| {
            state
                .window_infos
                .iter()
                .any(|info| !info.is_minibuffer && info.window_id == entry.window_id)
        })
        .expect("root window matrix");
    let rows = enabled_window_row_texts_expanding_stretches(entry);
    let first = rows.first().expect("first row");
    assert_eq!(
        first.trim_end(),
        format!("{}X", " ".repeat(10)),
        "the graphic clause aligns X to column 10 (the text clause would give 20): {rows:?}"
    );
}

/// Under `display-line-numbers`, GNU measures a buffer `:align-to` from the
/// text after the line-number field: `(space :align-to 10)` ends ten columns
/// past the field and `center` at the field plus half of the remaining text
/// width (vanilla 31.0.90 oracle: field 28px, X at 98px, center at 294px in a
/// 560px text area).  Relative to the same layout without line numbers, the
/// field therefore shifts a numeric target by its full width and `center` by
/// half of it.  The row's origin is the field's right edge, so the pen must
/// not count the field's glyphs a second time.
#[test]
fn buffer_align_to_under_line_numbers_measures_from_the_field_edge() {
    let mut eval = Context::new();
    let root = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("lnum-align", 640, 200, root);
    realize_test_gui_frame(&mut eval, frame_id);
    eval.eval_str(
        "(progn
           (insert \" X\\n\")
           (put-text-property 1 2 'display '(space :align-to 10))
           (insert \" Y\\n\")
           (put-text-property 4 5 'display '(space :align-to center))
           (insert \"Z\\n\")
           (insert \"P\\n\")
           (put-text-property 9 10 'line-prefix
             (propertize \" \" 'display '(space :align-to 10)))
           (insert \"Q\\n\")
           (put-text-property 11 12 'line-prefix
             (propertize \" \" 'display '(space :align-to center))))",
    )
    .expect("buffer");
    let mut engine = LayoutEngine::new();
    let rows_of = |engine: &mut LayoutEngine, eval: &mut Context| -> Vec<String> {
        engine.layout_frame_rust(eval, frame_id);
        let state = engine
            .last_frame_display_state
            .as_ref()
            .expect("display state");
        let entry = state
            .window_matrices
            .iter()
            .find(|entry| {
                state
                    .window_infos
                    .iter()
                    .any(|info| !info.is_minibuffer && info.window_id == entry.window_id)
            })
            .expect("root window matrix");
        enabled_window_row_texts_expanding_stretches(entry)
    };

    let plain = rows_of(&mut engine, &mut eval);
    assert_eq!(plain[2].find('Z'), Some(0), "no field yet: {plain:?}");
    let x_plain = plain[0].find('X').expect("X");
    let y_plain = plain[1].find('Y').expect("Y");
    assert_eq!(x_plain, 10, "{plain:?}");
    assert_eq!(
        plain[3].find('P'),
        Some(10),
        "prefix-string numeric: {plain:?}"
    );
    assert_eq!(
        plain[4].find('Q'),
        Some(y_plain),
        "prefix-string center: {plain:?}"
    );

    eval.buffer_manager_mut()
        .get_mut(root)
        .expect("buffer")
        .set_buffer_local("display-line-numbers", Value::T);
    let numbered = rows_of(&mut engine, &mut eval);
    let field = numbered[2]
        .find('Z')
        .expect("Z after the line-number field");
    assert!(
        field > 0,
        "line numbers should occupy columns: {numbered:?}"
    );
    assert_eq!(
        numbered[0].find('X'),
        Some(x_plain + field),
        "a numeric target moves by the whole field: {numbered:?}"
    );
    assert_eq!(
        numbered[1].find('Y'),
        Some(y_plain + field / 2),
        "`center` moves by half the field (field + (width - field) / 2): {numbered:?}"
    );
    assert_eq!(
        numbered[3].find('P'),
        Some(10 + field),
        "a prefix string's numeric target moves by the whole field: {numbered:?}"
    );
    assert_eq!(
        numbered[4].find('Q'),
        Some(y_plain + field / 2),
        "a prefix string's `center` moves by half the field: {numbered:?}"
    );
}

/// A single clause whose FORM evaluates to nil must do nothing: on the old
/// structural rule it applied (the FORM is non-nil), so this is red without
/// evaluation whatever the first/last rule does.
#[test]
fn a_when_clause_whose_form_is_nil_leaves_the_prefix_out() {
    let mut eval = Context::new();
    let root = eval
        .buffer_manager()
        .current_buffer()
        .expect("current buffer")
        .id();
    let frame_id = eval
        .frame_manager_mut()
        .create_frame("when-nil", 640, 200, root);
    realize_test_gui_frame(&mut eval, frame_id);
    eval.eval_str(
        "(progn
           (insert \"X\\n\")
           (put-text-property 1 2 'line-prefix
             (propertize \" \" 'display
               '((when (not (eq (framep (selected-frame)) 'neo)) space :align-to 20)))))",
    )
    .expect("buffer with a false conditional line prefix");

    let mut engine = LayoutEngine::new();
    engine.layout_frame_rust(&mut eval, frame_id);
    let state = engine
        .last_frame_display_state
        .as_ref()
        .expect("display state");
    let entry = state
        .window_matrices
        .iter()
        .find(|entry| {
            state
                .window_infos
                .iter()
                .any(|info| !info.is_minibuffer && info.window_id == entry.window_id)
        })
        .expect("root window matrix");
    let rows = enabled_window_row_texts_expanding_stretches(entry);
    assert_eq!(
        rows.first().map(|row| row.trim_end()),
        Some(" X"),
        "the prefix string itself (one space) shows, its display spec does not: {rows:?}"
    );
}
